-- playbooks table
create table if not exists public.playbooks (
  id                 bigint generated always as identity primary key,
  ratio_key          text    not null,
  ratio_name         text    not null,
  health_tier        text    not null check (health_tier in ('critical','at_risk','healthy')),
  health_score_min   int     not null,
  health_score_max   int     not null,
  step_number        int     not null,
  step_title         text    not null,
  step_description   text    not null,
  timeframe          text    not null,
  effort             text    not null check (effort in ('low','medium','high')),
  impact             text    not null check (impact in ('low','medium','high')),
  category           text    not null,
  unique (ratio_key, health_tier, step_number)
);

alter table public.playbooks enable row level security;
create policy "anyone can read playbooks" on public.playbooks for select using (true);

create index if not exists playbooks_lookup_idx on public.playbooks (ratio_key, health_tier);

-- Seed data
insert into public.playbooks
  (ratio_key, ratio_name, health_tier, health_score_min, health_score_max,
   step_number, step_title, step_description, timeframe, effort, impact, category)
values
  ('grossMargin','Gross Profit Margin','critical',0,40,1,'Halt all new low-margin sales immediately','Identify and stop accepting orders below 20% gross margin. Calculate your break-even GM% using fixed costs divided by revenue and enforce it as a hard floor for all new business. Every below-threshold sale erodes cash faster than no sale at all.','immediate','low','high','revenue'),
  ('grossMargin','Gross Profit Margin','critical',0,40,2,'Perform emergency COGS line-item audit now','Pull three months of COGS invoices and categorise every line by supplier and volume. Identify the top five cost drivers that represent 80% of COGS. You cannot fix what you have not explicitly mapped.','immediate','medium','high','cost'),
  ('grossMargin','Gross Profit Margin','critical',0,40,3,'Call top three suppliers for emergency renegotiation','Contact your three largest suppliers within 48 hours and request a 10–15% temporary price reduction or extended payment terms. Present your volume commitment — most suppliers prefer a discounted deal to losing a client entirely.','week_1_2','medium','high','cost'),
  ('grossMargin','Gross Profit Margin','critical',0,40,4,'Reprice top three products by 8–15% immediately','Increase prices on your three highest-volume products right now. In most SME contexts, 70% of customers will not object to a meaningful price increase if value is communicated clearly. Test with a subset first, then roll out broadly.','week_1_2','low','high','revenue'),
  ('grossMargin','Gross Profit Margin','critical',0,40,5,'Eliminate the five lowest-margin product lines','Rank all products or services by gross margin percentage and remove the bottom five from your active offering. Redirect freed capacity, working capital, and sales attention toward higher-margin lines. Fewer but more profitable products is almost always right at this stage.','month_1','medium','high','revenue'),
  ('grossMargin','Gross Profit Margin','critical',0,40,6,'Cancel or pause all non-essential supplier contracts','Review every supplier and sub-contractor agreement and immediately pause any non-essential service. For essential suppliers, request a 60-90 day payment deferral. Target a 10% reduction in total COGS within 30 days.','month_1','medium','medium','cost'),
  ('grossMargin','Gross Profit Margin','critical',0,40,7,'Introduce cost-plus pricing model for all quotes','Build a simple pricing template that calculates the minimum acceptable price for each job or product. Set the floor at your break-even GM% plus a 10% buffer and make this a non-negotiable rule before any quote is issued.','month_1','medium','high','revenue'),
  ('grossMargin','Gross Profit Margin','critical',0,40,8,'Audit and eliminate production waste above 3% of COGS','Measure waste, scrap, and rework as a percentage of COGS. A 2–3% reduction in waste directly improves gross margin by the same amount. Assign accountability to one person and set a 30-day reduction target.','month_1_3','medium','medium','operations'),
  ('grossMargin','Gross Profit Margin','critical',0,40,9,'Redesign sales commissions to reward margin not revenue','Pay commissions on gross profit, not gross revenue. Salespeople paid on revenue will discount aggressively; salespeople paid on margin will protect pricing. Model the change using the last six months of sales data before implementing.','month_1_3','medium','high','people'),
  ('grossMargin','Gross Profit Margin','critical',0,40,10,'Assess vertical integration for your largest cost input','Identify your single largest COGS input and assess whether partial vertical integration — owning supply, manufacturing in-house, or a joint venture — could reduce cost by more than 15%. This structural play can permanently shift your margin floor.','month_3_6','high','high','structure'),
  ('grossMargin','Gross Profit Margin','at_risk',40,65,1,'Rank all products by gross margin percentage now','Generate a ranked list of all products or services by gross margin percentage. Identify the bottom 20% of SKUs — these are dragging your overall margin down. Document revenue and margin contribution of each before making changes.','immediate','low','medium','revenue'),
  ('grossMargin','Gross Profit Margin','at_risk',40,65,2,'Audit discount patterns by salesperson and customer','Pull all discounts, rebates, and credit notes issued in the last six months and attribute them by salesperson and customer account. Discounting is often the primary reason gross margin erodes quietly. Set a maximum 5% discount authority without manager approval.','immediate','low','medium','revenue'),
  ('grossMargin','Gross Profit Margin','at_risk',40,65,3,'Renegotiate your three largest supplier contracts now','Prepare a negotiation pack showing 12-month purchase history, payment record, and projected volumes. Request a 5–10% price reduction or volume rebate. Even modest reductions compound significantly at scale over 12 months.','week_1_2','medium','medium','cost'),
  ('grossMargin','Gross Profit Margin','at_risk',40,65,4,'Set and enforce minimum gross margin per product category','Define a minimum acceptable gross margin percentage for each product or service category and enforce it as pricing policy. Any sale below this floor requires sign-off from the owner or CFO. Communicate the rationale clearly to your sales team.','week_1_2','low','high','revenue'),
  ('grossMargin','Gross Profit Margin','at_risk',40,65,5,'Test a 5–8% price increase on lowest-elasticity products','Identify products where customers are least price-sensitive — essential, differentiated, or hard-to-replace offerings. Test a 5–8% price increase with 20% of customers and monitor churn over 30 days before rolling out broadly.','month_1','low','high','revenue'),
  ('grossMargin','Gross Profit Margin','at_risk',40,65,6,'Redirect 30% of sales effort toward highest-margin products','Analyse your sales team time allocation against the margin profile of what they sell. Use spiffs, targets, or simplified quoting tools to make high-margin products easier to sell. This mix shift improves overall margin without changing prices.','month_1','medium','medium','revenue'),
  ('grossMargin','Gross Profit Margin','at_risk',40,65,7,'Set up monthly gross margin reporting by product line','Create a simple dashboard tracking gross margin percentage by product line, updated monthly. Share this report with your sales and operations leads. What gets measured and discussed is what gets managed.','month_1','low','medium','operations'),
  ('grossMargin','Gross Profit Margin','at_risk',40,65,8,'Qualify two alternative suppliers for your largest cost input','Introduce competitive tension by qualifying two alternative suppliers for your largest COGS input. Even if you do not switch, having alternatives gives you leverage to negotiate better terms with your incumbent. Aim for a 5–8% cost reduction over 90 days.','month_1_3','medium','medium','cost'),
  ('grossMargin','Gross Profit Margin','at_risk',40,65,9,'Develop a premium tier for your best-selling product','Design a higher-value variant of your best-selling product with enhanced features or service levels that justifies a 15–25% premium. Premium tiers improve overall portfolio margin without disrupting your existing volume base.','month_1_3','medium','medium','revenue'),
  ('grossMargin','Gross Profit Margin','at_risk',40,65,10,'Explore outsourcing high-cost low-differentiation inputs','Assess whether any component of your production or delivery process can be outsourced to a specialist at lower cost than in-house. Focus on high-cost, low-differentiation activities. Even a 10% reduction in one major input line adds 2–3 percentage points to gross margin.','month_3_6','high','medium','cost'),
  ('grossMargin','Gross Profit Margin','healthy',65,100,1,'Benchmark gross margin against industry top quartile','Research gross margin ranges for your sector and compare your current margin to the top quartile, not the average. If you are below the top quartile, you have a specific improvement target to work toward.','immediate','low','low','operations'),
  ('grossMargin','Gross Profit Margin','healthy',65,100,2,'Introduce value-based pricing for premium customers','Review your top 20% of customers by profitability and assess whether your pricing reflects the full value you deliver. Value-based pricing anchored to customer outcomes is the most sustainable route to gross margins above 60% in most service businesses.','month_1','medium','medium','revenue'),
  ('grossMargin','Gross Profit Margin','healthy',65,100,3,'Formalise annual supplier renegotiation cycle','Set a calendar reminder to renegotiate all major supplier contracts annually, 90 days before renewal. Use your growth trajectory and payment history as leverage. Even 2–3% per year in input cost reduction compounds to a significant margin advantage over three years.','month_1','low','medium','cost'),
  ('grossMargin','Gross Profit Margin','healthy',65,100,4,'Launch cross-sell and upsell programme for existing customers','Design two or three upsell or cross-sell offerings for your existing customer base. Selling to existing customers costs 5–7x less than acquiring new ones, and higher basket values typically carry higher margins due to lower incremental fulfilment costs.','month_1_3','medium','medium','revenue'),
  ('grossMargin','Gross Profit Margin','healthy',65,100,5,'Develop a premium product tier with 25–40% price uplift','Create a high-value variant of your best-selling product commanding a 25–40% price premium. Premium tiers serve your most demanding customers and lift overall portfolio margin without disrupting the existing volume base.','month_1_3','high','high','revenue'),
  ('grossMargin','Gross Profit Margin','healthy',65,100,6,'Conduct six-monthly product rationalisation reviews','Formally review your catalogue every six months and retire any SKU generating below your target gross margin that has not grown in two consecutive periods. Product complexity in low-margin lines is a silent drag on operational efficiency.','month_1_3','low','medium','operations'),
  ('grossMargin','Gross Profit Margin','healthy',65,100,7,'Invest in automation to reduce direct labour in COGS','Map your production or service delivery process and identify the most labour-intensive steps. Research automation options that could reduce direct labour by 15–25%. Model the payback period before committing capital.','month_3_6','high','high','operations'),
  ('grossMargin','Gross Profit Margin','healthy',65,100,8,'Build a monthly gross margin waterfall report','Create a monthly waterfall chart showing gross margin movement from prior period — broken into pricing changes, volume changes, product mix shifts, and cost changes. This visibility allows proactive management before margin becomes a problem.','month_3_6','medium','low','operations'),
  ('grossMargin','Gross Profit Margin','healthy',65,100,9,'Negotiate exclusive or preferred supplier agreements','Pursue preferred supplier status or exclusivity agreements with two or three key suppliers in exchange for volume commitments. These agreements typically yield 5–12% better pricing than spot purchasing and reduce supply chain risk simultaneously.','month_3_6','medium','medium','cost'),
  ('grossMargin','Gross Profit Margin','healthy',65,100,10,'Build an intellectual property or brand moat to protect margin','Assess whether patents, trademarks, trade secrets, or strong brand positioning could protect your margin premium from competitive erosion. Gross margin above the industry median is only sustainable if defended by a durable competitive advantage.','year_1','high','high','structure'),
  ('directCostsRatio','Direct Cost Burden','critical',0,40,1,'Freeze all non-critical direct cost commitments today','Place an immediate hold on all new purchase orders and supplier commitments. Only release orders where production would stop without them. Your COGS-to-revenue ratio is unsustainable and every new commitment at current margins deepens the problem.','immediate','low','high','cost'),
  ('directCostsRatio','Direct Cost Burden','critical',0,40,2,'Map every direct cost to a specific product or job','Create a cost card for your top five revenue sources attributing every direct cost to specific output. This will reveal which products are consuming disproportionate COGS and whether your cost allocation assumptions are still accurate.','immediate','medium','high','cost'),
  ('directCostsRatio','Direct Cost Burden','critical',0,40,3,'Call top five suppliers for emergency price reduction','Schedule calls with your five largest suppliers this week and request an emergency 10–20% reduction or 90-day payment deferral. Frame it as a survival conversation — most long-term suppliers prefer a discounted relationship to losing a client.','week_1_2','medium','high','cost'),
  ('directCostsRatio','Direct Cost Burden','critical',0,40,4,'Eliminate all subcontractor markups above market rate','Identify every subcontracted service and calculate the markup as a proportion of COGS. Either renegotiate the rate, bring it in-house, or eliminate it. Subcontractor markup of 20–40% is common and often invisible until costs are explicitly mapped.','week_1_2','medium','medium','cost'),
  ('directCostsRatio','Direct Cost Burden','critical',0,40,5,'Suspend your two lowest-margin products immediately','Stop producing and selling your two lowest-margin offerings now. Use the freed capacity, cash, and management attention to scale your highest-margin products. A focused product range is almost always more profitable for an SME under cost pressure.','week_1_2','low','high','revenue'),
  ('directCostsRatio','Direct Cost Burden','critical',0,40,6,'Measure and cut material waste to below 3% of COGS','Assign a team member to physically audit your production process for waste, scrap, rework, and over-ordering. Set a target of reducing waste to below 3% of COGS within 30 days and document each waste source with its monetary value.','month_1','medium','medium','operations'),
  ('directCostsRatio','Direct Cost Burden','critical',0,40,7,'Implement purchase order approval for all COGS spend','Require a mandatory purchase order for all direct cost commitments above a low threshold. This single control prevents rogue spending, creates audit trails, and immediately reduces impulse procurement that inflates COGS.','month_1','low','medium','operations'),
  ('directCostsRatio','Direct Cost Burden','critical',0,40,8,'Pass direct cost increases through to customers immediately','Review all long-term contracts for escalation clauses. If your input costs have risen but prices have not followed, you are absorbing the inflation. Notify customers of price increases within 30 days with a clear cost-justification narrative.','month_1','medium','high','revenue'),
  ('directCostsRatio','Direct Cost Burden','critical',0,40,9,'Consolidate suppliers by 30% to earn volume discounts','Reduce your active supplier count by 30–40% and concentrate spend with preferred suppliers. Consolidated purchasing typically yields volume discounts of 5–15%. Review your supplier list and identify candidates for consolidation within 60 days.','month_1_3','medium','medium','cost'),
  ('directCostsRatio','Direct Cost Burden','critical',0,40,10,'Build monthly COGS variance reporting with owner accountability','Establish a monthly direct cost budget broken down by category — materials, labour, subcontractors, freight. Review actual versus budget monthly with your operations lead. Sustained discipline over direct costs separates healthy SMEs from struggling ones.','month_1_3','medium','high','operations'),
  ('directCostsRatio','Direct Cost Burden','at_risk',40,65,1,'Benchmark direct cost ratio against your industry peers','Research COGS-to-revenue ratios for your sector — manufacturing typically 50–70%, services 20–40%, retail 60–75%. Knowing where you stand relative to peers gives you a specific improvement target rather than an abstract goal.','immediate','low','medium','cost'),
  ('directCostsRatio','Direct Cost Burden','at_risk',40,65,2,'Isolate the three largest COGS cost drivers','Analyse your profit and loss and isolate the three largest categories within direct costs. For most businesses 80% of COGS sits in three to five line items. Concentrated effort on these categories will have a disproportionate impact on overall margin.','immediate','low','medium','cost'),
  ('directCostsRatio','Direct Cost Burden','at_risk',40,65,3,'Solicit competitive quotes from two alternative suppliers','For your two largest direct cost inputs, obtain formal quotes from alternative suppliers. You do not need to switch — benchmarking creates negotiating leverage with your current supplier. Even a 5% reduction in your top two COGS inputs can meaningfully shift direct cost ratio.','week_1_2','medium','medium','cost'),
  ('directCostsRatio','Direct Cost Burden','at_risk',40,65,4,'Measure and improve direct labour productivity by 10%','Calculate output per direct labour hour across your main production or service activities. Compare to prior periods and industry benchmarks. A 10% improvement in labour productivity reduces direct labour as a percentage of COGS by a similar proportion.','week_1_2','medium','medium','operations'),
  ('directCostsRatio','Direct Cost Burden','at_risk',40,65,5,'Implement formal procurement policy for all direct purchases','Establish written procurement rules: minimum two quotes for purchases above R10 000; annual renegotiation of supplier contracts above R50 000; mandatory purchase orders for all COGS commitments. Procurement discipline typically yields 5–10% cost reduction within six months.','month_1','low','medium','operations'),
  ('directCostsRatio','Direct Cost Burden','at_risk',40,65,6,'Reduce waste rate to below 2% of direct material costs','Measure your current waste and scrap rate as a percentage of total direct material costs. Implement a visual management system to flag and record waste daily. Target a reduction to below 2% within 90 days and track progress weekly.','month_1','medium','medium','operations'),
  ('directCostsRatio','Direct Cost Burden','at_risk',40,65,7,'Negotiate annual volume rebates with top three suppliers','Propose annual volume rebates to your three largest suppliers — typically 2–5% of spend returned at year-end if volume commitments are met. These rebates are common but rarely offered proactively; you need to request them explicitly.','month_1','medium','medium','cost'),
  ('directCostsRatio','Direct Cost Burden','at_risk',40,65,8,'Align direct labour scheduling with revenue-generating activity','Analyse your direct labour roster against production or delivery volume. Identify periods of low utilisation and shift scheduling to align labour costs more closely with revenue activity. This reduces the fixed component of what should be a variable cost.','month_1_3','medium','medium','people'),
  ('directCostsRatio','Direct Cost Burden','at_risk',40,65,9,'Run a lean improvement sprint on your highest-cost process','Select your single highest direct-cost process and apply a focused lean methodology: map the steps, identify non-value-adding activities, and eliminate them. A 2-week lean sprint can typically reduce process costs by 10–20%.','month_1_3','high','medium','operations'),
  ('directCostsRatio','Direct Cost Burden','at_risk',40,65,10,'Lock in fixed-price supplier agreements for cost certainty','For your three largest cost inputs, assess whether a 12–24 month fixed-price agreement provides savings versus spot purchasing. Price certainty also aids financial planning and reduces the risk of margin compression from input cost inflation.','month_3_6','medium','medium','cost'),
  ('directCostsRatio','Direct Cost Burden','healthy',65,100,1,'Document cost management practices as standard procedures','Write your current direct cost controls, supplier management practices, and procurement rules as formal SOPs. This protects current performance from erosion when staff change and provides a baseline for continuous improvement.','month_1','low','low','operations'),
  ('directCostsRatio','Direct Cost Burden','healthy',65,100,2,'Build a direct cost early warning system','Set up monthly monitoring with an alert threshold — trigger a review if COGS/Revenue rises more than 2 percentage points above your current level in any single month. Early detection prevents small cost increases from compounding into margin crises.','month_1','low','medium','risk'),
  ('directCostsRatio','Direct Cost Burden','healthy',65,100,3,'Develop strategic sourcing partnerships with key suppliers','Move your most critical suppliers from transactional to strategic relationships. Share your growth plans and purchase forecasts in exchange for preferred pricing, priority supply, and joint cost reduction initiatives. Strategic partnerships can yield 8–15% long-term cost advantages.','month_1_3','medium','medium','cost'),
  ('directCostsRatio','Direct Cost Burden','healthy',65,100,4,'Invest in technology to reduce direct labour intensity','Identify your most labour-intensive direct cost activities and research technology that could automate or semi-automate them. Calculate ROI based on labour savings over three years. In many SME contexts, payback periods of 18–36 months are achievable.','month_1_3','high','high','operations'),
  ('directCostsRatio','Direct Cost Burden','healthy',65,100,5,'Explore joint purchasing with complementary peer businesses','Connect with two or three non-competing businesses in your sector to negotiate collective purchasing with shared suppliers. Pooled procurement achieves pricing typically reserved for much larger buyers, reducing direct costs by 5–10% without changing your model.','month_3_6','medium','medium','cost'),
  ('directCostsRatio','Direct Cost Burden','healthy',65,100,6,'Create a staff cost-reduction suggestion programme','Launch a formal suggestion programme for operations staff with financial rewards for implemented cost-reduction ideas. Frontline workers have the best insights into waste and inefficiency. Target a 1–2% annual improvement in direct cost ratio through this channel.','month_3_6','medium','medium','people'),
  ('directCostsRatio','Direct Cost Burden','healthy',65,100,7,'Conduct make-versus-buy analysis for major cost inputs','Formally analyse your largest direct cost inputs to assess whether in-house production, partial manufacture, or vertical integration could reduce cost below current market pricing. Revisit this analysis every two to three years as your scale evolves.','month_3_6','high','high','structure'),
  ('directCostsRatio','Direct Cost Burden','healthy',65,100,8,'Include direct cost benchmarking in annual business planning','Make an explicit direct cost benchmarking exercise part of your annual planning cycle. Compare your COGS structure against industry data and best-in-class operators. Use benchmarks to set your cost targets for the coming year.','month_3_6','low','low','operations'),
  ('directCostsRatio','Direct Cost Burden','healthy',65,100,9,'Assess local sourcing to reduce supply chain cost and risk','If any major direct cost inputs are imported or sourced from distant suppliers, assess local or regional alternatives. This reduces currency exposure, freight costs, and supply disruption risk — all contributors to direct cost stability and predictability.','month_3_6','high','medium','risk'),
  ('directCostsRatio','Direct Cost Burden','healthy',65,100,10,'Publish a three-year direct cost improvement roadmap','Create a structured plan to reduce your direct cost ratio by a further 3–5 percentage points over three years. Identify the specific initiatives — technology, supplier strategy, process improvement, and product mix — driving each percentage point. Review quarterly.','year_1','medium','high','structure'),
  ('fixedCostRatio','Fixed Cost Burden','critical',0,40,1,'List every fixed cost and classify it immediately','Within 24 hours write out every fixed cost with its monthly amount, contract end date, and whether it is essential to operations. This mapping is your cost reduction hit list. Do not attempt to cut costs without completing this exercise first.','immediate','low','high','cost'),
  ('fixedCostRatio','Fixed Cost Burden','critical',0,40,2,'Cancel or pause all non-essential fixed-cost contracts now','Immediately cancel or pause every fixed cost that is not critical to generating revenue — subscriptions, memberships, non-essential software, discretionary retainers. Target a 20% reduction in fixed costs within the first two weeks.','immediate','low','high','cost'),
  ('fixedCostRatio','Fixed Cost Burden','critical',0,40,3,'Negotiate rent reduction or rental holiday with landlord','Contact your landlord this week and request a 3–6 month rental reduction or deferral. South African commercial landlords faced significant vacancies post-2020 and many will negotiate rather than lose a tenant. A 20% reduction for 6 months saves meaningful cash.','week_1_2','medium','high','cost'),
  ('fixedCostRatio','Fixed Cost Burden','critical',0,40,4,'Freeze all hiring and implement salary review freeze','Place an immediate freeze on all new hires. Review all employment contracts for salary review clauses and defer discretionary increases. Payroll is typically the largest fixed cost in a service business — protecting it from further growth is essential in a crisis.','immediate','low','high','people'),
  ('fixedCostRatio','Fixed Cost Burden','critical',0,40,5,'Calculate your operational break-even revenue today','Divide total monthly fixed costs by your gross margin percentage to find minimum monthly revenue required to achieve positive operating margin. This number must drive all revenue decisions for the next 90 days.','week_1_2','low','high','operations'),
  ('fixedCostRatio','Fixed Cost Burden','critical',0,40,6,'Renegotiate financing and lease payments with your bank','Contact your bank or asset finance provider and request a 3–6 month capital repayment holiday or payment restructuring. Banks are significantly more flexible with businesses that proactively contact them before missing payments.','week_1_2','medium','medium','structure'),
  ('fixedCostRatio','Fixed Cost Burden','critical',0,40,7,'Convert fixed costs to variable costs wherever possible','Identify fixed cost lines that could be restructured as variable or output-based — switch from salaried roles to contractor arrangements, fixed retainers to usage-based pricing, or negotiate revenue-share agreements with suppliers.','month_1','high','high','structure'),
  ('fixedCostRatio','Fixed Cost Burden','critical',0,40,8,'Generate revenue to absorb fixed costs via capacity utilisation','Drive revenue using current resources: reactivate dormant customers, cross-sell to existing accounts, accelerate the pipeline on deals near closing. Additional revenue from existing capacity adds to operating margin at a very high incremental rate since fixed costs are already covered.','month_1','medium','high','revenue'),
  ('fixedCostRatio','Fixed Cost Burden','critical',0,40,9,'Sublease unused office or production space immediately','If you have spare office, warehouse, or production space, list it for sublease immediately. Even recovering 30–50% of your rental cost through a sublease is meaningful cash recovery. Many Cape Town and Johannesburg SMEs find subtenants within 4–8 weeks.','month_1','medium','medium','cash'),
  ('fixedCostRatio','Fixed Cost Burden','critical',0,40,10,'Build a 12-month fixed cost reduction plan with milestones','Once immediate cuts are made, build a structured plan for the next 12 months identifying each fixed cost contract due for renewal, the target reduction percentage, and the responsible owner. Sustained management of fixed costs requires a plan, not just a reaction.','month_1_3','medium','high','structure'),
  ('fixedCostRatio','Fixed Cost Burden','at_risk',40,65,1,'Calculate your operational break-even revenue today','Divide total monthly fixed costs by your gross margin percentage to get the revenue needed just to cover fixed costs. Compare this to your current and forecasted monthly revenue. The gap — positive or negative — defines your urgency and your target.','immediate','low','medium','operations'),
  ('fixedCostRatio','Fixed Cost Burden','at_risk',40,65,2,'Audit fixed cost contracts for renewal opportunities','List all fixed cost contracts with renewal or renegotiation dates. Contracts coming up for renewal in the next six months should be renegotiated proactively. Target a 10–15% reduction using your payment history as leverage.','immediate','low','medium','cost'),
  ('fixedCostRatio','Fixed Cost Burden','at_risk',40,65,3,'Cancel the five lowest-value fixed-cost subscriptions','Review every software subscription, service contract, and ongoing fixed commitment. Cancel the five that deliver the least value relative to their cost. Most businesses are paying for three to five services that are rarely or never used.','week_1_2','low','medium','cost'),
  ('fixedCostRatio','Fixed Cost Burden','at_risk',40,65,4,'Negotiate office or facility costs down by 10–15%','Approach your landlord or facilities provider with a market comparison of current rental rates in your area and a proposal for a rent reduction or lease restructuring. The risk of losing a tenant is a powerful incentive for most commercial landlords to negotiate.','week_1_2','medium','medium','cost'),
  ('fixedCostRatio','Fixed Cost Burden','at_risk',40,65,5,'Implement a revenue growth plan to dilute fixed cost ratio','The fixed cost ratio improves both by reducing costs and by growing revenue. Identify the fastest route to a 10–15% revenue increase using existing capacity — pricing, activation of dormant customers, or new channels — without adding fixed costs.','month_1','medium','high','revenue'),
  ('fixedCostRatio','Fixed Cost Burden','at_risk',40,65,6,'Review headcount for roles without clear revenue linkage','Map every staff role to a revenue or operational outcome. Roles without a clear link to value creation should be restructured, reassigned, or eliminated. This is about ensuring every fixed cost has a visible return.','month_1','medium','medium','people'),
  ('fixedCostRatio','Fixed Cost Burden','at_risk',40,65,7,'Explore shared services or outsourcing for non-core functions','Identify non-core functions — accounting, HR, IT support, legal — where outsourcing to a shared services provider would cost less than maintaining fixed in-house headcount. In South Africa, outsourced bookkeeping costs R3 000–R8 000 per month versus R20 000+ in-house.','month_1_3','medium','medium','cost'),
  ('fixedCostRatio','Fixed Cost Burden','at_risk',40,65,8,'Replace fixed retainers with output-based agreements','Review all fixed monthly retainer arrangements and propose converting them to output-based or project-based billing. This converts a fixed cost to a variable one and aligns supplier payment with actual value delivered.','month_1_3','medium','medium','structure'),
  ('fixedCostRatio','Fixed Cost Burden','at_risk',40,65,9,'Benchmark fixed cost structure against similar-sized businesses','Research what fixed cost ratios are typical for businesses at your revenue scale in your sector. Industry associations and financial benchmarking databases publish this data. Use the comparison to identify which specific fixed cost categories are above peer levels.','month_1_3','low','low','operations'),
  ('fixedCostRatio','Fixed Cost Burden','at_risk',40,65,10,'Build a scalable cost structure ahead of revenue growth','As you plan growth, design your fixed cost structure to scale at a lower rate than revenue. Adopt variable or commission-based compensation, flexible facility arrangements, and cloud-based or usage-priced technology — so your fixed cost ratio improves as you grow.','month_3_6','high','high','structure'),
  ('fixedCostRatio','Fixed Cost Burden','healthy',65,100,1,'Review fixed cost structure for efficiency every six months','Schedule a semi-annual fixed cost review assessing each major expense for value delivered. Cancel or renegotiate any fixed cost that cannot be directly linked to a revenue or operational outcome. This discipline prevents healthy cost structures from drifting upward through inertia and contract auto-renewals.','month_1','low','medium','cost'),
  ('fixedCostRatio','Fixed Cost Burden','healthy',65,100,2,'Set a fixed cost ceiling as percentage of revenue','Define a maximum acceptable fixed cost ratio for your business and enforce it as a financial policy. If fixed costs approach the ceiling as revenue fluctuates, trigger a review before the ratio deteriorates. Having a ceiling converts good performance from luck into managed discipline.','month_1','low','medium','operations'),
  ('fixedCostRatio','Fixed Cost Burden','healthy',65,100,3,'Negotiate multi-year fixed cost agreements at current rates','Lock in your current favourable fixed cost rates with landlords, key suppliers, and service providers through multi-year agreements. Securing 2–3 year terms now protects you from inflation-driven cost increases and preserves your current ratio. Offer prompt payment or volume commitments in exchange for rate certainty.','month_1','medium','medium','cost'),
  ('fixedCostRatio','Fixed Cost Burden','healthy',65,100,4,'Build an operating leverage model before any headcount addition','Before adding any fixed headcount, model the revenue required to maintain your current fixed cost ratio. Each new permanent hire increases your break-even revenue requirement. This model ensures growth-driven hiring does not silently erode your cost structure.','month_1_3','low','high','people'),
  ('fixedCostRatio','Fixed Cost Burden','healthy',65,100,5,'Transition non-core roles to variable cost arrangements','Identify functions that are not core to your competitive advantage — IT support, HR administration, marketing execution — and assess whether outsourcing or contractor arrangements would reduce fixed exposure. Even partial conversion of 10–15% of fixed payroll to variable cost meaningfully improves resilience during revenue dips.','month_1_3','medium','medium','structure'),
  ('fixedCostRatio','Fixed Cost Burden','healthy',65,100,6,'Stress-test your cost structure against a 20% revenue decline','Model what happens to profitability and cash if revenue drops 20% for three consecutive months. Identify which fixed costs become unsustainable and what decisions you would make first. Completing this exercise in advance of a crisis means you act faster and more decisively if it occurs.','month_1_3','low','high','risk'),
  ('fixedCostRatio','Fixed Cost Burden','healthy',65,100,7,'Invest fixed cost savings into revenue-generating capacity','Where fixed cost reductions are achieved, redirect the savings into sales, marketing, or product development rather than allowing them to be absorbed elsewhere. This compounds the benefit — lower fixed cost ratio AND higher revenue — creating a virtuous cycle of improving operating leverage.','month_3_6','medium','high','revenue'),
  ('fixedCostRatio','Fixed Cost Burden','healthy',65,100,8,'Benchmark your fixed cost ratio against top-quartile industry peers','Identify the fixed cost ratio of the top-quartile performers in your sector using industry reports, financial benchmarking databases, or peer comparisons through your industry association. Even a healthy ratio may have room to improve if the best operators in your sector are running leaner.','month_3_6','low','low','operations'),
  ('fixedCostRatio','Fixed Cost Burden','healthy',65,100,9,'Design your next growth phase on a scalable cost architecture','As you plan your next stage of growth, deliberately architect fixed costs to scale at a slower rate than revenue. Adopt cloud-based or usage-priced technology, flexible facility arrangements, and performance-linked compensation structures so that operating leverage improves as revenue grows.','month_3_6','high','high','structure'),
  ('fixedCostRatio','Fixed Cost Burden','healthy',65,100,10,'Include fixed cost ratio in your annual board or owner review','Make fixed cost ratio a standing agenda item in your annual strategic review alongside revenue growth and gross margin. Presenting it alongside operating leverage trends over three to five years gives you and your stakeholders a clear picture of whether the business is becoming more or less scalable over time.','year_1','low','medium','operations'),
  ('interestBurden','Interest Burden','critical',0,40,1,'Calculate your exact interest coverage ratio today','Divide EBIT by your total monthly interest expense to determine how many times your earnings cover your interest obligations. A ratio below 1.5x means you are at serious risk of not servicing debt from operations. This number must be known before any other decision is made.','immediate','low','high','risk'),
  ('interestBurden','Interest Burden','critical',0,40,2,'Call your bank before you miss a payment','Contact your primary lender this week and request an urgent meeting to discuss your debt position. Banks are dramatically more willing to restructure debt for clients who approach them proactively than for those who miss payments first. Prepare a 13-week cash flow forecast and a proposed repayment plan before the call.','immediate','medium','high','structure'),
  ('interestBurden','Interest Burden','critical',0,40,3,'Request a capital repayment holiday on all term loans','Formally apply for a 3–6 month capital repayment holiday across all term debt facilities. Most South African banks including ABSA, Standard Bank, Nedbank, and FNB have formal business distress restructuring programmes. A capital holiday reduces cash outflow while you restore EBIT — interest still accrues but the principal pause is critical relief.','week_1_2','medium','high','cash'),
  ('interestBurden','Interest Burden','critical',0,40,4,'Identify and sell non-core assets to reduce debt load','List every asset on your balance sheet that is not essential to generating current revenue — surplus equipment, unused vehicles, investment properties, dormant inventory. Liquidating even one significant asset can materially reduce your debt principal and the interest burden it generates. Target a 15–20% reduction in total debt within 90 days.','week_1_2','medium','high','structure'),
  ('interestBurden','Interest Burden','critical',0,40,5,'Halt all new debt-funded capital expenditure immediately','Place an immediate freeze on any new asset purchases, lease agreements, or capital commitments that would increase interest-bearing debt. Every additional rand of debt at this stage deepens the interest burden. Only reinstate capital expenditure once interest coverage exceeds 2.5x on a trailing three-month basis.','immediate','low','high','cost'),
  ('interestBurden','Interest Burden','critical',0,40,6,'Explore refinancing high-rate debt at lower interest rates','List every debt facility with its current interest rate and remaining term. Identify the highest-rate facilities and approach alternative lenders — including SEFA, IDC, or alternative finance providers — for refinancing at lower rates. Even reducing your weighted average cost of debt by 2–3 percentage points meaningfully reduces monthly interest expense.','month_1','high','high','structure'),
  ('interestBurden','Interest Burden','critical',0,40,7,'Drive EBIT growth to improve interest coverage from above','Interest burden improves both by reducing debt and by growing EBIT. Identify the fastest available route to a 20% EBIT improvement — price increases, cost cuts, or volume growth using existing capacity. A business with rising EBIT can service higher debt loads; the ratio improves from both ends simultaneously.','month_1','medium','high','revenue'),
  ('interestBurden','Interest Burden','critical',0,40,8,'Convert short-term debt to long-term to reduce monthly pressure','If you have short-term facilities — overdrafts, bridging loans, credit cards — that are carrying long-term balances, negotiate their conversion to term loans with fixed monthly repayments over 3–5 years. This spreads the repayment burden, reduces monthly cash pressure, and often lowers your effective interest rate.','month_1_3','medium','medium','structure'),
  ('interestBurden','Interest Burden','critical',0,40,9,'Explore equity injection to permanently reduce debt quantum','Consider whether a shareholder loan, external equity investor, or venture debt at lower rates could replace a portion of your high-cost bank debt. Equity does not carry interest. Even a partial equity injection that eliminates your highest-rate facility can shift the interest burden ratio from critical to manageable within one quarter.','month_1_3','high','high','structure'),
  ('interestBurden','Interest Burden','critical',0,40,10,'Build a 24-month debt reduction roadmap with milestones','Once the immediate crisis is stabilised, create a structured 24-month plan targeting specific debt balances for elimination in priority order — highest rate first. Assign monthly surplus cash flow to debt reduction above minimum repayments. Reaching an interest coverage ratio of 3.0x or above should be your 18-month milestone.','month_3_6','medium','high','structure'),
  ('interestBurden','Interest Burden','at_risk',40,65,1,'Map every debt facility with rate, term, and monthly cost','Create a single-page debt register listing every facility — its outstanding balance, interest rate, monthly repayment, and maturity date. Most SME owners do not have this picture clearly in front of them. You cannot manage what you have not explicitly mapped, and this register is the foundation of every subsequent step.','immediate','low','medium','structure'),
  ('interestBurden','Interest Burden','at_risk',40,65,2,'Calculate interest coverage ratio and set a 3.0x target','Divide your trailing three-month average EBIT by your monthly interest expense to calculate your current coverage ratio. The widely accepted minimum safe level for an SME is 2.0x; a comfortable level is 3.0x or above. Use 3.0x as your improvement target and track monthly progress.','immediate','low','medium','risk'),
  ('interestBurden','Interest Burden','at_risk',40,65,3,'Renegotiate your highest-rate facility with your bank','Take your debt register to your bank and specifically request a rate review on your highest-rate facility. If your business has been performing and making payments on time, you have a legitimate case for a 1–2 percentage point reduction. In the current South African interest rate environment, proactive renegotiation is often successful.','week_1_2','medium','medium','cost'),
  ('interestBurden','Interest Burden','at_risk',40,65,4,'Stop using revolving credit for long-term funding needs','Revolving credit facilities such as overdrafts and credit lines carry higher effective rates than term loans and are designed for short-term cash flow bridging, not long-term funding. If any revolving balance has been outstanding for more than six months, convert it to a term loan with a structured repayment schedule.','week_1_2','low','medium','structure'),
  ('interestBurden','Interest Burden','at_risk',40,65,5,'Allocate 20% of monthly free cash flow to debt reduction','Define a monthly debt reduction payment above your minimum repayments and automate it. Target 20% of free cash flow — cash remaining after operations and essential capex — directed to your highest-rate facility first. This approach, known as the avalanche method, minimises total interest paid over time.','month_1','low','medium','cash'),
  ('interestBurden','Interest Burden','at_risk',40,65,6,'Improve EBIT margin to grow coverage from the top line','Interest burden is a ratio of EBIT to interest, so improving EBIT directly improves the ratio without reducing debt. Identify two or three specific actions that could improve your EBIT margin by 3–5 percentage points over the next 90 days — a price increase, a cost reduction, or a product mix shift toward higher-margin lines.','month_1','medium','high','revenue'),
  ('interestBurden','Interest Burden','at_risk',40,65,7,'Establish a debt ceiling policy before any new borrowing','Define a maximum debt-to-EBITDA ratio — typically 2.5x to 3.0x for a healthy SME — and enforce it as a financial governance rule. Any borrowing that would breach this ceiling requires explicit owner or board approval. This prevents the gradual debt accumulation that erodes interest burden ratios over time.','month_1','low','medium','risk'),
  ('interestBurden','Interest Burden','at_risk',40,65,8,'Explore SEFA or IDC funding to replace commercial bank debt','The Small Enterprise Finance Agency (SEFA) and the Industrial Development Corporation (IDC) offer SME funding at concessionary rates — often 2–5% below commercial bank rates. If your business qualifies, refinancing a portion of your commercial debt through these institutions can meaningfully reduce your interest burden.','month_1_3','high','medium','structure'),
  ('interestBurden','Interest Burden','at_risk',40,65,9,'Assess whether asset finance is cheaper than working capital debt','If you are using general working capital facilities to fund fixed assets, restructure this into dedicated asset finance — hire purchase or finance leases typically carry lower rates and match the asset useful life. Mismatching short-term debt with long-term assets is one of the most common causes of an elevated interest burden in SMEs.','month_1_3','medium','medium','structure'),
  ('interestBurden','Interest Burden','at_risk',40,65,10,'Model the interest burden impact of your next growth investment','Before any new debt-funded investment, build a simple model showing the incremental EBIT the investment generates and whether it exceeds the incremental interest cost within 12 months. Only proceed with investments where the EBIT return is at least 3x the annual interest cost. This discipline prevents well-intentioned growth from worsening the ratio.','month_3_6','medium','medium','risk'),
  ('interestBurden','Interest Burden','healthy',65,100,1,'Document your current debt structure and cost of capital','Prepare a clean debt register showing every facility, its rate, term, security, and monthly cost. Calculate your weighted average cost of debt. This baseline document enables you to make rational financing decisions and protects against the gradual accumulation of sub-optimal debt that erodes a healthy interest burden over time.','immediate','low','low','structure'),
  ('interestBurden','Interest Burden','healthy',65,100,2,'Set a debt-to-EBITDA ceiling and review it annually','Formalise your maximum acceptable leverage level as a policy — most healthy SMEs target debt-to-EBITDA below 2.5x. Review your actual position against this ceiling annually or after any significant borrowing event. Having a policy prevents opportunistic borrowing from silently degrading your interest burden ratio.','month_1','low','medium','risk'),
  ('interestBurden','Interest Burden','healthy',65,100,3,'Use your strong coverage ratio to negotiate better facility rates','A healthy interest coverage ratio is a negotiating asset. Approach your bank with your trailing 12-month financials and formally request a rate review across all facilities. Lenders price risk — a business with 4x+ coverage is a lower risk than their pricing may reflect, and you have grounds to request a 0.5–1.5% rate reduction.','month_1','low','medium','cost'),
  ('interestBurden','Interest Burden','healthy',65,100,4,'Stress-test interest coverage against a 30% EBIT decline','Model your interest coverage ratio if EBIT dropped 30% due to a revenue shock, cost spike, or market disruption. If coverage falls below 1.5x in this scenario, you carry more debt risk than your healthy score suggests. Use this stress test to determine whether additional debt reduction or revenue diversification is warranted.','month_1','low','medium','risk'),
  ('interestBurden','Interest Burden','healthy',65,100,5,'Evaluate whether debt can fund accretive growth investments','With a healthy interest burden, you have borrowing capacity that underperforming competitors may not. Identify one or two growth investments — equipment, acquisition, market expansion — where the projected return on investment exceeds your cost of debt by at least 3x. Disciplined use of debt at this stage is a competitive advantage.','month_1_3','medium','high','structure'),
  ('interestBurden','Interest Burden','healthy',65,100,6,'Build an interest rate sensitivity model for your debt portfolio','If any of your debt is on variable rates, model the impact of a 1%, 2%, and 3% interest rate increase on your monthly interest expense and coverage ratio. South African prime rate has historically moved by 200–300 basis points in a single cycle. Knowing your exposure allows you to hedge or fix rates proactively.','month_1_3','medium','medium','risk'),
  ('interestBurden','Interest Burden','healthy',65,100,7,'Explore fixing variable rate debt ahead of rate cycle peaks','If the South African Reserve Bank is in a rate-hiking cycle, assess whether fixing your variable rate debt to a fixed rate provides protection. Fixed-rate facilities carry a slight premium but provide certainty — and prevent a rate cycle from converting a healthy interest burden into an at-risk position within 12 months.','month_1_3','medium','medium','structure'),
  ('interestBurden','Interest Burden','healthy',65,100,8,'Establish a revolving credit facility as emergency reserve','If you do not already have an undrawn revolving credit facility, negotiate one now while your financials are strong. Having R500 000 to R2 million in undrawn credit available costs very little when unused but provides critical liquidity insurance against unexpected cash shortfalls. Banks approve facilities to healthy businesses, not distressed ones.','month_3_6','medium','high','cash'),
  ('interestBurden','Interest Burden','healthy',65,100,9,'Optimise debt maturity profile to avoid refinancing cliff risk','Review when your major debt facilities mature. If more than 40% of your total debt matures in the same 12-month window, you face refinancing cliff risk. Stagger maturities now by refinancing one facility early to spread renewal risk across different years.','month_3_6','medium','medium','structure'),
  ('interestBurden','Interest Burden','healthy',65,100,10,'Develop a capital structure strategy as part of annual planning','Include a formal capital structure review in your annual planning cycle — assess the right mix of debt, equity, and retained earnings to fund your three-year growth plan at the lowest cost and risk. A deliberate capital structure is one of the most underutilised levers in SME financial management.','year_1','medium','high','structure'),
  ('netMargin','Net Margin','critical',0,40,1,'Identify whether loss is operating or financing driven','Compare your operating margin to your net margin. If operating margin is positive but net margin is negative, your problem is debt cost or tax — not operations. If both are negative, you have a fundamental trading problem. This distinction determines your entire recovery strategy and must be answered before any other action.','immediate','low','high','operations'),
  ('netMargin','Net Margin','critical',0,40,2,'Stop all cash outflows not essential to revenue generation','Issue an immediate spending freeze on all non-revenue-generating cash outflows. Every payment must be approved by the owner and tested against one question: does this directly protect or generate revenue this month? Discretionary spending at a critical net margin accelerates the path to insolvency.','immediate','low','high','cash'),
  ('netMargin','Net Margin','critical',0,40,3,'Build a 13-week cash flow survival forecast today','Create a week-by-week cash forecast for the next 13 weeks listing every confirmed receipt and every committed payment. Use only confirmed receivables — not forecasted sales. This forecast tells you exactly when you will run out of cash and how much time you have to act. Update it every Monday without exception.','immediate','medium','high','cash'),
  ('netMargin','Net Margin','critical',0,40,4,'Raise prices on your top five products within seven days','Increase prices on your five highest-volume products or services by 10–20% immediately. Net margin deterioration is often a pricing problem as much as a cost problem. Even modest price increases on high-volume lines produce disproportionate net income improvement since all additional revenue above break-even flows to the bottom line.','week_1_2','low','high','revenue'),
  ('netMargin','Net Margin','critical',0,40,5,'Contact your bank immediately to restructure debt repayments','If financing costs are contributing to a negative net margin, contact your lender within 48 hours to request a capital repayment holiday or debt restructuring. A business with negative net margins generating positive EBIT has a financing problem, not a trading problem — and banks can and do restructure facilities for clients who engage them proactively.','week_1_2','medium','high','structure'),
  ('netMargin','Net Margin','critical',0,40,6,'Cut your total cost base by 25% within 60 days','Set a non-negotiable target of reducing your total cost base — COGS plus Opex plus financing costs — by 25% within 60 days. Work from the largest cost lines first. A 25% cost reduction at critical net margin typically moves the business from loss-making to break-even, buying time to rebuild revenue.','month_1','high','high','cost'),
  ('netMargin','Net Margin','critical',0,40,7,'Exit or restructure every loss-making product or contract','Calculate the net profit contribution of every major product line and customer contract. Exit or restructure every arrangement generating a net loss — including all allocated overhead and financing costs. Continuing to operate loss-making lines while in a critical net margin position accelerates the deterioration of the whole business.','month_1','medium','high','revenue'),
  ('netMargin','Net Margin','critical',0,40,8,'Engage a business rescue advisor to assess your options','If net margin has been negative for more than two consecutive quarters and your cash position is declining, engage a registered business rescue practitioner or turnaround specialist for an independent assessment. South Africa Companies Act provides formal business rescue procedures that can protect the business while a recovery plan is implemented. Early engagement preserves more options.','month_1','medium','high','risk'),
  ('netMargin','Net Margin','critical',0,40,9,'Accelerate collections on all outstanding debtors immediately','Call every debtor with an outstanding balance above R10 000 this week and request immediate payment or a firm commitment date. Offer a 2–3% early payment discount if necessary — the cost of the discount is lower than the cost of a deteriorating cash position. Net margin improvement requires both cost reduction and accelerated cash recovery.','month_1','medium','medium','cash'),
  ('netMargin','Net Margin','critical',0,40,10,'Build a 12-month net margin recovery roadmap with monthly targets','Once immediate survival actions are in place, build a written 12-month recovery plan with monthly net margin targets, specific revenue and cost initiatives, and named owners for each action. Set a milestone of reaching positive net margin within 90 days and a target net margin of 5% or above within 12 months. Review weekly.','month_1_3','medium','high','operations'),
  ('netMargin','Net Margin','at_risk',40,65,1,'Decompose net margin into its four component drivers','Break your net margin into gross margin, Opex ratio, interest burden, and tax burden. Identify which component is most below benchmark for your industry. Targeted improvement on the weakest component delivers the fastest net margin recovery — and prevents you from spending effort on a driver that is already performing adequately.','immediate','low','medium','operations'),
  ('netMargin','Net Margin','at_risk',40,65,2,'Set a minimum net margin floor for all new business accepted','Define a minimum acceptable net margin percentage for any new contract, product line, or customer and enforce it as a business rule. Work backwards from your target net margin to determine the minimum gross margin required after deducting your Opex allocation, interest, and tax. Accepting below-floor business is the primary way at-risk businesses stay at-risk.','immediate','low','high','revenue'),
  ('netMargin','Net Margin','at_risk',40,65,3,'Implement a 5–8% price increase across your full product range','A 5% price increase on a business with a 5% net margin doubles net profit at the same volume — no additional costs required. Identify your least price-sensitive products and implement increases there first. Communicate increases with a value narrative and a reasonable notice period to minimise customer attrition.','week_1_2','low','high','revenue'),
  ('netMargin','Net Margin','at_risk',40,65,4,'Reduce total debt to lower net interest expense within 90 days','Identify the highest-rate debt facility and commit a defined monthly surplus — at minimum 15% of free cash flow — to reducing the principal. Lower principal means lower interest charges which flows directly to net margin improvement. Model the net margin impact of eliminating your most expensive facility within 12 months.','month_1','medium','medium','structure'),
  ('netMargin','Net Margin','at_risk',40,65,5,'Review tax structure for legitimate rate reduction opportunities','Engage your tax advisor to review whether your current tax structure is optimal. Businesses at an at-risk net margin often have significant tax efficiency opportunities — SBC qualification, unclaimed deductions, or ETI credits — that are being overlooked.','month_1','medium','medium','structure'),
  ('debtorDays','Debtor Days','critical',0,40,5,'Negotiate payment arrangements on your five largest outstanding invoices','For your five largest outstanding invoices, negotiate a structured payment arrangement — a specific amount due weekly or bi-weekly until the balance is cleared. A payment arrangement with a reliable customer is better than legal action that damages the relationship, delays cash, and incurs legal costs. Document all arrangements in writing and follow up religiously.','week_1_2','medium','high','cash'),
  ('debtorDays','Debtor Days','critical',0,40,6,'Implement COD or prepayment for all new orders immediately','Switch all new customer orders to cash on delivery or prepayment with immediate effect. Stop extending new credit while your existing debtors book is in crisis. Every new credit sale at a critical debtor days position adds to the working capital trap before the existing problem is resolved.','week_1_2','low','medium','cash'),
  ('debtorDays','Debtor Days','critical',0,40,7,'Instruct a debt collection attorney on all debtors over 90 days','For every customer whose invoice has been outstanding for more than 90 days and who has not responded to calls or demand letters, instruct a debt collection attorney or agency immediately. The probability of collection drops dramatically after 90 days — every additional day of delay reduces recovery prospects. Legal costs are typically recovered from the debtor if the claim is successful.','month_1','medium','medium','cash'),
  ('debtorDays','Debtor Days','critical',0,40,8,'Write off irrecoverable debts and claim the tax deduction','Identify debts that are genuinely irrecoverable — debtors who are insolvent, untraceable, or where the cost of collection exceeds the amount owed — and write them off formally. Written-off bad debts are tax deductible in South Africa under Section 11(a) of the Income Tax Act. Writing them off clears your debtors book, improves the ratio, and generates a tax saving.','month_1','low','medium','cost'),
  ('debtorDays','Debtor Days','critical',0,40,9,'Implement a daily debtors report with 7-day collection targets','Create a daily debtors report showing every outstanding invoice with its age, amount, and a 7-day collection target. Review this report every morning. At a critical debtor days position, daily monitoring and daily action are non-negotiable. Weekly or monthly debtor reviews are insufficient when you are losing cash every day.','month_1','low','medium','operations'),
  ('debtorDays','Debtor Days','critical',0,40,10,'Redesign credit policy to prevent recurrence once crisis is resolved','Once the immediate debtors crisis is stabilised, redesign your credit policy from scratch — credit limits by customer, required credit checks for new accounts, maximum days before hold, escalation triggers, and collection procedures. A written credit policy prevents the structural issues that created the crisis from recurring. Implement within 90 days of crisis resolution.','month_1_3','medium','high','risk'),
  ('debtorDays','Debtor Days','at_risk',40,65,1,'Generate an aged debtors report and review it today','Pull a full aged debtors report showing every outstanding invoice by age bucket — current, 30 days, 60 days, 90 days, 90+ days. Calculate the percentage of your debtors book in each bucket. An at-risk debtors position typically has 20–40% of the book in the 60–90 day bucket — still recoverable but requiring urgent action.','immediate','low','medium','cash'),
  ('debtorDays','Debtor Days','at_risk',40,65,2,'Implement a weekly debtors collections process with named accountability','Assign a specific person to own debtor collections and set a weekly process — aged report reviewed Monday, calls made Tuesday through Thursday, escalations Friday. Collections performance should be measured against target debtor days monthly. Disciplined weekly process typically reduces debtor days by 10–15 days within 60 days without any structural change to credit policy.','immediate','low','medium','operations'),
  ('debtorDays','Debtor Days','at_risk',40,65,3,'Implement credit holds for all customers exceeding 45-day outstanding balance','Set up an automatic credit hold for all customers whose outstanding balance exceeds 45 days. No further orders should be processed until the overdue amount is paid or a payment arrangement is agreed. Credit holds create urgency for customers to pay and prevent the debtors position from worsening through continued trading on extended credit.','week_1_2','low','medium','cash'),
  ('debtorDays','Debtor Days','at_risk',40,65,4,'Run a credit check on all customers receiving more than 30-day terms','Conduct a credit bureau check on every customer currently receiving more than 30-day terms. Customers whose credit profile has deteriorated since you first extended terms represent an increasing collection risk. Adjust credit limits and terms for any customer whose credit score has declined materially — before their invoice becomes a bad debt.','week_1_2','medium','medium','risk'),
  ('debtorDays','Debtor Days','at_risk',40,65,5,'Switch to same-day invoicing from delivery or completion','Eliminate any invoicing lag by issuing invoices on the same day as delivery or service completion. Many at-risk debtor positions have an invoicing lag of 3–7 days built in as standard practice. Removing this lag immediately reduces effective debtor days by the same amount at zero cost. Implement via mobile invoicing tools if field staff are doing the delivery.','month_1','low','medium','cash'),
  ('debtorDays','Debtor Days','at_risk',40,65,6,'Offer a 2% early payment discount to incentivise faster settlement','Introduce a 2% discount for payment within 7 days on all new invoices, communicated clearly on the invoice itself. A 2% discount for 23 days earlier payment has an effective annual cost of approximately 31% — high as a borrowing cost but very low compared to the working capital benefit of consistently faster collections.','month_1','low','medium','cash'),
  ('debtorDays','Debtor Days','at_risk',40,65,7,'Introduce progress billing for all projects over two weeks in duration','Require progress billing at defined milestones for any engagement running more than two weeks. Billing at 50% of project value at midpoint and 50% at completion can halve your effective debtor days on project revenue. Make progress billing a standard contractual term for all new engagements.','month_1','medium','medium','cash'),
  ('debtorDays','Debtor Days','at_risk',40,65,8,'Explore invoice discounting as a working capital management tool','Assess whether a revolving invoice discounting facility — where you can selectively discount specific invoices when cash is needed — provides a cost-effective working capital buffer. Unlike full factoring, revolving invoice discounting gives you flexibility to use the facility only when needed, reducing the cost of the arrangement compared to discounting your entire book.','month_1_3','medium','medium','structure'),
  ('debtorDays','Debtor Days','at_risk',40,65,9,'Formalise your credit policy in a written document','Write a formal credit policy covering: credit assessment criteria for new accounts, maximum credit limits by customer tier, required terms and conditions, escalation triggers, and collection procedures at 30, 45, 60, and 90 days. A written policy creates consistency, accountability, and defensibility — and reduces the debtor days that arise from informal or inconsistent credit decisions.','month_1_3','medium','medium','risk'),
  ('debtorDays','Debtor Days','at_risk',40,65,10,'Set a 12-month debtor days target and track it monthly','Define a specific target debtor days figure — typically your invoice payment terms plus 5 days — and track your actual debtor days against this target monthly. Share the performance metric with your collections team and include it in monthly management accounts. What gets measured gets managed, and debtor days managed to a target consistently outperform those managed to a vague intention to improve.','month_3_6','low','medium','operations'),
  ('debtorDays','Debtor Days','healthy',65,100,1,'Document your credit policy and collections process formally','Write down your current credit policy — credit assessment criteria, terms by customer tier, hold triggers, and collection procedures. A healthy debtor days position built on informal practices is fragile to staff changes. Documentation protects your current performance and provides a training foundation for new staff managing credit and collections.','month_1','low','low','operations'),
  ('debtorDays','Debtor Days','healthy',65,100,2,'Set a debtor days ceiling and configure monthly alerts','Define a maximum acceptable debtor days figure — your standard payment terms plus 5 days — and set up a monthly alert if actual debtor days exceed this ceiling for two consecutive months. Early warning prevents a healthy position from drifting to at-risk through gradual, unnoticed deterioration in collections discipline.','month_1','low','medium','risk'),
  ('debtorDays','Debtor Days','healthy',65,100,3,'Assess whether debtor days can be reduced further through technology','Explore automated invoice delivery, payment reminders, and online payment portals that could reduce your average debtor days by 3–5 further days. On R10 million annual revenue, a 5-day reduction releases R137 000 in permanent working capital. Technology-enabled collections are more consistent and less resource-intensive than manual processes.','month_1','medium','medium','operations'),
  ('debtorDays','Debtor Days','healthy',65,100,4,'Run annual credit reviews on all major customer accounts','Conduct an annual review of the credit limits and terms extended to your top 20 accounts by outstanding balance. Reassess their creditworthiness using current financial information. Customer financial health changes — a customer who was creditworthy two years ago may not be today. Annual review prevents comfortable debtor relationships from becoming risky ones.','month_1_3','medium','medium','risk'),
  ('debtorDays','Debtor Days','healthy',65,100,5,'Explore whether a deposit or prepayment model suits your highest-risk accounts','Identify customers who represent the highest credit risk in your book — large balances, inconsistent payment history, or deteriorating financial health — and introduce a deposit or prepayment requirement for future orders. Migrating your highest-risk accounts to prepayment reduces the volatility of your debtors position without affecting your best customers.','month_1_3','medium','medium','risk'),
  ('debtorDays','Debtor Days','healthy',65,100,6,'Negotiate shorter payment terms with smaller, lower-credit customers','Review payment terms by customer size and credit quality. Large, creditworthy customers often command 30-day terms legitimately. Small customers with limited creditworthiness should be on shorter terms — 7 or 14 days — or COD. Tiering your credit terms by customer quality is the most risk-efficient approach to maintaining healthy debtor days.','month_3_6','medium','medium','risk'),
  ('debtorDays','Debtor Days','healthy',65,100,7,'Invest surplus working capital in yield-bearing short-term instruments','Your healthy debtor days generate surplus cash that many businesses leave idle. Move any cash surplus above your minimum operating buffer into a money market fund, 32-day notice account, or treasury product. Consistently healthy debtor management is a competitive advantage — ensure you are capturing the financial return it generates.','month_3_6','low','medium','cash'),
  ('debtorDays','Debtor Days','healthy',65,100,8,'Stress-test debtors position against a customer concentration risk event','Model your debtor days and cash position if your largest customer delayed payment by 60 days. Identify whether this single event would push your debtors position to at-risk and what action you would take. Customer concentration in your debtors book is a specific risk worth understanding and planning for in advance.','month_3_6','low','medium','risk'),
  ('debtorDays','Debtor Days','healthy',65,100,9,'Explore credit insurance for large individual debtor exposures','If any single customer represents more than 15–20% of your total debtors book, assess whether credit insurance on that exposure is cost-effective. Credit insurance pays out if the insured customer fails to pay due to insolvency or protracted default. Premiums are typically 0.2–0.5% of insured turnover — a low cost relative to the protection provided.','year_1','medium','medium','risk'),
  ('debtorDays','Debtor Days','healthy',65,100,10,'Include debtor days in your annual working capital strategy review','Make debtor days a standing agenda item in your annual financial planning cycle alongside inventory days and creditor days. Set targets for the coming year based on any changes to your customer mix, credit policy, or product offering. Debtors management that is reviewed and targeted annually consistently outperforms that managed only when problems emerge.','year_1','low','medium','operations'),
  ('creditorDays','Creditor Days','critical',0,40,1,'Assess whether critical creditor days reflects under-utilisation or over-payment','A critical creditor days score means you are paying suppliers too quickly relative to your working capital needs — you are funding your suppliers rather than optimising your own cash cycle. Calculate your current creditor days and compare to your invoice payment terms. If you are paying well before the due date, this is a cash management problem, not a supplier relationship one.','immediate','low','high','cash'),
  ('creditorDays','Creditor Days','critical',0,40,2,'Stop all early supplier payments immediately','Issue a directive that no supplier invoice will be paid before its contractual due date. Many businesses default to paying invoices as they arrive rather than on due date — a practice that unnecessarily accelerates cash outflow. Paying on due date rather than early is an immediate improvement to creditor days that requires no negotiation.','immediate','low','high','cash'),
  ('creditorDays','Creditor Days','critical',0,40,3,'Contact all major suppliers to negotiate extended payment terms','Call your five largest suppliers and request an extension of payment terms — from 30 to 60 days, or from 14 to 30 days. Present your purchase history, payment reliability, and projected volumes as leverage. A 30-day extension across your major suppliers can release weeks of cash flow equivalent to a significant working capital facility.','week_1_2','medium','high','cash'),
  ('creditorDays','Creditor Days','critical',0,40,4,'Negotiate 60-day terms as standard for all new supplier agreements','Make 60-day payment terms a non-negotiable requirement for all new supplier agreements. New suppliers entering a relationship are often more flexible on terms than established ones. Building longer terms into new contracts from the outset avoids the need to renegotiate later and immediately benefits your creditor days ratio.','week_1_2','low','medium','cash'),
  ('creditorDays','Creditor Days','critical',0,40,5,'Implement a formal payment run schedule to maximise terms utilisation','Set up a weekly or bi-weekly payment run schedule where all invoices are reviewed and payments are scheduled for the latest acceptable payment date. Ad-hoc payment of invoices as they arrive is a common cause of unnecessarily short creditor days. A scheduled payment run ensures you utilise your full terms on every supplier payment.','week_1_2','low','high','cash'),
  ('creditorDays','Creditor Days','critical',0,40,6,'Request extended terms from your three largest spend categories','Prioritise your renegotiation effort on the three supplier categories representing the most spend. A 30-day extension from your three largest cost categories will improve overall creditor days more than a 30-day extension from ten small suppliers. Concentrate negotiating effort where the cash impact is greatest.','month_1','medium','high','cash'),
  ('creditorDays','Creditor Days','critical',0,40,7,'Offer volume commitments in exchange for extended payment terms','Approach key suppliers with a formal volume commitment — a guaranteed annual purchase quantity — in exchange for extended payment terms of 60–90 days. Volume certainty is valuable to most suppliers and can offset the cost to them of extended terms. Document the commitment clearly to make it a tradeable business arrangement.','month_1','medium','medium','cost'),
  ('creditorDays','Creditor Days','critical',0,40,8,'Explore supply chain finance for your largest supplier relationships','Research supply chain finance programmes — available through several South African banks — where the bank pays your supplier on due date and you repay the bank on extended terms of 90–120 days. This provides your supplier with certainty of payment while giving you significantly extended creditor days. It is a structured, bank-facilitated extension of your creditor cycle.','month_1_3','high','high','structure'),
  ('creditorDays','Creditor Days','critical',0,40,9,'Benchmark creditor days against your sector and set an improvement target','Research creditor days benchmarks for your sector — retail typically achieves 45–60 days, manufacturing 30–45 days, services 20–30 days. If your creditor days are significantly below your sector benchmark, you are funding your working capital cycle more expensively than your competitors. Set a specific target to close the gap within 12 months.','month_1_3','low','medium','operations'),
  ('creditorDays','Creditor Days','critical',0,40,10,'Build a supplier terms management calendar for all major contracts','Create a calendar showing every major supplier contract, its current payment terms, and the next opportunity to renegotiate. Schedule a renegotiation conversation 60 days before each contract renewal. Systematic management of supplier terms through a calendar converts a reactive creditor days position into a proactively managed competitive advantage.','month_1_3','low','medium','operations'),
  ('creditorDays','Creditor Days','at_risk',40,65,1,'Audit current payment terms across all major suppliers','List every major supplier with its current contractual payment terms, your actual average payment date, and the cash impact of paying on due date versus current practice. Many at-risk creditor days positions exist because businesses pay before the contractual due date by default. Identifying where you are paying early is the first step to correcting it.','immediate','low','medium','cash'),
  ('creditorDays','Creditor Days','at_risk',40,65,2,'Implement a structured payment run to use terms in full','Set up a bi-weekly payment run where all invoices are reviewed and scheduled for payment on — not before — their contractual due date. Centralise payment authority so that ad-hoc early payments require explicit approval. This single discipline improvement often adds 7–14 days to effective creditor days without any supplier negotiation.','immediate','low','medium','cash'),
  ('creditorDays','Creditor Days','at_risk',40,65,3,'Renegotiate terms with your three largest suppliers to 45–60 days','Approach your three largest suppliers and request an extension of payment terms to 45–60 days. Present your purchase history, payment reliability, and projected growth as the basis for the request. Even if only one of three agrees, the cash impact is immediate and meaningful. Prioritise your largest spend categories for the greatest working capital benefit.','week_1_2','medium','medium','cash'),
  ('creditorDays','Creditor Days','at_risk',40,65,4,'Make 45-day minimum terms a requirement for all new supplier agreements','Establish 45-day payment terms as your minimum standard requirement for all new supplier agreements. New suppliers are almost always more flexible on terms during contract negotiation than established ones. Building longer terms into new agreements from day one avoids the need for subsequent renegotiation and benefits your creditor days immediately.','month_1','low','medium','cash'),
  ('creditorDays','Creditor Days','at_risk',40,65,5,'Track creditor days monthly alongside debtor and inventory days','Add creditor days to your monthly management accounts as part of a working capital dashboard alongside debtor days and inventory days. Monthly visibility of all three components makes it easy to see the combined impact on your cash conversion cycle and identify which element needs the most attention.','month_1','low','medium','operations'),
  ('creditorDays','Creditor Days','at_risk',40,65,6,'Offer volume commitments to suppliers in exchange for extended terms','Identify suppliers where a formal volume commitment over 12 months would be valuable to them in exchange for extended payment terms. A guaranteed volume offer reduces a supplier''s sales uncertainty and justifies the cost of extending your terms. Structure the offer as a formal written agreement to give it commercial weight.','month_1','medium','medium','cost'),
  ('creditorDays','Creditor Days','at_risk',40,65,7,'Evaluate consolidating suppliers to earn longer terms through higher volume','If you are spreading spend across many small suppliers, consolidating to fewer larger suppliers concentrates volume and increases your leverage to negotiate longer terms. A supplier receiving 100% of your category spend has more reason to extend 60-day terms than one receiving 20%. Supplier consolidation is a strategic lever for improving creditor days.','month_1_3','medium','medium','cost'),
  ('creditorDays','Creditor Days','at_risk',40,65,8,'Benchmark creditor days against your sector median','Research creditor days benchmarks for your industry and compare your current performance. If you are below sector median, your competitors are effectively funding their working capital more cheaply than you. Closing the gap to sector median through better terms management is a free improvement to your cash conversion cycle.','month_1_3','low','medium','operations'),
  ('creditorDays','Creditor Days','at_risk',40,65,9,'Explore supply chain finance for your largest supplier relationships','Research supply chain finance programmes available through South African banks. Under these programmes, the bank pays your supplier promptly while you repay the bank on extended terms — effectively extending your creditor days without impacting your supplier''s cash flow. This is a win-win arrangement that benefits both parties.','month_3_6','high','medium','structure'),
  ('creditorDays','Creditor Days','at_risk',40,65,10,'Set a 12-month creditor days improvement target by supplier category','Define a 12-month creditor days target for each major supplier category — materials, services, utilities, subcontractors — and build the specific negotiation and terms management actions required to reach it. Category-level targets are more actionable than a single blended number and produce faster results through focused negotiation.','month_3_6','medium','medium','cash'),
  ('creditorDays','Creditor Days','healthy',65,100,1,'Document your current supplier terms and payment schedule','Record every major supplier with its contracted payment terms, actual average payment date, and creditor days contribution. This baseline protects your healthy creditor days from eroding when staff change and ensures your payment run schedule consistently utilises the full terms available rather than defaulting to early payment.','month_1','low','low','operations'),
  ('creditorDays','Creditor Days','healthy',65,100,2,'Maintain your payment run discipline to protect terms utilisation','Reinforce your bi-weekly or weekly payment run as a standing operational discipline. The most common cause of healthy creditor days drifting to at-risk is the return to ad-hoc early payment driven by supplier pressure or staff convenience. Maintain centralised payment authority and the run schedule as a non-negotiable process.','month_1','low','medium','operations'),
  ('creditorDays','Creditor Days','healthy',65,100,3,'Use strong payment history to negotiate better terms at renewal','Your consistent on-time payment history is a negotiating asset. When major supplier contracts come up for renewal, request an extension of payment terms — from 45 to 60 days or from 30 to 45 days — as part of the renewal discussion. Present your payment track record as the basis for the request. Suppliers value reliable payers and will often extend terms to retain them.','month_1','low','medium','cash'),
  ('creditorDays','Creditor Days','healthy',65,100,4,'Ensure new supplier agreements include minimum 45-day terms','Set 45-day payment terms as your standard minimum for all new supplier agreements. Protect your healthy creditor days from erosion by new suppliers offering only 14 or 30-day terms as a default. Negotiate at contract initiation — it is far easier to secure favourable terms when establishing a new relationship than to extend them after the relationship is set.','month_1_3','low','medium','cash'),
  ('creditorDays','Creditor Days','healthy',65,100,5,'Explore whether 60–90 day terms are achievable for major supplier categories','Assess whether your highest-spend supplier categories could be extended to 60 or 90 days through volume commitments, supply chain finance, or strategic partnership arrangements. Even moving from 45 to 60 days on your largest category releases meaningful additional working capital permanently and reduces your CCC further.','month_1_3','medium','medium','cash'),
  ('creditorDays','Creditor Days','healthy',65,100,6,'Include creditor days in your annual working capital review','Make creditor days a standing item in your annual financial planning cycle. Review every major supplier contract for terms optimisation opportunities at renewal, assess whether consolidation would improve leverage, and confirm that your payment run discipline is being maintained. Annual reviews prevent silent erosion of a healthy creditor days position.','month_1_3','low','medium','operations'),
  ('creditorDays','Creditor Days','healthy',65,100,7,'Explore dynamic discounting for early payment on selective invoices','Investigate dynamic discounting platforms that allow you to offer early payment on selected supplier invoices in exchange for a discount — only when you have surplus cash and the discount yield exceeds your money market return. Dynamic discounting turns your cash surplus into a managed yield opportunity rather than an early payment donation to your supplier.','month_3_6','medium','low','cash'),
  ('creditorDays','Creditor Days','healthy',65,100,8,'Stress-test creditor days against a supplier relationship disruption','Model what happens to your working capital cycle if your two largest suppliers reduced terms from 60 to 30 days simultaneously — a plausible scenario during a sector credit crunch or if those suppliers face their own cash pressures. Identify the cash impact and your response plan. Diversifying supplier relationships is a key risk mitigation in this scenario.','month_3_6','low','medium','risk'),
  ('creditorDays','Creditor Days','healthy',65,100,9,'Build supplier relationship strength to protect long-term terms','Invest in strategic supplier relationships beyond transactional purchasing — share your growth plans, provide forecast visibility, pay reliably, and give feedback. Suppliers who view you as a strategic partner rather than a commodity customer are more likely to maintain favourable terms during market disruptions and more likely to offer improved terms as your volume grows.','year_1','medium','medium','operations'),
  ('creditorDays','Creditor Days','healthy',65,100,10,'Include creditor days strategy in your three-year working capital plan','Dedicate a section of your three-year business plan to creditor days strategy — identifying target terms by supplier category at each revenue milestone, the supplier consolidation and relationship investments required, and the working capital benefit from each improvement. Proactive creditor management at scale is a CFO-level discipline that generates real competitive advantage in capital efficiency.','year_1','low','medium','cash'),
  ('wipDays','WIP Days','critical',0,40,1,'Map every active WIP job with its start date and cost to date','Create a complete list of every job, project, or batch currently in work-in-progress, with its start date, total costs incurred, expected completion date, and billed amount to date. At a critical WIP days ratio, cash is trapped in uncompleted work — you cannot release it until jobs are completed and invoiced. This map tells you exactly how much cash is trapped and where.','immediate','medium','high','cash'),
  ('wipDays','WIP Days','critical',0,40,2,'Prioritise completion of highest-value WIP jobs within seven days','Rank all WIP jobs by value and direct all available resources to completing the highest-value jobs as quickly as possible. Each completed job converts WIP to a billable invoice — releasing trapped cash. In a critical WIP days position, completion velocity is a cash flow lever. Assign overtime, additional resources, or management oversight to the top five jobs by value.','immediate','high','high','cash'),
  ('wipDays','WIP Days','critical',0,40,3,'Invoice immediately upon each job completion — no batch billing','Implement a policy that every job or deliverable is invoiced on the day it is completed or accepted by the customer. Batch billing — invoicing weekly or at month-end — adds 7–31 days of unnecessary delay between completion and cash receipt. Every day between completion and invoicing is a day of WIP days that has already been resolved but not yet captured.','immediate','low','high','cash'),
  ('wipDays','WIP Days','critical',0,40,4,'Introduce progress billing on all jobs longer than two weeks','Implement a mandatory progress billing policy for all new jobs expected to take longer than two weeks — billing 30% at commencement, 40% at midpoint, and 30% at completion. Progress billing converts long-duration WIP into a series of shorter billing cycles, dramatically reducing the cash trapped in work in progress at any point in time.','week_1_2','medium','high','cash'),
  ('wipDays','WIP Days','critical',0,40,5,'Identify and resolve all WIP jobs stalled by customer or internal delays','Review every WIP job that has been open for more than your target completion cycle and identify the specific cause of delay — customer non-responsiveness, internal resource bottleneck, or scope dispute. Escalate each stalled job personally and set a 48-hour deadline for resolution. Stalled WIP is one of the most expensive forms of working capital trap because it also consumes management capacity.','week_1_2','medium','high','operations'),
  ('wipDays','WIP Days','critical',0,40,6,'Require deposits of 30–50% before commencing any new work','Implement a mandatory deposit requirement of 30–50% before commencing any new job or project. Deposits fund a portion of the initial costs, reducing the WIP that accumulates before the first billing milestone. Communicate this as standard business practice and hold firm — customers who refuse a reasonable deposit are often the same ones who delay final payment.','week_1_2','low','high','cash'),
  ('wipDays','WIP Days','critical',0,40,7,'Set a maximum WIP days limit per job and enforce it operationally','Define a maximum number of days any single job may remain in WIP before a billing milestone must be reached. For example, no job may accumulate more than 30 days of unbilled WIP. Assign the operations or project manager the responsibility to flag any job approaching this limit. This operational limit prevents runaway WIP accumulation on individual jobs.','month_1','medium','high','operations'),
  ('wipDays','WIP Days','critical',0,40,8,'Stop accepting new jobs until existing WIP backlog is cleared','If your WIP backlog is so large that resources are stretched and completion dates are slipping, consider a temporary moratorium on accepting new work until existing WIP is reduced to a manageable level. Continuing to start new jobs while existing ones remain uncompleted compounds the WIP days problem and delays cash receipt on all jobs simultaneously.','month_1','high','medium','operations'),
  ('wipDays','WIP Days','critical',0,40,9,'Implement weekly WIP reporting with completion and billing targets','Set up a weekly WIP dashboard showing all active jobs with their start date, estimated completion, costs incurred, amount billed, and amount outstanding. Review this every Monday and set specific completion and billing targets for the week. Weekly WIP management reduces average WIP days by 20–30% within 60 days in most service and project businesses.','month_1','medium','medium','operations'),
  ('wipDays','WIP Days','critical',0,40,10,'Redesign your service delivery model to shorten job cycle times','Assess whether your standard job or project structure can be redesigned to reduce cycle times — breaking large projects into smaller discrete deliverables, standardising recurring job types, or improving resource allocation between jobs. Shorter cycle times reduce peak WIP at any point in time and improve overall WIP days structurally rather than just tactically.','month_1_3','high','high','structure'),
  ('wipDays','WIP Days','at_risk',40,65,1,'Generate a WIP age analysis and identify stalled jobs','List all active WIP jobs with their start date, current age, costs incurred, and billing status. Flag any job that has been in WIP for more than 50% of its expected duration without a billing milestone reached. At-risk WIP days typically has a cluster of stalled or slow-moving jobs that are anchoring the overall ratio upward.','immediate','low','medium','operations'),
  ('wipDays','WIP Days','at_risk',40,65,2,'Implement progress billing for all new jobs over 14 days','Require progress billing at defined milestones for all new engagements expected to run more than 14 days. Billing at 30–50% at midpoint and the remainder on completion reduces peak WIP by approximately half on each job. Implement this immediately for all new engagements and negotiate it into existing jobs at the next natural checkpoint.','week_1_2','medium','medium','cash'),
  ('wipDays','WIP Days','at_risk',40,65,3,'Resolve all stalled WIP jobs within 14 days','For every job that has been open for more than its expected completion time, make a direct call to the client or responsible person and set a 14-day resolution deadline — either complete and invoice, or formally close and bill for work done to date. Stalled jobs are the primary driver of at-risk WIP days and must be resolved before they age further.','week_1_2','medium','medium','operations'),
  ('wipDays','WIP Days','at_risk',40,65,4,'Switch from month-end billing to completion-date billing','If your billing cycle is monthly, switch to invoicing on the day of job completion or milestone sign-off. Monthly billing adds an average of 15 days of unnecessary WIP delay across all jobs completed in mid-month. Completion-date billing eliminates this structural delay and immediately reduces average WIP days without any change to job processes.','month_1','low','medium','cash'),
  ('wipDays','WIP Days','at_risk',40,65,5,'Require 25–30% deposits on all new jobs before commencement','Implement a deposit requirement for all new work that will run longer than 5 days. Deposits reduce the initial WIP accumulation on each job and improve cash flow from the outset of each engagement. Deposits also serve as a commitment signal from the customer — reducing the probability of job abandonment that creates unbillable WIP.','month_1','low','medium','cash'),
  ('wipDays','WIP Days','at_risk',40,65,6,'Set a WIP days target by job type and track it weekly','Define a target WIP days figure for each type of job or project your business undertakes — based on expected duration — and track actual WIP days by job type weekly. Different job types have different natural cycles; managing WIP days against type-specific targets is more precise and actionable than managing against a single blended number.','month_1','medium','medium','operations'),
  ('wipDays','WIP Days','at_risk',40,65,7,'Improve resource scheduling to reduce job queue waiting time','Analyse how long jobs spend waiting for resources between active work phases. Waiting time in the job queue is WIP days that add no value — the job is open, costs are accumulating, but no productive work is happening. Improving resource scheduling to reduce queue waiting typically reduces WIP days by 15–25% within 60 days.','month_1_3','medium','medium','operations'),
  ('wipDays','WIP Days','at_risk',40,65,8,'Standardise your highest-volume job types to reduce cycle times','Identify your two or three most common job types and create standardised delivery templates — defined steps, standard time allocations, required sign-offs at each stage. Standardised delivery is faster, more consistent, and generates less rework than custom processes. A 20% reduction in average job cycle time directly reduces WIP days by a similar proportion.','month_1_3','medium','medium','operations'),
  ('wipDays','WIP Days','at_risk',40,65,9,'Implement a job management system with WIP tracking','If you are managing WIP in spreadsheets or informally, implement a basic job management system — even a simple project tool like Monday.com, Asana, or Xero Projects — that tracks all active jobs with their start date, milestone dates, costs incurred, and billing status. Visibility of WIP at the job level is the foundation of effective WIP days management.','month_1_3','medium','medium','operations'),
  ('wipDays','WIP Days','at_risk',40,65,10,'Set a 12-month WIP days improvement target with quarterly milestones','Define a specific 12-month WIP days target and break it into quarterly milestones across billing process improvements, job cycle time reductions, and deposit implementation. Assign ownership to your operations and finance leads. A written WIP improvement plan with milestones consistently outperforms an informal intention to manage WIP more actively.','month_3_6','medium','medium','operations'),
  ('wipDays','WIP Days','healthy',65,100,1,'Document your WIP management process and billing triggers','Record your current progress billing structure, completion billing process, deposit policy, and WIP monitoring approach. This documentation protects your healthy WIP days from eroding when staff change and provides a reference point for continuous improvement. A healthy WIP position built on undocumented practices is fragile.','month_1','low','low','operations'),
  ('wipDays','WIP Days','healthy',65,100,2,'Set a WIP days ceiling and flag any job exceeding it for review','Define a maximum acceptable WIP days for your business — based on your typical job duration plus a 20% buffer — and flag any job exceeding this limit for management review. Catching individual jobs that are running over WIP targets prevents a single problematic engagement from dragging the whole portfolio ratio from healthy to at-risk.','month_1','low','medium','risk'),
  ('wipDays','WIP Days','healthy',65,100,3,'Assess whether deposit levels can be increased to improve cash flow','If your deposits are currently at 25%, assess whether 35–40% is achievable in your market. Even a 10 percentage point increase in deposit levels on a project-based revenue stream meaningfully reduces peak WIP and improves cash flow from the outset of each engagement. Test with new clients before applying to existing ones.','month_1','low','medium','cash'),
  ('wipDays','WIP Days','healthy',65,100,4,'Continue to optimise progress billing milestones for faster conversion','Review the milestone structure of your progress billing and assess whether earlier or more frequent billing milestones can be incorporated without disrupting delivery. More frequent smaller billings convert WIP to invoices faster, reduce peak WIP at any point in time, and smooth your cash flow profile across the billing cycle.','month_1_3','medium','medium','cash'),
  ('wipDays','WIP Days','healthy',65,100,5,'Standardise delivery templates to sustain WIP efficiency at scale','As you take on more jobs and grow revenue, delivery consistency becomes harder to maintain — more jobs in progress simultaneously increases the risk of WIP days creeping upward. Invest in standardising your delivery templates, resource scheduling, and billing procedures now so that growth does not erode your healthy WIP position.','month_1_3','medium','high','operations'),
  ('wipDays','WIP Days','healthy',65,100,6,'Invest in job management technology to maintain WIP visibility at scale','As your job volume grows, manual WIP tracking becomes inadequate. Invest in job management software that tracks all active jobs in real time — costs, progress, billing milestones, and WIP days — at a portfolio level. Technology-enabled WIP management is the primary tool for sustaining healthy WIP days through growth-driven job volume increases.','month_3_6','medium','high','operations'),
  ('wipDays','WIP Days','healthy',65,100,7,'Explore productising your service to reduce WIP cycle length','Assess whether any of your current project or bespoke service offerings can be converted into a standardised productised service — fixed scope, fixed price, fixed delivery timeline. Productised services have shorter, more predictable WIP cycles and are easier to bill on completion without dispute. They also command higher margins than custom work in most markets.','month_3_6','high','high','structure'),
  ('wipDays','WIP Days','healthy',65,100,8,'Stress-test WIP days against a high job volume scenario','Model your WIP days if job volume doubled without a proportional increase in delivery resources. Identify at what volume your current scheduling and billing processes would push WIP days from healthy to at-risk. Pre-planning your capacity and billing process response to high-volume periods prevents growth from being undermined by a WIP cash trap.','month_3_6','low','medium','risk'),
  ('wipDays','WIP Days','healthy',65,100,9,'Include WIP days in your annual cash flow forecasting process','Incorporate WIP days as a variable in your annual cash flow forecast — modelling the cash timing impact of your expected job volume, average duration, and billing structure. Businesses that plan WIP cash timing alongside debtor days and creditor days have significantly more accurate cash flow forecasts and avoid the working capital surprises that growth creates.','year_1','medium','medium','cash'),
  ('wipDays','WIP Days','healthy',65,100,10,'Build WIP management into your three-year operational scaling plan','Include a WIP management strategy in your three-year business plan — specifying target WIP days at each revenue milestone, the operational and billing systems required to sustain it, and the deposit and progress billing structure that will govern future engagements. WIP management built into scaling plans prevents the cash flow disruptions that frequently accompany rapid service business growth.','year_1','medium','high','structure'),
  ('workingCapitalFunding','WC Funding Intensity','critical',0,40,1,'Calculate the exact rand value of your working capital funding requirement','Add debtors and inventory then subtract creditors to calculate the exact rand amount of working capital you are currently funding from cash or borrowings. A critical WC funding intensity means this number is a dangerously high proportion of your annual revenue. Knowing the exact amount and its composition — debtors versus inventory versus creditor shortfall — directs your immediate action.','immediate','low','high','cash'),
  ('workingCapitalFunding','WC Funding Intensity','critical',0,40,2,'Apply for invoice discounting on your full debtors book immediately','If debtors are the dominant component of your working capital funding requirement, apply for invoice discounting or factoring immediately. This converts 70–85% of outstanding invoices to cash within 24–48 hours. The cost — typically 1.5–2.5% per month — is justified by the immediate cash release from a critical working capital funding crisis.','immediate','medium','high','cash'),
  ('workingCapitalFunding','WC Funding Intensity','critical',0,40,3,'Emergency inventory clearance to release working capital funding','Identify all inventory over 45 days old and price it for immediate clearance at 25–40% discount. Each rand of inventory converted to cash reduces your working capital funding requirement by the same amount. Set a 30-day target to reduce inventory value by 25% through clearance activity and report progress weekly.','week_1_2','medium','high','cash'),
  ('workingCapitalFunding','WC Funding Intensity','critical',0,40,4,'Contact all major suppliers for emergency payment term extensions','Call your five largest suppliers this week and request an emergency extension of payment terms by 30–45 days. Extended creditor terms reduce your working capital funding requirement without requiring any customer or inventory action. Suppliers who extend terms reduce the cash you need to fund the business — the equivalent of an interest-free loan from each supplier.','week_1_2','medium','high','cash'),
  ('workingCapitalFunding','WC Funding Intensity','critical',0,40,5,'Switch all new customer transactions to prepayment or COD immediately','Implement COD or prepayment for all new orders with immediate effect. Every new credit sale adds to your working capital funding requirement before the existing crisis is resolved. Stopping the inflow of new credit sales is the only way to prevent the working capital funding gap from widening while you work on reducing the existing one.','week_1_2','low','medium','cash'),
  ('workingCapitalFunding','WC Funding Intensity','critical',0,40,6,'Contact your bank to discuss a working capital facility immediately','If you do not have a working capital facility, contact your bank immediately and apply for one based on your current debtors book, inventory, and financials. A dedicated working capital or overdraft facility converts the funding requirement from an acute crisis to a managed financial obligation. Apply before the crisis has caused a cash default — banks are significantly more receptive to applications from businesses that have not yet missed payments.','month_1','medium','high','structure'),
  ('workingCapitalFunding','WC Funding Intensity','critical',0,40,7,'Target a 30% reduction in working capital funding requirement within 90 days','Set a specific 90-day target to reduce your total working capital funding requirement by 30% through the combined impact of debtor collections, inventory reduction, and creditor term extensions. Assign each component to a named owner with weekly targets. A 30% reduction in the funding requirement on a critical ratio typically moves the business from crisis to at-risk within one quarter.','month_1','medium','high','cash'),
  ('workingCapitalFunding','WC Funding Intensity','critical',0,40,8,'Restructure your largest contracts to include upfront deposits','Renegotiate your three largest customer contracts to include a deposit element at contract commencement and progress billing at defined milestones. For existing contracts, approach the customer as a partnership discussion — explain that your working capital model requires earlier payment in exchange for guaranteed delivery commitment. Many customers will accept this structure if approached professionally.','month_1','medium','medium','cash'),
  ('workingCapitalFunding','WC Funding Intensity','critical',0,40,9,'Model the working capital funding requirement at each revenue growth milestone','Calculate how much working capital funding you will require at each of your next two revenue milestones at current CCC performance. Many businesses discover a working capital funding crisis mid-growth rather than planning for it in advance. Knowing the funding requirement at future revenue levels allows you to arrange facilities proactively before the need is urgent.','month_1_3','medium','high','cash'),
  ('workingCapitalFunding','WC Funding Intensity','critical',0,40,10,'Redesign your business model to reduce structural working capital intensity','Assess whether structural changes — productised services, subscription models, consignment inventory, supply chain finance — could permanently reduce your working capital funding intensity below the sector median. Structural reduction in working capital intensity is the only sustainable fix for a business that has experienced a critical ratio repeatedly. Tactical fixes without structural change lead to recurring crises.','month_3_6','high','high','structure'),
  ('workingCapitalFunding','WC Funding Intensity','at_risk',40,65,1,'Calculate your working capital funding gap and its primary driver','Calculate debtors plus inventory minus creditors to get your total working capital funding requirement. Express this as a percentage of annual revenue and compare to your sector benchmark. Identify which component — debtors, inventory, or short creditor terms — contributes most to the gap. This decomposition determines where you focus your improvement effort.','immediate','low','medium','cash'),
  ('workingCapitalFunding','WC Funding Intensity','at_risk',40,65,2,'Implement weekly collections discipline to reduce debtors component','Set up a standing weekly debtors review where every invoice over 21 days is followed up with a direct call. Assign a named person to collections and measure performance against target debtor days monthly. A disciplined weekly collections process reduces the debtors component of your working capital funding requirement by 10–15% within 60 days.','week_1_2','low','medium','cash'),
  ('workingCapitalFunding','WC Funding Intensity','at_risk',40,65,3,'Reduce inventory component by resetting reorder quantities to 30-day demand','Review purchase order quantities for your top 10 SKUs by inventory value and reset them to cover 30 days of actual current demand plus a 7-day safety buffer. Reducing order quantities reduces average inventory on hand and the working capital it consumes. Even a 15% reduction in average inventory value at the same revenue level produces a meaningful improvement in funding intensity.','week_1_2','medium','medium','cash'),
  ('workingCapitalFunding','WC Funding Intensity','at_risk',40,65,4,'Negotiate 15-day payment term extensions with your top three suppliers','Request extended payment terms from your three largest suppliers — even a 15-day extension directly reduces your working capital funding requirement. Use your payment history and volume relationship as leverage. A 15-day extension across three major suppliers on R1 million of combined monthly purchases releases approximately R500 000 in working capital.','month_1','medium','medium','cash'),
  ('workingCapitalFunding','WC Funding Intensity','at_risk',40,65,5,'Arrange a working capital facility before the need becomes urgent','Apply for a revolving working capital facility or overdraft with your bank while your financial position is still at-risk rather than critical. Banks approve facilities to businesses that need them as a contingency — not to businesses already in distress. An approved facility you do not draw on costs very little; a facility you cannot get when you need it is extremely expensive.','month_1','medium','high','structure'),
  ('workingCapitalFunding','WC Funding Intensity','at_risk',40,65,6,'Introduce progress billing to reduce working capital on project revenue','Implement milestone billing for all project-based or long-cycle revenue. Billing at 30%, 30%, and 40% of project value at defined milestones rather than at completion can reduce the debtors component of working capital funding by 40–60% on project revenue. Build this into all new contracts and renegotiate it into renewals.','month_1','medium','medium','cash'),
  ('workingCapitalFunding','WC Funding Intensity','at_risk',40,65,7,'Track working capital funding intensity monthly in management accounts','Add working capital funding intensity — expressed as the rand value of net working capital as a percentage of annual revenue — to your monthly management accounts. Monthly tracking with a trend line shows whether your improvement initiatives are reducing the funding requirement and flags any unexpected increases before they become structural.','month_1','low','medium','operations'),
  ('workingCapitalFunding','WC Funding Intensity','at_risk',40,65,8,'Model funding requirement growth at your planned revenue milestone','Calculate your working capital funding requirement at your next revenue milestone assuming your current CCC remains unchanged. This tells you how much additional funding you will need to support growth before that growth is profitable. Use this calculation to plan your facility requirements and growth financing strategy in advance.','month_1_3','medium','high','cash'),
  ('workingCapitalFunding','WC Funding Intensity','at_risk',40,65,9,'Explore consignment arrangements for your highest-value inventory lines','For your highest-value inventory lines where consignment is commercially viable, approach your suppliers about consignment arrangements. Consignment removes these items from your balance sheet until sold, eliminating their contribution to working capital funding intensity entirely. Even converting 20% of inventory to consignment produces a meaningful funding intensity reduction.','month_1_3','medium','medium','structure'),
  ('workingCapitalFunding','WC Funding Intensity','at_risk',40,65,10,'Build a 12-month working capital funding reduction plan','Create a structured 12-month plan targeting a specific reduction in working capital funding intensity — for example, from 25% of revenue to 15% of revenue — through initiatives across debtors, inventory, and creditors. Set quarterly milestones and assign component ownership. A written plan with targets consistently produces better outcomes than informal improvement intentions.','month_3_6','medium','high','cash'),
  ('workingCapitalFunding','WC Funding Intensity','healthy',65,100,1,'Document your working capital funding structure and benchmark it','Record your current net working capital as a percentage of annual revenue and compare to your sector benchmark. A healthy funding intensity should be benchmarked annually — what was excellent two years ago may be average today as competitors improve. Document the components — debtors, inventory, and creditors — separately to maintain a clear decomposition.','month_1','low','low','operations'),
  ('workingCapitalFunding','WC Funding Intensity','healthy',65,100,2,'Model working capital funding at your next revenue milestone','Calculate the working capital funding your business will require at each of your next two revenue milestones, assuming your current funding intensity percentage remains constant. This tells you the absolute cash requirement of planned growth — and whether it can be funded from retained earnings or will require an external facility. Plan the funding before the need arises.','month_1','medium','high','cash'),
  ('workingCapitalFunding','WC Funding Intensity','healthy',65,100,3,'Arrange a pre-approved working capital facility as a growth buffer','Negotiate a revolving working capital facility with your bank while your position is healthy — this is the time when facilities are cheapest and easiest to obtain. Having a pre-approved facility available costs very little when undrawn but provides critical operational certainty if your working capital funding requirement temporarily spikes during growth or a cash cycle disruption.','month_1','medium','medium','structure'),
  ('workingCapitalFunding','WC Funding Intensity','healthy',65,100,4,'Stress-test working capital funding against a growth and delay scenario','Model your working capital funding requirement if revenue grew 40% over 12 months while debtor days extended by 15 days simultaneously. This combined scenario — fast growth plus collection slowdown — is a common cash flow crisis trigger for otherwise healthy businesses. Pre-planning your response means you identify and arrange funding before the crisis hits.','month_1_3','low','medium','risk'),
  ('workingCapitalFunding','WC Funding Intensity','healthy',65,100,5,'Assess whether funding intensity can be reduced through model changes','Even with a healthy funding intensity, explore whether structural changes — subscriptions, deposits, consignment inventory, or supply chain finance — could reduce it further. Each percentage point of improvement releases cash permanently. On R10 million annual revenue, reducing funding intensity from 15% to 10% permanently releases R500 000 in cash for reinvestment or distributions.','month_1_3','medium','medium','structure'),
  ('workingCapitalFunding','WC Funding Intensity','healthy',65,100,6,'Deploy surplus working capital into yield-bearing short-term instruments','If your efficient working capital management consistently generates a positive cash balance above your operating minimum, deploy the surplus in a money market fund, 32-day notice account, or treasury bill. South African money market rates have historically yielded 6–9% annually — meaningful on a consistent surplus balance and a direct return from working capital excellence.','month_1_3','low','medium','cash'),
  ('workingCapitalFunding','WC Funding Intensity','healthy',65,100,7,'Build working capital funding into your annual business plan','Include a working capital funding section in your annual plan showing the projected funding requirement at your target revenue, the facility headroom available, and the initiatives that will sustain your healthy intensity through the year. Working capital planning embedded in the annual cycle prevents the unplanned cash crises that derail otherwise well-run businesses.','month_3_6','low','medium','cash'),
  ('workingCapitalFunding','WC Funding Intensity','healthy',65,100,8,'Explore supply chain finance to extend creditor terms cost-effectively','Research supply chain finance programmes available through South African banks. These programmes allow you to extend creditor payment terms — sometimes to 90 or 120 days — at a cost below your overdraft rate, while your supplier is paid promptly. Supply chain finance is one of the most cost-effective tools for structurally reducing working capital funding intensity.','month_3_6','high','medium','structure'),
  ('workingCapitalFunding','WC Funding Intensity','healthy',65,100,9,'Design your next growth phase to maintain or improve funding intensity','When planning your next major revenue growth initiative, model its working capital funding intensity explicitly. Growth that requires disproportionately high working capital — slow-paying customer segments, high-inventory categories, or long project cycles — can turn a healthy funding intensity into an at-risk one. Design growth for capital efficiency, not just revenue scale.','year_1','medium','high','structure'),
  ('workingCapitalFunding','WC Funding Intensity','healthy',65,100,10,'Include working capital funding in three-year capital structure planning','Integrate working capital funding intensity into your three-year capital structure plan alongside debt and equity strategy. Set a target funding intensity for years one, two, and three, and identify the CCC improvements and facility arrangements required to achieve it at each revenue milestone. Working capital management at three-year horizon is a CFO-level discipline that separates financially sophisticated SMEs from those that discover their capital needs under pressure.','year_1','medium','high','structure'),
  ('capexIntensity','Capex Intensity','critical',0,40,1,'Halt all non-essential capital expenditure with immediate effect','Place an immediate and absolute freeze on all capital expenditure that is not essential to maintaining current revenue generation. At a critical Capex intensity — whether from over-spending or under-investing relative to revenue — every unessential capital commitment worsens your position. Only release capex for items where production or revenue would stop without them.','immediate','low','high','cost'),
  ('capexIntensity','Capex Intensity','critical',0,40,2,'Determine if critical score reflects over-spending or revenue shortfall','A critical Capex intensity can result from two opposite problems: excessive capital spending relative to revenue, or inadequate revenue from existing capital. Calculate both your Capex-to-revenue ratio and your revenue-to-fixed-assets ratio to diagnose which problem you face. The correct response is fundamentally different — one requires cutting Capex, the other requires growing revenue.','immediate','low','high','operations'),
  ('capexIntensity','Capex Intensity','critical',0,40,3,'Cancel or defer all committed but not yet contracted capital projects','Review all planned capital projects and immediately cancel or defer any that have not yet been contractually committed. Planned but uncommitted Capex is the easiest form of capital relief available. Identify the total value of deferrable planned Capex and calculate the cash and financing cost savings from delaying by 12 months.','week_1_2','low','high','cost'),
  ('capexIntensity','Capex Intensity','critical',0,40,4,'Negotiate deferral of contracted but undelivered capital commitments','For any capital items that are contracted but not yet delivered, contact the supplier and request a delivery deferral of 3–6 months. Suppliers of capital equipment are generally willing to defer delivery if the customer agrees to maintain the contract and payment schedule — this buys time to improve revenue before taking on the asset.','week_1_2','medium','medium','cost'),
  ('capexIntensity','Capex Intensity','critical',0,40,5,'Switch from purchase to lease for any remaining essential capital needs','For any capital requirements that remain essential, switch immediately to an operating lease rather than purchase. Leasing keeps Capex off the statement of cash flows and maintains your Capex intensity ratio. The monthly lease payment is an operating expense — it does not appear as Capex and does not contribute to your Capex intensity problem.','month_1','medium','high','structure'),
  ('capexIntensity','Capex Intensity','critical',0,40,6,'Drive revenue growth to dilute Capex intensity from the top line','If your Capex intensity is critical because revenue is too low relative to the capital you have already spent, the solution is revenue growth — not additional cost cutting. Identify the fastest available revenue growth initiatives using your existing asset base and commit maximum management energy to closing the revenue gap within 90 days.','month_1','medium','high','revenue'),
  ('capexIntensity','Capex Intensity','critical',0,40,7,'Benchmark Capex intensity against your sector and set a 12-month target','Research Capex intensity benchmarks for your sector — manufacturing typically targets 3–8% of revenue, services 1–3%, retail 1–4%. If your current ratio significantly exceeds the sector benchmark, you have a structural over-capitalisation problem. Set a specific 12-month target and map the combination of Capex reduction and revenue growth required to reach it.','month_1','low','medium','operations'),
  ('capexIntensity','Capex Intensity','critical',0,40,8,'Explore sale-and-leaseback to recover capital from existing assets','For your largest fixed assets, assess whether a sale-and-leaseback arrangement would release capital that could repay the debt used to fund the original purchase. Sale-and-leaseback reduces your net Capex position, releases cash, and converts a balance sheet asset into an off-balance-sheet operating expense — improving multiple financial ratios simultaneously.','month_1_3','high','high','structure'),
  ('capexIntensity','Capex Intensity','critical',0,40,9,'Establish a formal Capex approval process with ROI requirements','Implement a formal capital expenditure approval process requiring every Capex request to include a projected ROI, payback period, and Capex intensity impact. Any investment with a payback period above 36 months or a Capex intensity impact above your sector benchmark should require explicit board or owner approval. This process prevents the undisciplined capital spending that creates critical Capex intensity positions.','month_1_3','medium','medium','structure'),
  ('capexIntensity','Capex Intensity','critical',0,40,10,'Build a 24-month Capex rationalisation and revenue restoration plan','Create a structured 24-month plan combining Capex reduction, deferred projects, lease conversions, and revenue growth to return Capex intensity to within the sector benchmark range. Include quarterly milestones for both Capex committed and revenue generated. Review with your accountant quarterly. Without a written plan, Capex intensity recovery defaults to inertia.','month_3_6','medium','high','structure'),
  ('capexIntensity','Capex Intensity','at_risk',40,65,1,'Calculate your Capex-to-revenue ratio and compare to sector benchmark','Divide your annual Capex spend by your annual revenue and compare the result to your sector benchmark. If you are above the benchmark, you are spending more on capital than revenue justifies. If you are below, you may be under-investing in future capacity. Either direction requires a different response — benchmark first, then decide.','immediate','low','medium','operations'),
  ('capexIntensity','Capex Intensity','at_risk',40,65,2,'Implement a formal Capex approval process with ROI thresholds','Require every capital expenditure above a defined threshold — for example R25 000 — to include a projected ROI, payback period, and Capex intensity impact before approval. Establish a maximum payback period — typically 24–36 months for an SME — as a hard threshold. Capital spending without ROI discipline is the primary driver of at-risk Capex intensity.','immediate','low','medium','structure'),
  ('capexIntensity','Capex Intensity','at_risk',40,65,3,'Defer all planned Capex not committed within the next 12 months','Review your Capex pipeline for the next 12 months and defer any project that is not already contractually committed and does not have a clear revenue connection within 6 months of deployment. Deferred Capex preserves cash, improves the ratio immediately, and buys time to assess whether each project remains strategically justified.','week_1_2','low','medium','cost'),
  ('capexIntensity','Capex Intensity','at_risk',40,65,4,'Adopt lease-first policy for all future capital requirements','For all future capital requirements, default to operating leases before considering purchase. Leasing keeps assets off the Capex line, maintains operational capacity, and converts capital commitments to predictable monthly operating expenses. Implement this as a standing policy — only override it when the total five-year ownership cost is materially below the lease cost.','month_1','low','medium','structure'),
  ('capexIntensity','Capex Intensity','at_risk',40,65,5,'Review all committed Capex projects for ROI and payback adequacy','For every capital project currently in progress or already committed, calculate the expected ROI and payback period based on current revenue assumptions. Any project where payback exceeds 36 months should be reviewed for scope reduction, cost optimisation, or accelerated revenue deployment to shorten the payback timeline.','month_1','medium','medium','operations'),
  ('capexIntensity','Capex Intensity','at_risk',40,65,6,'Track Capex-to-revenue ratio quarterly as a KPI','Add Capex intensity to your quarterly KPI dashboard alongside revenue growth and asset turnover. Quarterly tracking allows you to see whether your improvement initiatives are working and whether the ratio is moving in the right direction. An at-risk ratio tracked monthly is caught early; one reviewed only at year-end is managed too late.','month_1','low','medium','operations'),
  ('capexIntensity','Capex Intensity','at_risk',40,65,7,'Maximise revenue from recent capital investments to improve the ratio','Identify assets acquired in the last 12–24 months and assess whether they are generating their projected revenue. For any asset generating below-projection revenue, implement an intensive 90-day plan to close the gap — additional sales effort, new customer targeting, extended operating hours, or revised pricing on the output. Revenue acceleration from existing assets is the fastest available Capex intensity improvement.','month_1_3','medium','medium','revenue'),
  ('capexIntensity','Capex Intensity','at_risk',40,65,8,'Explore co-investment or equipment sharing for major capital needs','For large capital items that are needed but would push Capex intensity further at-risk, explore co-investment with a complementary business or shared equipment arrangements. Splitting the capital cost of shared assets between two non-competing businesses halves the Capex intensity impact while maintaining access to the required capacity.','month_1_3','high','medium','structure'),
  ('capexIntensity','Capex Intensity','at_risk',40,65,9,'Evaluate whether government incentives can fund qualifying Capex','Research current SEDA, IDC, dti, and sector-specific incentive programmes that offer grants or concessionary funding for qualifying capital investment. South Africa''s manufacturing, agri-processing, and technology sectors have several grant and incentive programmes that can fund 15–50% of qualifying Capex. Incentive-funded capital does not impact your Capex intensity the same way as debt-funded capital.','month_1_3','medium','medium','structure'),
  ('capexIntensity','Capex Intensity','at_risk',40,65,10,'Build a 12-month Capex budget aligned to revenue growth targets','Create a 12-month Capex budget that explicitly links each capital commitment to a specific revenue target — the incremental revenue the investment generates within 12 months. Total Capex should be sized to maintain your sector benchmark Capex intensity at your planned revenue level. A revenue-linked Capex budget converts capital spending from a cost to an investment.','month_3_6','medium','high','structure'),
  ('capexIntensity','Capex Intensity','healthy',65,100,1,'Document your Capex governance process and ROI thresholds','Write down your current Capex approval process — the ROI thresholds, payback period limits, approval authorities, and post-investment review procedure. This documentation protects a healthy Capex intensity from eroding when staff change and provides a reference for consistent capital allocation decision-making as the business grows.','month_1','low','low','operations'),
  ('capexIntensity','Capex Intensity','healthy',65,100,2,'Benchmark Capex intensity annually against your sector','Compare your Capex-to-revenue ratio to your sector benchmark annually. A healthy intensity should be confirmed against current benchmarks each year — industry capital requirements change with technology, regulation, and competitive dynamics. Benchmark annually to ensure your healthy ratio reflects genuine capital efficiency rather than under-investment.','month_1','low','medium','operations'),
  ('capexIntensity','Capex Intensity','healthy',65,100,3,'Conduct a post-investment review on all major Capex of the past 24 months','Review every significant capital investment made in the last 24 months against its projected ROI and payback period. Identify which investments have delivered as expected and which have underperformed. This retrospective review improves future capital allocation decisions and identifies any assets that are underperforming and need an activation plan.','month_1','medium','medium','operations'),
  ('capexIntensity','Capex Intensity','healthy',65,100,4,'Use healthy Capex position to access growth investment funding','A healthy Capex intensity, combined with strong asset productivity metrics, is a compelling argument for growth capital from lenders and investors. Use your Capex efficiency track record in facility applications and investor presentations. Businesses that demonstrate disciplined capital spending attract capital at lower cost than those with a history of over-capitalisation.','month_1_3','low','medium','structure'),
  ('capexIntensity','Capex Intensity','healthy',65,100,5,'Assess whether under-investment risk exists at current Capex levels','A healthy Capex intensity can conceal under-investment if your capital base is ageing. Calculate your asset reinvestment ratio — Capex divided by depreciation. A ratio below 1.0x means you are not replacing assets as fast as they depreciate, which may indicate a future asset productivity problem. Assess whether current Capex adequately maintains and grows your productive capacity.','month_1_3','medium','medium','risk'),
  ('capexIntensity','Capex Intensity','healthy',65,100,6,'Develop a three-year Capex roadmap aligned to your growth strategy','Create a three-year Capex plan identifying the capital investments required to support your revenue targets at each milestone. For each investment, specify the expected revenue contribution, ROI, payback period, and Capex intensity impact. A three-year Capex plan converts capital spending from a reactive annual budget exercise into a strategic growth enabler.','month_3_6','medium','high','structure'),
  ('capexIntensity','Capex Intensity','healthy',65,100,7,'Research government and DFI incentives for qualifying growth Capex','Proactively research SEDA, IDC, dti, and sector-specific grant and incentive programmes that could partially fund your planned growth Capex. Incentive-funded capital reduces effective Capex intensity and improves returns on growth investment. Many qualifying businesses are unaware of or too slow to access available programmes. Build grant research into your annual Capex planning process.','month_3_6','medium','medium','cost'),
  ('capexIntensity','Capex Intensity','healthy',65,100,8,'Stress-test Capex intensity under a revenue shortfall scenario','Model your Capex intensity if revenue fell 25% for two consecutive years while committed Capex remained unchanged. Identify the specific Capex items that would be deferred first and second. Pre-planning the Capex response to a revenue shock preserves healthy intensity under adverse conditions and maintains lender confidence through downturns.','month_3_6','low','medium','risk'),
  ('capexIntensity','Capex Intensity','healthy',65,100,9,'Evaluate technology investments for disproportionate revenue impact','Identify technology investments — automation, software, data infrastructure — that could generate revenue or cost savings disproportionate to their capital cost. Technology-enabled assets often produce the highest revenue-per-rand-of-Capex returns available and are frequently more scalable than physical assets. Prioritise technology in your Capex pipeline where ROI exceeds physical asset alternatives.','year_1','medium','high','operations'),
  ('capexIntensity','Capex Intensity','healthy',65,100,10,'Include Capex intensity as a metric in shareholder reporting','Present Capex intensity alongside revenue growth, asset turnover, and ROA in your annual shareholder or board report. This demonstrates capital discipline to your stakeholders and positions Capex as a strategic lever rather than a cost. Shareholders who understand your Capex efficiency are more likely to support growth investment decisions that temporarily increase the ratio for a clear strategic return.','year_1','low','medium','structure'),
  ('ocfToEbitda','Cash Quality','critical',0,40,1,'Investigate the specific cause of cash quality deterioration immediately','A critical OCF-to-EBITDA ratio means your reported profit is significantly higher than your actual cash generation. Calculate the gap between EBITDA and OCF and identify its cause — rising debtors, growing inventory, falling creditors, or large one-off working capital movements. Each cause requires a different response and cannot be addressed without precise identification.','immediate','medium','high','cash'),
  ('ocfToEbitda','Cash Quality','critical',0,40,2,'Build a 13-week cash flow forecast immediately','A critical cash quality ratio means your profitability is not translating to cash — the most dangerous form of financial illusion for an SME. Build a 13-week rolling cash forecast listing every confirmed receipt and committed payment. This forecast tells you exactly when cash runs out regardless of what the profit and loss statement shows. Update every Monday.','immediate','medium','high','cash'),
  ('ocfToEbitda','Cash Quality','critical',0,40,3,'Emergency debtor collection campaign on all overdue invoices','If rising debtors are the primary cause of poor cash quality, launch an immediate collections campaign — owner calls all overdue debtors personally, credit holds on all accounts over 45 days, and an offer of 2–3% early payment discount to your five largest debtors. Each rand collected from debtors directly improves OCF and therefore cash quality.','immediate','medium','high','cash'),
  ('ocfToEbitda','Cash Quality','critical',0,40,4,'Freeze inventory purchasing and clear aged stock immediately','If inventory build-up is causing the EBITDA-to-OCF gap, implement an immediate purchasing freeze and initiate clearance of all stock over 45 days old at 25–40% discount. Rising inventory consumes cash without appearing on the profit and loss statement — it is the most common hidden cause of critical cash quality in product businesses.','week_1_2','medium','high','cash'),
  ('ocfToEbitda','Cash Quality','critical',0,40,5,'Extend supplier payment terms to improve the creditor component of OCF','If creditor terms have shortened — either through supplier pressure or your own early payment habit — contact your five largest suppliers and negotiate a 30-day extension. Creditor reductions consume cash and reduce OCF without appearing as a cost on the income statement. Extending terms restores cash quality by reducing the working capital funding drain.','week_1_2','medium','high','cash'),
  ('ocfToEbitda','Cash Quality','critical',0,40,6,'Review income statement for non-cash profit items inflating EBITDA','Work with your accountant to identify any non-cash items boosting reported EBITDA — unrealised gains, accrued but uncollected income, fair value movements, or revenue recognised before cash receipt. Profit that has been recognised but not received inflates EBITDA without improving OCF. Identifying and correcting these items gives you an accurate picture of your true cash generation.','month_1','medium','medium','operations'),
  ('ocfToEbitda','Cash Quality','critical',0,40,7,'Apply for a working capital facility to bridge the cash quality gap','Contact your bank and apply for a working capital facility — overdraft or revolving credit — sized to bridge the gap between your EBITDA and your OCF. This buys operational time while you address the underlying working capital causes. Apply before missing any payments — banks are significantly more receptive to facilities for businesses that engage proactively.','month_1','medium','high','structure'),
  ('ocfToEbitda','Cash Quality','critical',0,40,8,'Switch to cash-basis revenue recognition for management reporting','In addition to statutory accounting, implement a parallel cash-basis management report showing revenue collected rather than invoiced, expenses paid rather than accrued, and actual cash profit rather than accounting profit. Running a business on accrual-basis profitability alone when cash quality is critical is a management visibility failure that delays corrective action.','month_1','medium','medium','operations'),
  ('ocfToEbitda','Cash Quality','critical',0,40,9,'Set a minimum OCF-to-EBITDA target of 80% and track monthly','Define a minimum acceptable cash quality ratio of 80% — meaning at least 80 cents of every rand of EBITDA converts to operating cash flow. Track this ratio monthly alongside EBITDA. A written target makes cash quality management explicit and prevents the gradual erosion that occurs when profitability is managed without reference to its cash conversion rate.','month_1_3','low','medium','operations'),
  ('ocfToEbitda','Cash Quality','critical',0,40,10,'Build a 12-month cash quality recovery plan addressing all working capital drivers','Create a structured 12-month plan with specific monthly OCF-to-EBITDA targets and the debtors, inventory, and creditor actions required to reach them. Assign ownership of each working capital component to a named person. A written recovery plan with monthly milestones is the most reliable way to restore cash quality from a critical position within a financial year.','month_1_3','medium','high','cash'),
  ('ocfToEbitda','Cash Quality','at_risk',40,65,1,'Identify the working capital driver causing EBITDA-to-OCF leakage','Compare your EBITDA and OCF for the last three months and calculate the gap. Trace the gap to its working capital source — rising debtors, increasing inventory, falling creditors, or growing WIP. At an at-risk cash quality ratio, one or two drivers typically account for 70–80% of the conversion gap. Correct identification directs your improvement effort efficiently.','immediate','medium','medium','cash'),
  ('ocfToEbitda','Cash Quality','at_risk',40,65,2,'Set an OCF-to-EBITDA target of 85% and track monthly','Define a monthly cash quality target of 85% — 85 cents of OCF for every rand of EBITDA. A target of 85% is achievable in most SME sectors and signals healthy working capital management. Track actual versus target monthly and attribute any shortfall to its specific working capital cause. A tracked target is managed; an untracked ratio is hoped for.','immediate','low','medium','operations'),
  ('ocfToEbitda','Cash Quality','at_risk',40,65,3,'Reduce debtor days by 10 days within 60 days','Implement a focused collections improvement targeting a 10-day reduction in average debtor days within 60 days through weekly follow-up calls, same-day invoicing, and early payment incentives. A 10-day reduction in debtor days on R5 million annual revenue improves OCF by approximately R137 000 — a direct and measurable cash quality improvement.','week_1_2','medium','medium','cash'),
  ('ocfToEbitda','Cash Quality','at_risk',40,65,4,'Reduce inventory by 15% within 60 days to improve OCF','Set a target to reduce total inventory value by 15% within 60 days through tighter reorder quantities and clearance of aged stock. Inventory reduction converts balance sheet assets to operating cash flow, directly improving your OCF-to-EBITDA ratio. Monitor inventory value weekly and track the cash conversion impact monthly.','month_1','medium','medium','cash'),
  ('ocfToEbitda','Cash Quality','at_risk',40,65,5,'Extend creditor terms by 15 days to improve OCF conversion','Negotiate a 15-day extension on payment terms with your three largest suppliers. Extended creditor terms reduce the cash outflow required for the same level of purchases, improving OCF without affecting EBITDA. Each day of creditor extension on significant supplier spend produces a direct OCF improvement that shows up in your cash quality ratio.','month_1','medium','medium','cash'),
  ('ocfToEbitda','Cash Quality','at_risk',40,65,6,'Add cash flow statement to your monthly management reporting','If you are only reviewing a profit and loss statement monthly, add a cash flow statement showing the movement from EBITDA to OCF. Most at-risk cash quality positions are invisible to business owners managing on profitability alone. The monthly cash flow statement makes the EBITDA-to-OCF conversion rate explicit and visible — turning it from a hidden drag into a managed metric.','month_1','low','medium','operations'),
  ('ocfToEbitda','Cash Quality','at_risk',40,65,7,'Review revenue recognition policy for any early or aggressive recognition','Work with your accountant to confirm that your revenue recognition policy is conservative and consistent. Revenue recognised before cash receipt or before delivery of the contracted obligation inflates EBITDA without generating OCF. If any revenue is being recognised before it is earned or collected, correcting the policy will align EBITDA more closely with OCF.','month_1','medium','medium','operations'),
  ('ocfToEbitda','Cash Quality','at_risk',40,65,8,'Introduce progress billing to improve cash conversion on long projects','For project-based or long-cycle revenue, implement progress billing at defined milestones. Progress billing converts project revenue from a deferred cash receipt — which reduces OCF relative to EBITDA — to a series of earlier cash receipts that align more closely with cost incurrence. This structural change improves cash quality on all future project revenue.','month_1_3','medium','medium','cash'),
  ('ocfToEbitda','Cash Quality','at_risk',40,65,9,'Model the cash quality impact of each working capital initiative separately','For each working capital improvement initiative — debtor days reduction, inventory reduction, creditor extension — model its specific impact on OCF and therefore on OCF-to-EBITDA. Quantifying the cash quality improvement from each initiative helps prioritise effort toward the highest-impact levers and creates accountability for each improvement owner.','month_1_3','medium','medium','operations'),
  ('ocfToEbitda','Cash Quality','at_risk',40,65,10,'Set a 12-month cash quality improvement plan with quarterly milestones','Build a 12-month OCF-to-EBITDA improvement plan with quarterly targets and the specific working capital actions required to reach each milestone. Target reaching 85% cash quality within 12 months and 90%+ within 24 months. Review quarterly with your accountant and adjust initiatives if actuals diverge from plan.','month_3_6','medium','high','cash'),
  ('ocfToEbitda','Cash Quality','healthy',65,100,1,'Document your cash quality baseline and working capital drivers','Record your current OCF-to-EBITDA ratio, the working capital components driving it — debtor days, inventory days, creditor days — and any known seasonal or cyclical patterns in cash conversion. This baseline protects your healthy cash quality from eroding when business conditions or staff change.','month_1','low','low','operations'),
  ('ocfToEbitda','Cash Quality','healthy',65,100,2,'Include cash flow statement in monthly management reporting','Ensure your monthly management accounts include a cash flow statement alongside the profit and loss and balance sheet. Tracking OCF monthly — and computing the OCF-to-EBITDA ratio — maintains visibility of cash quality as a managed metric rather than a retrospective discovery at year-end. Monthly cash flow reporting is a hallmark of financially disciplined SME management.','month_1','low','medium','operations'),
  ('ocfToEbitda','Cash Quality','healthy',65,100,3,'Stress-test cash quality against a debtor collection and inventory shock','Model your OCF-to-EBITDA ratio if debtor days extended by 30 days and inventory increased by 20% simultaneously — a scenario that could occur if a major customer slowed payment during an economic downturn while you over-ordered in anticipation of demand. Identify the OCF impact and pre-plan the working capital actions you would take.','month_1','low','medium','risk'),
  ('ocfToEbitda','Cash Quality','healthy',65,100,4,'Use strong cash quality to fund growth from operating cash flow','A healthy OCF-to-EBITDA ratio means your profits are converting efficiently to cash. This cash generation is a self-funding growth resource. Develop a plan to fund incremental growth investments — new staff, market expansion, product development — from OCF rather than external debt, reducing leverage and preserving balance sheet strength.','month_1_3','medium','high','cash'),
  ('ocfToEbitda','Cash Quality','healthy',65,100,5,'Invest surplus OCF in yield-bearing instruments to compound return','If your healthy cash quality generates a consistent OCF surplus above operational needs, deploy it in money market funds, treasury bills, or short-dated bonds rather than leaving it in a current account. South African money market rates of 6–9% per year generate meaningful return on a sustained OCF surplus and compound the financial advantage of excellent cash quality.','month_1_3','low','medium','cash'),
  ('ocfToEbitda','Cash Quality','healthy',65,100,6,'Use OCF to accelerate debt repayment and reduce leverage','Allocate a defined percentage of monthly OCF — for example 20–25% — to accelerated debt repayment above minimum instalments. Strong cash quality provides the ability to deleverage faster than the minimum schedule requires. Early debt repayment reduces interest cost, improves equity solvency, and increases future OCF by eliminating interest charges.','month_3_6','medium','high','structure'),
  ('ocfToEbitda','Cash Quality','healthy',65,100,7,'Model three-year OCF generation for strategic capital planning','Project your OCF for each of the next three years based on your revenue growth targets and current cash quality ratio. This three-year OCF forecast shows how much capital you will generate internally — telling you how much external funding you will need for growth and how quickly you can fund strategic investments from operations.','month_3_6','medium','high','structure'),
  ('ocfToEbitda','Cash Quality','healthy',65,100,8,'Protect cash quality during growth by managing working capital proactively','As revenue grows, the absolute working capital required to maintain your current CCC increases — and if not managed proactively, OCF-to-EBITDA can decline even as profitability improves. Build working capital management disciplines — collections, inventory reorder controls, creditor terms — that scale with revenue to protect your cash quality through growth.','month_3_6','medium','high','cash'),
  ('ocfToEbitda','Cash Quality','healthy',65,100,9,'Present OCF-to-EBITDA in shareholder reporting as a quality indicator','Include OCF-to-EBITDA in your annual shareholder or board report as a measure of earnings quality. Shareholders who understand that your profits convert efficiently to cash have greater confidence in reported earnings than those who see only profit figures. Cash quality is a differentiating metric in investor and lender conversations that most SMEs overlook.','year_1','low','medium','operations'),
  ('ocfToEbitda','Cash Quality','healthy',65,100,10,'Maintain OCF-to-EBITDA above 85% as a financial governance target','Set a formal financial governance target of maintaining OCF-to-EBITDA above 85% in every financial year. Include this target in your annual board or management objectives alongside profitability and revenue growth metrics. A business that sustains cash quality above 85% over multiple years demonstrates the combination of profitability and working capital discipline that creates durable financial strength.','year_1','low','high','structure'),
  ('dol','Operating Leverage','critical',0,40,1,'Calculate your DOL and understand your revenue sensitivity today','Divide contribution margin by EBIT to calculate your Degree of Operating Leverage. A critical DOL — either extremely high or negative — means your EBIT is highly sensitive to small revenue changes or that you are operating at a loss. If DOL is above 10x, a 10% revenue decline produces a 100% EBIT decline. You must know this number before making any operational decision.','immediate','low','high','risk'),
  ('dol','Operating Leverage','critical',0,40,2,'Reduce fixed costs immediately to lower your operating leverage','High DOL is caused by high fixed costs relative to EBIT. Every fixed cost you eliminate reduces your DOL and makes the business less vulnerable to revenue swings. Cancel all non-essential fixed costs today — subscriptions, retainers, non-critical services — and target a 20% reduction in monthly fixed costs within 30 days.','immediate','medium','high','cost'),
  ('dol','Operating Leverage','critical',0,40,3,'Convert fixed costs to variable costs wherever possible immediately','Identify fixed cost lines that could be restructured as variable — switch salaried roles to contractor arrangements, fixed retainers to usage-based pricing, fixed supplier agreements to volume-based pricing. Every fixed cost converted to variable reduces your DOL and makes EBIT more resilient to revenue fluctuations.','week_1_2','high','high','structure'),
  ('dol','Operating Leverage','critical',0,40,4,'Grow revenue to increase EBIT and reduce DOL simultaneously','DOL improves as EBIT grows relative to fixed costs. Every additional rand of contribution margin above break-even flows directly to EBIT — reducing the sensitivity of EBIT to revenue changes. Identify and immediately pursue the fastest available revenue growth opportunities using existing capacity. Revenue above break-even is your most powerful DOL reduction tool.','week_1_2','medium','high','revenue'),
  ('dol','Operating Leverage','critical',0,40,5,'Calculate your break-even revenue and how far you are from it','Divide total monthly fixed costs by your contribution margin percentage to determine your break-even revenue. If you are below break-even, your DOL is technically infinite or negative — every dollar of revenue is moving you toward survival. Knowing exactly how far you are from break-even gives you a single, clear target to manage toward.','week_1_2','low','high','operations'),
  ('dol','Operating Leverage','critical',0,40,6,'Improve contribution margin by raising prices or cutting variable costs','A higher contribution margin percentage reduces your break-even revenue point and lowers your DOL at the same EBIT level. Implement a 10–15% price increase on your highest-volume products or reduce variable costs by 10% through supplier renegotiation. Both approaches improve contribution margin and reduce operating leverage risk simultaneously.','month_1','medium','high','revenue'),
  ('dol','Operating Leverage','critical',0,40,7,'Diversify revenue to reduce single-source operating leverage risk','A high DOL business with concentrated revenue is extremely vulnerable — a single large customer loss or market disruption can wipe out EBIT entirely. Identify two or three new revenue sources that can be developed within 90 days and begin active development now. Revenue diversification is the most important structural risk mitigation for a high-leverage operating model.','month_1','medium','medium','risk'),
  ('dol','Operating Leverage','critical',0,40,8,'Build a DOL scenario model showing EBIT at different revenue levels','Create a simple table showing your projected EBIT at revenue levels 10%, 20%, and 30% below current — and 10% and 20% above. This model makes your operating leverage risk concrete and visible. Share it with your management team. Teams that understand the EBIT consequences of revenue changes make better decisions about pricing, discounting, and cost commitments.','month_1','low','medium','risk'),
  ('dol','Operating Leverage','critical',0,40,9,'Negotiate performance-linked arrangements with key staff','Convert a portion of fixed salaries for key staff to a variable performance component — base salary plus a percentage of revenue or gross profit generated. This reduces fixed payroll — your largest fixed cost in most service businesses — and aligns staff incentives with the revenue performance that reduces operating leverage risk. Consult an HR practitioner to ensure employment law compliance.','month_1_3','high','high','people'),
  ('dol','Operating Leverage','critical',0,40,10,'Build a 12-month operating leverage reduction plan with monthly targets','Create a structured 12-month plan targeting a specific DOL reduction through fixed cost elimination, variable cost conversion, contribution margin improvement, and revenue growth. Set a monthly DOL target and track progress against it. A DOL above 5x on a stable business is manageable; reaching that level from critical requires a written plan with accountability.','month_1_3','medium','high','structure'),
  ('dol','Operating Leverage','at_risk',40,65,1,'Calculate your DOL and revenue sensitivity at current EBIT','Divide contribution margin by EBIT to get your current DOL. Use this to calculate your EBIT sensitivity — a DOL of 5x means a 10% revenue decline produces a 50% EBIT decline. An at-risk DOL typically falls in the 3x–8x range. Understanding your exact sensitivity helps you set appropriate revenue protection and cost management priorities.','immediate','low','medium','risk'),
  ('dol','Operating Leverage','at_risk',40,65,2,'Build a DOL sensitivity model for revenue at plus and minus 15%','Model your EBIT at current revenue minus 15% and minus 30% and at current revenue plus 15%. This model makes your operating leverage risk concrete. If a 15% revenue decline would push you to break-even or below, you have insufficient EBIT buffer for an at-risk DOL. Use this model to determine the minimum revenue protection strategy required.','immediate','low','medium','risk'),
  ('dol','Operating Leverage','at_risk',40,65,3,'Identify and reduce your five largest fixed cost lines by 10%','List your five largest fixed cost categories and target a 10% reduction on each within 60 days. Reducing fixed costs lowers your break-even point, expands the EBIT buffer above break-even, and reduces DOL — all simultaneously. A 10% reduction on your top five fixed costs typically improves DOL meaningfully on most at-risk businesses.','week_1_2','medium','medium','cost'),
  ('dol','Operating Leverage','at_risk',40,65,4,'Implement a 5–8% price increase to improve contribution margin','A price increase improves contribution margin percentage and shifts break-even revenue lower, reducing DOL at the same revenue level. On a business with 40% contribution margin, a 5% price increase with stable variable costs increases contribution margin to approximately 45% — reducing break-even revenue by more than 10% and improving DOL materially.','week_1_2','low','medium','revenue'),
  ('dol','Operating Leverage','at_risk',40,65,5,'Convert one or two fixed cost roles to variable or output-based arrangements','Identify one or two fixed salary roles that could be restructured as contractor or output-based arrangements without disrupting operations. Each fixed cost converted to variable reduces your break-even point and your DOL. Focus on roles in functions where output is measurable and variable compensation is commercially viable and legally compliant.','month_1','high','medium','people'),
  ('dol','Operating Leverage','at_risk',40,65,6,'Diversify revenue to reduce EBIT sensitivity to any single source','Identify two or three new revenue streams that can be developed within 6 months and begin active pursuit. Revenue diversification does not directly change DOL, but it reduces the probability of a large revenue decline that would trigger the EBIT sensitivity your DOL represents. A high-DOL business with diversified revenue is safer than the same DOL with concentrated revenue.','month_1','medium','medium','risk'),
  ('dol','Operating Leverage','at_risk',40,65,7,'Build contribution margin reporting into your monthly management accounts','Add contribution margin percentage and EBIT to your monthly management accounts and track both alongside DOL. Monitoring the contribution margin trend tells you whether fixed cost coverage is improving or deteriorating before it shows up in EBIT. A monthly management account that shows contribution margin gives you an earlier warning than one showing only gross and operating margin.','month_1','medium','medium','operations'),
  ('dol','Operating Leverage','at_risk',40,65,8,'Grow revenue using existing capacity to reduce DOL from the top line','Revenue growth above break-even flows entirely to EBIT — rapidly reducing DOL from a high level. Identify and immediately pursue the fastest available revenue opportunities using your current fixed cost base. Every rand of additional contribution margin generated from existing fixed capacity reduces DOL by improving the denominator of the formula.','month_1_3','medium','high','revenue'),
  ('dol','Operating Leverage','at_risk',40,65,9,'Build a cash reserve buffer to absorb revenue volatility','At an at-risk DOL, you need a cash buffer proportional to your revenue sensitivity. Target a cash reserve of at least three months of fixed costs — this provides operational continuity through a revenue downturn without requiring emergency borrowing or destructive cost cuts. Build this reserve systematically from monthly OCF over the next 12 months.','month_1_3','medium','high','cash'),
  ('dol','Operating Leverage','at_risk',40,65,10,'Set a target DOL of 3–5x and build a plan to reach it within 18 months','Define a target DOL of 3–5x — a level where a 20% revenue decline produces a 60–100% EBIT decline that the business can survive with its cash buffer intact — and build a structured plan of fixed cost reduction, variable conversion, margin improvement, and revenue growth to reach it within 18 months. Review quarterly.','month_3_6','medium','high','structure'),
  ('dol','Operating Leverage','healthy',65,100,1,'Calculate current DOL and document your break-even revenue','Confirm your current DOL and break-even revenue as a baseline. A healthy DOL — typically 2–4x — means your EBIT is relatively stable against moderate revenue swings. Document these numbers and review them quarterly. Understanding your operating leverage structure is the foundation of confident revenue and cost decision-making.','month_1','low','low','operations'),
  ('dol','Operating Leverage','healthy',65,100,2,'Use healthy DOL to justify growth investment from fixed capacity','A healthy DOL means your fixed cost base can support revenue growth at very low incremental cost — each additional sale flows largely to EBIT. Use this operating leverage advantage to justify growth investment in sales, marketing, and customer acquisition. The business economics of growing revenue above break-even are extremely favourable at a healthy DOL.','month_1','low','high','revenue'),
  ('dol','Operating Leverage','healthy',65,100,3,'Stress-test DOL against a 25% revenue decline scenario','Model your EBIT at revenue levels 10%, 20%, and 25% below current. Identify the revenue level at which you would breach break-even and the specific fixed cost actions you would take at each threshold. Pre-planned responses to revenue stress scenarios allow faster and more decisive action — preserving more EBIT than improvised reactions.','month_1','low','medium','risk'),
  ('dol','Operating Leverage','healthy',65,100,4,'Build a cash buffer of three months fixed costs as an operating leverage hedge','Maintain a cash reserve equivalent to at least three months of total fixed costs. This buffer provides the time and liquidity to respond to a revenue decline without making destructive emergency cost cuts. At a healthy DOL, the buffer protects the advantage you have built — and prevents a temporary revenue setback from becoming a structural problem.','month_1_3','medium','high','cash'),
  ('dol','Operating Leverage','healthy',65,100,5,'Protect DOL during growth by adding variable rather than fixed capacity','As you grow revenue, resist the instinct to scale fixed costs proportionally. Invest in variable capacity first — contractors, outsourced functions, part-time staff, usage-based technology — before adding permanent fixed costs. Maintaining your healthy DOL through growth requires deliberate variable-first capacity planning.','month_1_3','medium','high','structure'),
  ('dol','Operating Leverage','healthy',65,100,6,'Increase contribution margin to create more EBIT buffer above break-even','Improve your contribution margin percentage through pricing or variable cost reduction. A higher contribution margin percentage reduces your break-even revenue, lowers your DOL at the same revenue level, and makes your EBIT more resilient to revenue fluctuations. Even a 3–5 percentage point improvement in contribution margin is meaningful at scale.','month_3_6','medium','medium','revenue'),
  ('dol','Operating Leverage','healthy',65,100,7,'Develop recurring revenue to stabilise the denominator of operating leverage','Build recurring or subscription revenue streams that provide a stable, predictable contribution margin floor. Recurring revenue reduces revenue volatility — the primary risk factor for a high-DOL business. Even converting 20–30% of revenue to recurring significantly reduces the probability of a large revenue decline that would trigger your operating leverage sensitivity.','month_3_6','high','high','revenue'),
  ('dol','Operating Leverage','healthy',65,100,8,'Include DOL in your annual strategic risk assessment','Make DOL a standing item in your annual strategic risk review — assessed alongside customer concentration, supplier dependency, and market risk. Model your EBIT sensitivity under each major risk scenario using your current DOL. A business that manages operating leverage as a strategic risk produces more resilient performance through economic cycles than one that ignores it.','month_3_6','low','medium','risk'),
  ('dol','Operating Leverage','healthy',65,100,9,'Link team incentives to contribution margin and EBIT performance','Design your management team incentive scheme to reward contribution margin generation and EBIT performance alongside revenue growth. Teams incentivised on revenue alone tend to grow fixed costs proportionally with revenue — eroding DOL. Teams incentivised on EBIT naturally protect fixed cost discipline while pursuing revenue growth.','year_1','medium','medium','people'),
  ('dol','Operating Leverage','healthy',65,100,10,'Build operating leverage management into your three-year growth plan','Include a deliberate operating leverage strategy in your three-year plan — specifying target DOL at each revenue milestone, the fixed-to-variable cost mix required to achieve it, and the contribution margin percentage that will sustain it. Businesses that manage operating leverage as a strategic variable rather than an accounting outcome generate more durable and resilient EBIT growth.','year_1','medium','high','structure'),
  ('gpToLabor','Labor ROI','critical',0,40,1,'Calculate labor ROI by department and identify the worst performers','Divide gross profit by labor cost for each department or team, not just for the business overall. A blended critical Labor ROI almost always has one or two departments generating significantly negative returns that drag down the overall ratio. Identifying the specific underperforming teams is the prerequisite for targeted intervention.','immediate','medium','high','people'),
  ('gpToLabor','Labor ROI','critical',0,40,2,'Implement emergency price increases to restore gross profit per labor rand','Increase prices on your highest-volume products and services by 10–20% immediately. Every rand of additional gross profit generated by existing staff directly improves Labor ROI. Price increases are the fastest available mechanism to restore gross profit without changing headcount. Test with a subset of customers before full rollout.','immediate','low','high','revenue'),
  ('gpToLabor','Labor ROI','critical',0,40,3,'Freeze all hiring and review all discretionary labor costs immediately','Place an immediate freeze on all new hires, temporary staff increases, and discretionary contractor spend. Review all current labor costs — overtime, agency staff, consultants — and cancel any that are not directly linked to revenue generation. At a critical Labor ROI, every additional rand of labor cost must be justified by an immediate gross profit return.','immediate','low','high','people'),
  ('gpToLabor','Labor ROI','critical',0,40,4,'Map every staff role to its gross profit contribution','Create a role-level map showing each employee''s total cost and the gross profit they directly generate or enable. Roles with no visible gross profit contribution — administrative, support, or duplicated functions — are candidates for restructuring. At a critical Labor ROI, every role must justify its cost through a clear and direct contribution to gross profit.','week_1_2','medium','high','people'),
  ('gpToLabor','Labor ROI','critical',0,40,5,'Eliminate your lowest-margin products to free labor for higher-return work','Stop producing and selling your three lowest gross margin product lines. In most businesses, lower-margin products consume disproportionate labor relative to their gross profit contribution. Freeing that labor for higher-margin work improves Labor ROI without reducing headcount — it is a reallocation, not a reduction.','week_1_2','medium','high','revenue'),
  ('gpToLabor','Labor ROI','critical',0,40,6,'Review and restructure underperforming roles before considering retrenchment','Before initiating retrenchments — which are costly, legally complex, and damaging to morale — exhaust all restructuring options: reassignment to higher-value work, reduced hours, performance plans, and role redefinition. Retrenchments in South Africa require a Section 189 process with consultation — always take legal advice first. Restructuring often improves Labor ROI faster and at lower cost than retrenchment.','month_1','high','high','people'),
  ('gpToLabor','Labor ROI','critical',0,40,7,'Implement sales targets linked to gross profit not revenue','Redesign your sales incentives so that salespeople are rewarded on gross profit generated, not gross revenue. Salespeople paid on revenue will discount aggressively and bring in low-margin work that worsens Labor ROI. Salespeople paid on gross profit protect pricing and focus effort on high-margin products — directly improving the numerator of the Labor ROI formula.','month_1','medium','high','people'),
  ('gpToLabor','Labor ROI','critical',0,40,8,'Measure and improve direct labor productivity by 15% within 90 days','Calculate output per labor hour for your core production or service delivery function and set a 15% productivity improvement target within 90 days. Productivity improvement from the same labor cost directly increases gross profit per labor rand. Assign a manager to lead the productivity initiative with weekly measurement and accountability.','month_1','medium','medium','operations'),
  ('gpToLabor','Labor ROI','critical',0,40,9,'Reduce direct cost burden to improve gross profit per labor rand','Gross profit is revenue minus COGS. Any reduction in COGS — through supplier renegotiation, waste reduction, or process improvement — directly increases gross profit without adding labor cost, improving Labor ROI from the numerator. Identify your three largest COGS line items and target a 10% reduction on each within 60 days.','month_1_3','medium','medium','cost'),
  ('gpToLabor','Labor ROI','critical',0,40,10,'Build a 12-month Labor ROI recovery plan with monthly milestones','Create a structured 12-month recovery plan targeting a specific Labor ROI improvement through revenue growth, gross margin improvement, productivity gains, and labor cost discipline. Set monthly gross profit and labor cost targets and review with your management team at the start of each month. A written plan with monthly accountability produces faster Labor ROI recovery than reactive management.','month_3_6','medium','high','structure'),
  ('gpToLabor','Labor ROI','at_risk',40,65,1,'Calculate Labor ROI by team and product line to isolate underperformance','Break your Labor ROI calculation down by department, team, or product line to identify which areas are pulling the overall ratio below benchmark. An at-risk blended ratio almost always masks specific underperforming segments subsidised by stronger ones. Identifying the specific underperformers allows targeted intervention rather than across-the-board action.','immediate','medium','medium','people'),
  ('gpToLabor','Labor ROI','at_risk',40,65,2,'Benchmark your Labor ROI against your sector','Research gross profit to labor cost ratios for businesses at your scale and sector. Professional services typically target GP-to-labor ratios of 2.0x–3.0x, manufacturing 1.5x–2.5x, and retail 1.8x–2.5x. Knowing where you stand relative to peers gives you a specific improvement target and helps identify whether your problem is a revenue, margin, or labor cost issue.','immediate','low','medium','people'),
  ('gpToLabor','Labor ROI','at_risk',40,65,3,'Implement gross-profit-linked sales incentives immediately','Redesign sales commission structures to reward gross profit generated rather than revenue. This single change typically improves Labor ROI within two to three months as salespeople naturally gravitate toward higher-margin products and stop discounting aggressively. Model the commission change using the last six months of sales data before implementing.','week_1_2','medium','medium','people'),
  ('gpToLabor','Labor ROI','at_risk',40,65,4,'Implement a 5–8% price increase on your highest-volume products','A price increase improves gross profit without increasing labor cost — directly improving Labor ROI. Test a 5–8% increase on your least price-sensitive products and monitor volume impact over 30 days. Even a 3 percentage point improvement in gross margin on a stable labor cost base produces a meaningful Labor ROI improvement.','month_1','low','medium','revenue'),
  ('gpToLabor','Labor ROI','at_risk',40,65,5,'Measure output per labor hour and set a 10% productivity improvement target','Calculate revenue or gross profit generated per labor hour in your core production or service function. Set a 10% productivity improvement target over 90 days through better scheduling, reduced downtime, or process improvement. A 10% improvement in productivity generates the same gross profit from 10% fewer labor hours — directly improving Labor ROI.','month_1','medium','medium','operations'),
  ('gpToLabor','Labor ROI','at_risk',40,65,6,'Redirect labor toward your highest-margin products and services','Analyse how your team''s time is allocated across your product and service range and identify where labor is being spent on lower-margin activities. Redirect 20–30% of labor capacity toward your highest-margin products — the mix shift improves gross profit from the same labor cost. Track gross profit per team per month to measure the impact.','month_1','medium','medium','revenue'),
  ('gpToLabor','Labor ROI','at_risk',40,65,7,'Control labor cost growth to below gross profit growth rate','Set a policy that any increase in total labor cost must be accompanied by a proportionally larger increase in gross profit. Track both monthly and flag any period where labor cost grows faster than gross profit. This simple discipline prevents the gradual labor cost drift that converts healthy Labor ROI into an at-risk ratio over 12–24 months.','month_1','low','medium','people'),
  ('gpToLabor','Labor ROI','at_risk',40,65,8,'Explore automation to reduce direct labor intensity on high-volume tasks','Identify your most labor-intensive high-volume production or service tasks and research automation or semi-automation options. A technology investment with a 24-month payback that reduces direct labor by 15% improves Labor ROI permanently — unlike a price increase or productivity initiative that may require ongoing management.','month_1_3','high','medium','operations'),
  ('gpToLabor','Labor ROI','at_risk',40,65,9,'Develop a training programme to improve labor output quality and speed','Invest in skills development for your frontline production or service delivery staff — improving both the speed and quality of output from the same labor cost. Skills-driven productivity improvement is more sustainable than pressure-driven productivity and typically yields 10–20% gains on well-targeted training programmes. In South Africa, SETA grants can fund qualifying training at minimal cost.','month_1_3','medium','medium','people'),
  ('gpToLabor','Labor ROI','at_risk',40,65,10,'Set a 12-month Labor ROI target with quarterly milestones','Define a specific 12-month Labor ROI target and build a plan addressing gross profit improvement, labor productivity, and mix shift toward higher-margin work. Set quarterly milestones and review with your operations and HR leads. A written Labor ROI plan with milestones produces more consistent improvement than ad-hoc interventions.','month_3_6','medium','high','people'),
  ('gpToLabor','Labor ROI','healthy',65,100,1,'Benchmark Labor ROI against top-quartile industry peers','Compare your Labor ROI against the top quartile — not just the median — for businesses at your scale and sector. If you are at the median, there is a clear improvement opportunity. If you are above the median but below the top quartile, a specific performance gap remains. Top-quartile Labor ROI is the objective, not merely above-median performance.','month_1','low','low','people'),
  ('gpToLabor','Labor ROI','healthy',65,100,2,'Track Labor ROI monthly by team and product line','Maintain monthly Labor ROI reporting broken down by department and product line. Healthy overall Labor ROI can conceal underperforming segments that are masked by strong performers. Monthly granular tracking allows you to identify emerging underperformance at the unit level before it affects the blended ratio.','month_1','medium','medium','people'),
  ('gpToLabor','Labor ROI','healthy',65,100,3,'Protect Labor ROI by ensuring labor growth lags gross profit growth','Set a standing rule that total labor cost may only grow at 80% of the rate of gross profit growth. This discipline ensures your Labor ROI improves as the business scales rather than eroding through proportional headcount expansion. Review the ratio of labor cost growth to gross profit growth quarterly and flag any breach for management attention.','month_1','low','medium','people'),
  ('gpToLabor','Labor ROI','healthy',65,100,4,'Invest in high-performing staff to compound Labor ROI','A healthy Labor ROI gives you the financial capacity to pay above-market rates for exceptional talent. Top performers in revenue-generating roles typically produce 2–3x the gross profit of average performers at the same salary cost — dramatically improving Labor ROI. Invest in identifying, attracting, and retaining your top quartile performers as a strategic Labor ROI initiative.','month_1_3','medium','high','people'),
  ('gpToLabor','Labor ROI','healthy',65,100,5,'Develop a premium product to increase gross profit per labor hour','Design a premium version of your highest-selling product or service that commands a 25–40% price premium. The same labor hours spent on premium work generates significantly more gross profit — directly improving Labor ROI without any change to headcount, productivity, or labor cost. Premium offerings are the most margin-efficient labor productivity enhancement available.','month_1_3','high','high','revenue'),
  ('gpToLabor','Labor ROI','healthy',65,100,6,'Invest in automation to grow revenue without proportional labor growth','Identify the most labor-intensive production or service delivery processes and research automation options with payback periods below 24 months. Automation enables revenue growth at lower incremental labor cost — improving Labor ROI sustainably as scale increases. Commission a technology assessment on your top two labor-intensive processes within the next quarter.','month_3_6','high','high','operations'),
  ('gpToLabor','Labor ROI','healthy',65,100,7,'Build SETA training investment into your annual Labor ROI strategy','Maximise your SETA (Sector Education and Training Authority) levy grant claims to fund skills development that improves your labor productivity and output quality. South African employers paying skills development levies can claim back 20–50% of those levies through SETA training grants. Skills-funded training that improves productivity reduces the effective cost of labor improvement.','month_3_6','medium','medium','people'),
  ('gpToLabor','Labor ROI','healthy',65,100,8,'Stress-test Labor ROI against a revenue decline and labor cost increase','Model your Labor ROI if revenue declined 20% while labor costs increased 8% due to annual salary escalation. This combined scenario — realistic in a South African economic downturn — tests whether your healthy ratio is resilient. Pre-plan the gross profit and cost actions you would take to protect Labor ROI under this scenario.','month_3_6','low','medium','risk'),
  ('gpToLabor','Labor ROI','healthy',65,100,9,'Design your next hire to be immediately accretive to Labor ROI','Before making any new hire, model the gross profit that role will generate within six months and confirm it exceeds the total labor cost by your target Labor ROI multiple. Hiring for roles where the gross profit contribution is uncertain or delayed below your minimum target erodes Labor ROI. Make Labor ROI accretion a standing hiring criterion.','year_1','low','medium','people'),
  ('gpToLabor','Labor ROI','healthy',65,100,10,'Include Labor ROI in your three-year people strategy','Set a specific three-year Labor ROI target and build the talent, productivity, automation, and product mix strategies required to achieve it. Labor is your largest cost in most SME businesses — making its return a deliberate strategic priority, rather than an outcome you observe at year-end, separates high-performing businesses from those that struggle with people cost management.','year_1','medium','high','people'),
  ('customerConcentration','Customer Dependency','critical',0,40,1,'Quantify your revenue exposure to your top five customers today','Calculate the exact percentage of total revenue generated by your top five customers individually and combined. Identify which single customer, if lost, would cause an existential cash crisis. At a critical customer concentration, this analysis tells you how quickly you would hit break-even if your largest customer left — this is your primary risk number.','immediate','low','high','risk'),
  ('customerConcentration','Customer Dependency','critical',0,40,2,'Meet your top customer within 48 hours to assess relationship health','If one customer represents more than 30% of your revenue, request an urgent face-to-face meeting with your primary contact there within 48 hours. The purpose is to assess the health of the relationship, understand any threats to the contract, and reinforce your commitment. You need to know immediately whether this relationship is secure — and if not, you need maximum lead time to respond.','immediate','medium','high','risk'),
  ('customerConcentration','Customer Dependency','critical',0,40,3,'Diversify into at least three new customer targets immediately','Identify three specific new prospective customers in the same sector or in adjacent sectors who could realistically become meaningful revenue contributors within 90 days. Assign your best salesperson to these accounts exclusively. Customer concentration risk cannot be resolved without new customer acquisition — and new customer acquisition takes time. Start immediately.','immediate','medium','high','revenue'),
  ('customerConcentration','Customer Dependency','critical',0,40,4,'Embed your business deeper into your top customer''s operations','Identify two or three additional services, products, or functions you could provide to your largest customer that would increase your integration into their operations. The more embedded you are — the harder you are to remove — the lower the actual risk of sudden loss even at high concentration. Integration is the fastest available risk mitigation for existing concentration.','week_1_2','medium','high','revenue'),
  ('customerConcentration','Customer Dependency','critical',0,40,5,'Negotiate long-term contracts with your top three customers','Approach your three largest customers and propose formal long-term agreements — 2–3 year contracts with annual volume commitments, renewal options, and exit notice periods of at least 90 days. A long-term contract converts a critical concentration risk into a managed, time-bounded one. Offer preferential pricing or service levels in exchange for commitment.','week_1_2','medium','high','risk'),
  ('customerConcentration','Customer Dependency','critical',0,40,6,'Build a cash reserve equivalent to three months of your largest customer''s revenue','Calculate three months of revenue from your largest customer and set this as a minimum cash reserve target. If that customer is lost suddenly, this reserve buys three months of operational continuity while you pursue replacement revenue. Build this reserve from monthly OCF and maintain it as a standing financial policy.','month_1','medium','high','cash'),
  ('customerConcentration','Customer Dependency','critical',0,40,7,'Develop a new channel or market to access a different customer segment','Your current customer concentration reflects your current route to market. Identify one new channel — direct sales, digital, distribution partner, or geographic expansion — that accesses a different customer segment. Developing a new channel takes 3–12 months but is the structural fix for customer concentration that tactical sales alone cannot achieve.','month_1','high','high','structure'),
  ('customerConcentration','Customer Dependency','critical',0,40,8,'Build a 12-month new customer acquisition plan with monthly targets','Create a structured 12-month new customer acquisition plan with monthly revenue diversification targets. The plan should show what percentage of total revenue each new customer should represent by month 12 and the specific sales activities required to reach it. A written acquisition plan with monthly targets produces more consistent results than a general intention to diversify.','month_1','medium','high','revenue'),
  ('customerConcentration','Customer Dependency','critical',0,40,9,'Develop a contingency plan for the sudden loss of your largest customer','Write a specific contingency plan for the scenario where your largest customer terminates with 30 days notice. The plan should cover: which costs would be cut immediately, which customers would be prioritised for growth, which staff would be retained, and what emergency financing would be arranged. Having a written plan means you act within days rather than weeks if the worst happens.','month_1_3','medium','high','risk'),
  ('customerConcentration','Customer Dependency','critical',0,40,10,'Set a 3-year target of no single customer above 20% of revenue','Define a formal 3-year strategic goal: no single customer should represent more than 20% of total revenue. Build the new customer acquisition, channel development, and product diversification initiatives required to reach this target. Review progress annually against this milestone. Customer concentration above 20% is universally recognised as a material business risk by lenders, investors, and acquirers.','month_3_6','high','high','structure'),
  ('customerConcentration','Customer Dependency','at_risk',40,65,1,'Map your customer revenue concentration with specific percentages','Calculate the percentage of total revenue represented by each of your top ten customers individually. Identify which customers, if lost simultaneously or individually, would push the business below break-even. At at-risk concentration, typically one to three customers represent 30–50% of revenue — knowing the precise figures is the foundation of risk management.','immediate','low','medium','risk'),
  ('customerConcentration','Customer Dependency','at_risk',40,65,2,'Assess the health and security of your top three customer relationships','Meet with your key contacts at your top three customers in the next two weeks and conduct a relationship health check — satisfaction, renewal likelihood, competing supplier activity, and strategic fit. At-risk concentration means a single relationship deterioration could push you to critical. Knowing the current health of each relationship tells you how much time you have.','week_1_2','medium','medium','risk'),
  ('customerConcentration','Customer Dependency','at_risk',40,65,3,'Set a new customer acquisition target of two new accounts per month','Commit to acquiring at least two new customer accounts per month with meaningful revenue potential. Track new customer revenue as a percentage of total monthly revenue and set a 12-month target to reduce your top customer''s share by 10 percentage points through new customer growth rather than by reducing revenue from existing ones.','week_1_2','medium','medium','revenue'),
  ('customerConcentration','Customer Dependency','at_risk',40,65,4,'Negotiate 24-month contracts with your top three customers','Approach your three largest customers and propose 24-month supply or service agreements with committed volumes and exit notice periods. A 24-month contract converts an at-risk concentration into a managed time-bound exposure. Offer a modest incentive — 2–3% pricing benefit or enhanced service level — in exchange for the commitment.','month_1','medium','high','risk'),
  ('customerConcentration','Customer Dependency','at_risk',40,65,5,'Expand your offering to existing customers to grow revenue from more of them','Design cross-sell and upsell offerings for your existing customer base beyond your top three. Growing revenue from customers who currently represent 3–8% of total revenue is the fastest way to reduce concentration without adding new customer acquisition cost. Identify two cross-sell opportunities for each of your next 10 largest customers.','month_1','medium','medium','revenue'),
  ('customerConcentration','Customer Dependency','at_risk',40,65,6,'Build a cash reserve to absorb potential loss of your second largest customer','Build a cash reserve equal to three months of revenue from your second-largest customer. This provides operational buffer if your at-risk concentration materialises as an actual customer loss. The reserve should be held in a notice deposit separate from your operating accounts — accessible within 5–7 days but not commingled with daily operating cash.','month_1_3','medium','medium','cash'),
  ('customerConcentration','Customer Dependency','at_risk',40,65,7,'Develop a new distribution channel to access untapped customer segments','Identify one new route to market — a digital channel, a referral partnership, a distributor, or a geographic expansion — that accesses a customer segment you currently do not serve. New channels take 6–12 months to generate meaningful revenue but are essential for structural concentration reduction. Begin development now so the channel is producing revenue within 12 months.','month_1_3','high','high','structure'),
  ('customerConcentration','Customer Dependency','at_risk',40,65,8,'Track customer concentration monthly as a KPI','Add customer concentration — expressed as top customer percentage and top-5 percentage of total revenue — to your monthly management KPI dashboard. Monthly visibility creates accountability for diversification progress and flags any period where concentration worsens rather than improves. Concentration tracked monthly is managed actively; concentration reviewed annually is discovered too late.','month_1_3','low','medium','risk'),
  ('customerConcentration','Customer Dependency','at_risk',40,65,9,'Invest your largest customer''s margins into customer acquisition','Deliberately allocate a percentage of the above-average margins earned from your largest customer into a customer diversification fund — marketing, sales capacity, or channel development. The margin advantage of serving a large customer should fund the diversification that reduces the risk of depending on them.','month_3_6','medium','medium','revenue'),
  ('customerConcentration','Customer Dependency','at_risk',40,65,10,'Set a 2-year target to reduce top customer concentration below 25%','Define a formal 24-month goal to reduce your largest single customer from its current share to below 25% of total revenue through new customer acquisition and existing customer development. Break this into 6-month milestones and include the specific sales, marketing, and channel initiatives required to achieve each. Customer concentration above 25% is a material risk that affects your ability to attract investment, financing, and acquirers.','month_3_6','high','high','structure'),
  ('customerConcentration','Customer Dependency','healthy',65,100,1,'Document your customer revenue distribution and set concentration ceilings','Record the revenue percentage of each of your top ten customers and establish formal concentration ceilings — for example, no single customer above 15% and top five combined below 40%. These ceilings, enforced as policy, prevent a healthy concentration ratio from drifting upward through the natural tendency of growing with your best customers faster than diversifying.','month_1','low','medium','risk'),
  ('customerConcentration','Customer Dependency','healthy',65,100,2,'Monitor customer concentration monthly and alert if any customer exceeds 20%','Set up a monthly alert if any single customer''s revenue contribution exceeds 20% of total revenue. Growth with existing customers — a positive outcome — can silently worsen concentration. Monthly monitoring catches this trend before it becomes structural and allows proactive diversification before concentration becomes a problem.','month_1','low','medium','risk'),
  ('customerConcentration','Customer Dependency','healthy',65,100,3,'Use healthy concentration metrics in investment and funding conversations','A well-diversified customer base is a significant positive signal for lenders, investors, and acquirers. Include customer concentration metrics — number of active customers, largest customer as a percentage, revenue from top five — in any funding application or investor conversation. Healthy concentration is a competitive differentiator in capital markets.','month_1','low','medium','structure'),
  ('customerConcentration','Customer Dependency','healthy',65,100,4,'Maintain diversification discipline during growth by onboarding new segments','As you grow, actively onboard customers from new segments, geographies, or industries alongside expanding with existing ones. Healthy concentration ratios erode when growth happens predominantly with existing concentrated customers. Commit 20–30% of your sales capacity to new segment development even while existing account growth is available and easier.','month_1_3','medium','medium','revenue'),
  ('customerConcentration','Customer Dependency','healthy',65,100,5,'Conduct annual relationship health reviews with your top ten customers','Schedule annual structured relationship reviews with each of your top ten customers — assessing satisfaction, renewal likelihood, competitive threats, and growth opportunities. Even a healthy concentration ratio carries residual risk from the revenue in your top tier. Annual relationship reviews give you early warning of any deterioration in key accounts.','month_1_3','medium','medium','risk'),
  ('customerConcentration','Customer Dependency','healthy',65,100,6,'Build a customer lifetime value model to prioritise your highest-value relationships','Calculate the customer lifetime value for your top 20 customers — combining revenue, margin, retention probability, and growth potential. Concentrate relationship investment — senior account management, preferential service, innovation collaboration — on customers with the highest lifetime value, not just the highest current revenue. LTV-based prioritisation sustains a healthy revenue base more effectively than revenue-only prioritisation.','month_3_6','medium','medium','revenue'),
  ('customerConcentration','Customer Dependency','healthy',65,100,7,'Explore recurring revenue models to make existing diversification more resilient','Convert as much customer revenue as possible to subscription, retainer, or maintenance contract models. Recurring revenue from a diversified customer base is the most resilient revenue structure available — it combines the financial quality of predictable income with the risk management of diversification. Target 30% of revenue from recurring sources within 12 months.','month_3_6','high','high','revenue'),
  ('customerConcentration','Customer Dependency','healthy',65,100,8,'Stress-test revenue base against simultaneous loss of top two customers','Model your revenue, EBIT, and cash position if your two largest customers both terminated with 30 days notice simultaneously. Identify whether the business would survive, for how long, and what specific actions you would take. Even a healthy concentration ratio warrants this stress test — concentrated revenue carries residual risk that healthy diversification only partially mitigates.','month_3_6','low','medium','risk'),
  ('customerConcentration','Customer Dependency','healthy',65,100,9,'Build your brand to attract inbound customers and reduce concentration risk','Invest in brand-building activities — thought leadership, digital presence, industry visibility — that generate inbound customer interest independent of your existing relationships. Inbound customers are better quality — they have sought you out — and they diversify your pipeline beyond the accounts your sales team is actively managing. A strong brand is a structural diversification mechanism.','year_1','medium','medium','revenue'),
  ('customerConcentration','Customer Dependency','healthy',65,100,10,'Include customer concentration in your three-year strategic plan','Set a three-year customer concentration target — for example, no single customer above 12% and top five combined below 35% — and build the market development, channel, and product strategies required to achieve it. Customer concentration management at three-year horizon is a CFO and CEO-level responsibility that creates durable revenue resilience and significantly improves business valuation.','year_1','medium','high','structure'),
  ('revenueGrowth','Revenue Momentum','critical',0,40,1,'Determine if revenue decline is customer loss or volume reduction','Separate your revenue decline into two components — lost customers and reduced spend from existing customers. These have different causes and different solutions. Customer loss requires acquisition; volume decline from existing customers requires retention and upselling. You cannot fix a revenue crisis without knowing which problem you actually have.','immediate','low','high','revenue'),
  ('revenueGrowth','Revenue Momentum','critical',0,40,2,'Call every lapsed customer from the last 12 months this week','Generate a list of every customer who purchased in the prior year but not in the last 90 days and make personal calls to every one of them this week. Reactivating a lapsed customer is 5x faster and cheaper than acquiring a new one. Even recovering 20% of lapsed accounts meaningfully improves your revenue momentum trajectory.','immediate','medium','high','revenue'),
  ('revenueGrowth','Revenue Momentum','critical',0,40,3,'Accelerate every deal in your pipeline to closure within 30 days','Review your entire sales pipeline and identify every deal that is 50% or more through your sales process. Offer a time-limited incentive — a small discount, enhanced terms, or expedited delivery — to close each one within 30 days. Pipeline velocity is the fastest available source of incremental revenue from existing relationships.','immediate','medium','high','revenue'),
  ('revenueGrowth','Revenue Momentum','critical',0,40,4,'Introduce a referral programme for your top ten existing customers','Contact your ten most satisfied customers and ask each for one introduction to a potential new customer. Offer a meaningful referral incentive — a credit, gift, or service upgrade — for each introduction that converts. A structured referral programme from your top customers is the lowest-cost, highest-conversion new customer acquisition channel available to a business with a critical revenue position.','week_1_2','low','high','revenue'),
  ('revenueGrowth','Revenue Momentum','critical',0,40,5,'Increase prices to restore revenue value even if volume is declining','If revenue is declining due to volume loss but your customers are relatively price-inelastic, a 10–15% price increase partially offsets the volume decline in revenue terms. Raising prices during a critical revenue decline is counterintuitive but often correct — it also communicates confidence and quality positioning to remaining customers.','week_1_2','low','medium','revenue'),
  ('revenueGrowth','Revenue Momentum','critical',0,40,6,'Launch cross-sell campaign to your entire active customer base','Design a specific cross-sell offer for every active customer — a complementary product, a bundled package, or a service upgrade — and contact your entire customer base with this offer within 30 days. Cross-selling to existing customers costs 5–7x less than new customer acquisition and generates revenue faster. Even a 10% take-up rate can materially improve your revenue growth rate.','month_1','medium','high','revenue'),
  ('revenueGrowth','Revenue Momentum','critical',0,40,7,'Identify and resolve the specific cause of revenue decline','If revenue is declining, there is a specific cause — competitive pressure, product obsolescence, pricing issues, service quality problems, or market contraction. Conduct five to ten customer interviews to identify the primary reason. Solving the right problem is the only path to restoring momentum. Applying the wrong solution wastes limited resources and time.','month_1','medium','high','revenue'),
  ('revenueGrowth','Revenue Momentum','critical',0,40,8,'Reduce cost base in parallel with revenue recovery to protect survival','Revenue recovery takes 3–12 months. In parallel, cut costs to ensure the business can survive at its current reduced revenue level until growth is restored. Target a cost base reduction that achieves break-even at 20–30% below your current revenue. Survival through cost discipline buys the time for revenue recovery to work.','month_1','high','high','cost'),
  ('revenueGrowth','Revenue Momentum','critical',0,40,9,'Develop a new product or market adjacent to your current offering','If your current market is contracting, identify the closest adjacent market or product opportunity where your existing capabilities translate. A new adjacent offering can restore growth within 90 days if it leverages existing skills, relationships, and infrastructure. Pivot is not failure — it is adaptation to market reality.','month_1_3','high','high','structure'),
  ('revenueGrowth','Revenue Momentum','critical',0,40,10,'Build a 12-month revenue recovery plan with monthly milestones','Create a structured 12-month revenue recovery plan with specific monthly targets, named customers to be pursued, campaigns to be run, and products to be launched. Set a milestone of returning to your prior year revenue level within 12 months. A written recovery plan with monthly accountability produces measurably better outcomes than an unstructured recovery attempt.','month_1_3','medium','high','revenue'),
  ('revenueGrowth','Revenue Momentum','at_risk',40,65,1,'Calculate your actual revenue growth rate and compare to inflation','Calculate your revenue growth rate over the last 12 months and compare it to South African CPI (approximately 5–6% in recent years). If your nominal revenue growth is below inflation, your real revenue is actually declining. A business with 3% nominal revenue growth in a 6% inflation environment is effectively contracting in real terms.','immediate','low','medium','revenue'),
  ('revenueGrowth','Revenue Momentum','at_risk',40,65,2,'Implement annual price increases equal to or above inflation','If you have not implemented a price increase in the last 12 months, do so immediately. South African input cost inflation typically runs at 5–10% per year — if your prices have not kept pace, your real revenue and margin are shrinking. Implement a minimum CPI-linked price increase annually and communicate it as a standard practice to all customers.','week_1_2','low','medium','revenue'),
  ('revenueGrowth','Revenue Momentum','at_risk',40,65,3,'Launch a structured cross-sell programme for existing customers','Design two or three specific cross-sell offers for your existing customer base and run a structured outreach campaign over 60 days. Existing customers who already trust you have the highest conversion rate for additional revenue. A 10% increase in average spend per customer at your current customer base produces meaningful revenue growth with zero new customer acquisition cost.','week_1_2','medium','medium','revenue'),
  ('revenueGrowth','Revenue Momentum','at_risk',40,65,4,'Set a monthly new customer acquisition target and track it','Define a specific number of new customer accounts to be acquired each month and track actual versus target. At-risk revenue growth is often caused by insufficient new customer acquisition — the business is retaining existing customers but not growing its base. A monthly target with a tracking mechanism is the minimum management discipline for improving growth momentum.','month_1','low','medium','revenue'),
  ('revenueGrowth','Revenue Momentum','at_risk',40,65,5,'Identify and reactivate your lapsed customer list','Generate a list of customers who purchased 12–24 months ago but have not returned and call each one personally within 30 days. Lapsed customer reactivation is one of the highest-ROI revenue initiatives available because you are re-engaging people who already know and have trusted your business. Even a 15% reactivation rate on a meaningful lapsed list generates significant incremental revenue.','month_1','medium','medium','revenue'),
  ('revenueGrowth','Revenue Momentum','at_risk',40,65,6,'Develop a referral programme to generate warm new leads','Design a formal referral programme for your most satisfied customers — offering a meaningful incentive for each referral that converts to a paying customer. Referral-generated leads convert at 3–4x the rate of cold leads and have higher lifetime values. A structured programme with a clear incentive generates referrals consistently rather than waiting for them to happen organically.','month_1','low','medium','revenue'),
  ('revenueGrowth','Revenue Momentum','at_risk',40,65,7,'Analyse your win-loss data to identify why you are losing deals','Review the last 20 sales opportunities you lost and identify the most common reasons — price, quality, timing, competitor, or product gap. If the same reason appears in 40%+ of lost deals, you have a specific and fixable problem. Closing the most common loss reason typically improves win rates by 15–25% within 90 days.','month_1_3','medium','medium','revenue'),
  ('revenueGrowth','Revenue Momentum','at_risk',40,65,8,'Launch a new product or service to access untapped demand','Identify one new product or service that addresses a specific unmet need in your existing customer base or adjacent market. New offerings to existing customers have lower development risk and faster adoption than new offerings to new markets. Aim to have a minimum viable new offering in market within 90 days.','month_1_3','high','high','revenue'),
  ('revenueGrowth','Revenue Momentum','at_risk',40,65,9,'Set a 12-month revenue growth target of 15% above current run rate','Define a specific 12-month revenue target representing at least 15% above your current annual run rate. Break it into the contribution from existing customer growth, new customer acquisition, and new products. A specific target with a disaggregated plan produces significantly better outcomes than a general ambition to grow.','month_1_3','medium','high','revenue'),
  ('revenueGrowth','Revenue Momentum','at_risk',40,65,10,'Invest in digital marketing to generate scalable inbound revenue growth','Develop or improve your digital presence — website, SEO, LinkedIn, Google Ads — to generate inbound leads at a cost per acquisition below your current outbound sales cost. Digital marketing compounds over time and can produce a sustained improvement in revenue growth rate that scales without proportional sales headcount growth.','month_3_6','medium','high','revenue'),
  ('revenueGrowth','Revenue Momentum','healthy',65,100,1,'Benchmark revenue growth against your market and top competitors','Compare your revenue growth rate to your sector''s average growth rate and to your most direct competitors. Growing at 15% in a market growing 25% means you are losing market share despite good absolute growth. Benchmarking determines whether your healthy growth rate is competitive or merely riding a market tailwind.','month_1','low','medium','revenue'),
  ('revenueGrowth','Revenue Momentum','healthy',65,100,2,'Identify the primary driver of current growth to protect and amplify it','Determine where your growth is coming from — new customers, existing customer expansion, price increases, or new products. The driver of your growth determines your risk profile and your best amplification strategy. Growth from existing customer expansion is the most sustainable; growth from new channels has the most future potential.','month_1','low','medium','revenue'),
  ('revenueGrowth','Revenue Momentum','healthy',65,100,3,'Convert one-off revenue to recurring subscriptions or retainers','Identify your highest-volume one-off or project revenue and design a recurring version — a subscription, maintenance contract, or retainer. Converting even 20% of one-off revenue to recurring creates a compounding revenue base that makes future growth more predictable and less dependent on continuous new customer acquisition.','month_1_3','high','high','revenue'),
  ('revenueGrowth','Revenue Momentum','healthy',65,100,4,'Invest in sales capacity to scale revenue growth above current trajectory','If your healthy revenue growth is limited by sales capacity rather than market demand, invest in additional sales capacity — headcount, systems, or process improvement. Model the revenue return on each additional sales rand invested and target roles where the revenue-to-cost ratio exceeds your current business average within 12 months.','month_1_3','medium','high','people'),
  ('revenueGrowth','Revenue Momentum','healthy',65,100,5,'Develop a premium tier to grow revenue from existing customers','Design a premium version of your core offering at a 25–40% price premium for customers who want more. Premium tiers grow revenue from existing customers without requiring new customer acquisition — your fastest and lowest-cost revenue growth lever. Even a 10% take-up rate from your existing base at a 30% premium is a meaningful revenue growth contribution.','month_1_3','high','high','revenue'),
  ('revenueGrowth','Revenue Momentum','healthy',65,100,6,'Explore new geographic markets to access additional growth runway','Assess whether your current product or service can be extended into adjacent geographic markets — neighbouring cities, provinces, or export markets. Geographic expansion is often the most capital-efficient growth lever once your core market is well-penetrated, particularly for digital or professional services businesses where delivery can be managed remotely.','month_3_6','high','high','structure'),
  ('revenueGrowth','Revenue Momentum','healthy',65,100,7,'Protect growth margins as revenue scales','Monitor gross margin and operating margin monthly as revenue grows. Growth that erodes margin — because costs scale faster than revenue — is a warning sign. Ensure that your growth model is designed so that unit economics improve or at least hold stable at higher revenue levels. Revenue growth with declining margins creates future profitability problems regardless of how healthy the growth rate appears.','month_3_6','medium','high','operations'),
  ('revenueGrowth','Revenue Momentum','healthy',65,100,8,'Build a 3-year revenue growth model with compounding assumptions','Create a three-year revenue model showing growth from existing customers, new customer acquisition, new products, and new geographies — with assumptions for each. A compounding model that assumes each year''s new customers become the following year''s growth base produces more realistic projections than year-on-year linear models.','month_3_6','medium','high','structure'),
  ('revenueGrowth','Revenue Momentum','healthy',65,100,9,'Stress-test growth assumptions against a market disruption scenario','Model your revenue growth trajectory if your largest market contracted 30% due to economic downturn, regulatory change, or competitive disruption. Identify which growth initiatives are resilient to this scenario and which are not. Pre-planning a response to a significant growth interruption preserves momentum better than improvising under pressure.','year_1','low','medium','risk'),
  ('revenueGrowth','Revenue Momentum','healthy',65,100,10,'Include revenue growth strategy as the lead item in your annual strategic plan','Make revenue growth strategy — including the specific customer, product, channel, and geographic initiatives driving it — the lead item in your annual strategic plan. Include growth targets, resource requirements, and milestones for each growth initiative. Businesses that plan growth explicitly and resourcefully outperform those that expect growth to happen as a consequence of operational excellence alone.','year_1','medium','high','structure'),
  ('salesPerEmployee','Revenue per Employee','critical',0,40,1,'Calculate revenue per employee and compare to your sector benchmark','Divide your annual revenue by total full-time equivalent headcount and compare to your sector benchmark. South African professional services businesses typically target R500 000–R1 500 000 per employee; manufacturing R300 000–R800 000; retail R400 000–R1 000 000. Knowing how far below benchmark you are determines the scale of intervention required.','immediate','low','high','people'),
  ('salesPerEmployee','Revenue per Employee','critical',0,40,2,'Identify whether the problem is too much headcount or too little revenue','Calculate what revenue per employee would be if (a) revenue returned to its prior year level with current headcount, and (b) headcount were reduced 20% at current revenue. This decomposition tells you whether your critical ratio is primarily a revenue crisis requiring growth action or a headcount crisis requiring reduction — the interventions are fundamentally different.','immediate','low','high','people'),
  ('salesPerEmployee','Revenue per Employee','critical',0,40,3,'Map every role to its direct revenue or productivity contribution','Create a role-level map showing each employee''s total employment cost and their direct or indirect contribution to revenue generation. Roles without a clear revenue or productivity linkage are the first candidates for restructuring. At a critical revenue per employee, every role must justify its cost through a measurable contribution.','week_1_2','medium','high','people'),
  ('salesPerEmployee','Revenue per Employee','critical',0,40,4,'Implement emergency revenue push from all customer-facing staff','Redirect every customer-facing employee''s primary focus to revenue generation for 90 days — maximising cross-sells, closing pipeline deals, reactivating lapsed customers, and requesting referrals. In a critical revenue per employee situation, every staff member with customer contact must become a revenue contributor. Set daily or weekly revenue targets for each.','week_1_2','medium','high','revenue'),
  ('salesPerEmployee','Revenue per Employee','critical',0,40,5,'Freeze all hiring with immediate effect','Place an absolute hiring freeze with immediate effect. No new permanent or temporary staff until revenue per employee returns to at least 80% of your sector benchmark. Every new hire at a critical revenue per employee ratio deepens the problem before the new employee can generate revenue. Existing headcount must first reach productivity targets.','immediate','low','high','people'),
  ('salesPerEmployee','Revenue per Employee','critical',0,40,6,'Review underperforming roles for restructuring before retrenchment','Identify roles where productivity is below the level required to justify the employment cost at your current revenue level. Before initiating retrenchments — which require a formal Section 189 process in South Africa — exhaust alternatives: performance improvement plans, role reassignment, or reduction in hours. Legal compliance in retrenchment is non-negotiable. Always take HR legal advice first.','month_1','high','high','people'),
  ('salesPerEmployee','Revenue per Employee','critical',0,40,8,'Implement productivity tracking for all revenue-generating roles','Set up weekly productivity tracking for every revenue-generating employee — calls made, proposals submitted, revenue closed, or deliverables completed. At a critical revenue per employee, you cannot afford to carry underperforming revenue generators. Visibility of individual productivity creates accountability and identifies who needs support versus who needs to be replaced.','month_1','medium','medium','people'),
  ('salesPerEmployee','Revenue per Employee','critical',0,40,9,'Train your lowest-performing revenue generators within 30 days','Identify your three to five lowest-performing revenue-generating staff and put each through an intensive 30-day skills improvement programme — sales technique, product knowledge, or delivery quality. At a critical revenue per employee, each person performing below their potential is costing you more than their salary. Rapid skills improvement is often faster and cheaper than replacement.','month_1_3','medium','medium','people'),
  ('salesPerEmployee','Revenue per Employee','critical',0,40,10,'Set a 12-month revenue per employee recovery target with monthly milestones','Define a specific 12-month revenue per employee target — at or above your sector benchmark — and build a plan covering revenue growth, headcount discipline, and productivity improvement to reach it. Set monthly milestones and review with your management team. A written recovery plan with monthly accountability produces faster and more durable improvement than reactive management.','month_1_3','medium','high','people'),
  ('salesPerEmployee','Revenue per Employee','at_risk',40,65,1,'Benchmark revenue per employee against sector and set improvement target','Calculate your revenue per employee and compare to your sector benchmark. Set a specific 12-month target to close the gap to the sector median — if the median is R800 000 and you are at R550 000, the improvement required is specific and calculable. A benchmark-driven target is more motivating and actionable than a general intention to improve productivity.','immediate','low','medium','people'),
  ('salesPerEmployee','Revenue per Employee','at_risk',40,65,2,'Identify your highest and lowest revenue-per-employee performers','Rank every employee by the revenue they generate or directly enable. Identify the top quartile and the bottom quartile. The gap between your best and worst performers is your productivity improvement opportunity. Understanding the specific behaviours, tools, or skills of your top performers enables you to replicate them across the wider team.','week_1_2','medium','medium','people'),
  ('salesPerEmployee','Revenue per Employee','at_risk',40,65,3,'Set individual revenue targets for all revenue-generating staff','Define explicit monthly or quarterly revenue targets for every revenue-generating employee. Staff without individual revenue targets are less likely to maximise their personal contribution to the ratio. Targets should be ambitious but achievable — based on the gap between current and benchmark revenue per employee for each role type.','week_1_2','low','medium','people'),
  ('salesPerEmployee','Revenue per Employee','at_risk',40,65,4,'Implement process improvements to reduce time-waste and increase billable output','Audit how your revenue-generating staff spend their time and identify the top three non-revenue activities consuming their hours — administrative tasks, internal meetings, rework, or inefficient processes. Eliminating these wastes directly increases the proportion of their time generating revenue. A 10% improvement in time allocation to revenue activity produces a 10% improvement in revenue per employee.','month_1','medium','medium','operations'),
  ('salesPerEmployee','Revenue per Employee','at_risk',40,65,5,'Invest in sales enablement tools to increase per-person output','Identify technology that could increase each revenue generator''s output — a CRM system, proposal automation, quoting tools, or customer communication platforms. Technology-enabled productivity improvements scale across your entire team at low marginal cost per person. Even a 15% improvement in each person''s revenue output from better tools significantly improves the ratio.','month_1','medium','medium','operations'),
  ('salesPerEmployee','Revenue per Employee','at_risk',40,65,6,'Raise prices to improve revenue per employee without headcount changes','A price increase improves revenue per employee directly — the same number of people generate more revenue from the same output. On an at-risk revenue per employee ratio, a 7–10% price increase with stable headcount and minimal volume loss produces an immediate improvement. Pricing is the most capital-efficient lever for revenue per employee improvement.','month_1','low','medium','revenue'),
  ('salesPerEmployee','Revenue per Employee','at_risk',40,65,7,'Outsource non-revenue administrative roles to improve the ratio','Review all administrative and support roles and identify candidates for outsourcing. Reducing in-house headcount in non-revenue functions through outsourcing improves the revenue per employee ratio without reducing revenue-generating capacity. Focus outsourcing on the most routine and easily standardised administrative functions first.','month_1_3','medium','medium','operations'),
  ('salesPerEmployee','Revenue per Employee','at_risk',40,65,8,'Develop a training programme for your bottom-quartile performers','Invest in a targeted skills development programme for your lowest-performing revenue generators. Focus training on the specific skills that your top performers demonstrate — product knowledge, customer engagement, closing skills, or technical proficiency. Skills-driven productivity improvement is more sustainable and less disruptive than headcount reduction as a productivity lever.','month_1_3','medium','medium','people'),
  ('salesPerEmployee','Revenue per Employee','at_risk',40,65,9,'Align future hiring to revenue-per-employee threshold requirements','Before approving any new hire, model the expected revenue contribution of that role within six months and confirm it meets your target revenue per employee. Only hire where the projected revenue per employee impact is neutral or positive. This discipline prevents at-risk ratios from worsening through headcount growth that lags revenue.','month_1_3','low','medium','people'),
  ('salesPerEmployee','Revenue per Employee','at_risk',40,65,10,'Set a 12-month revenue per employee improvement target with quarterly reviews','Define a 12-month revenue per employee target representing at least sector median performance and build a plan across revenue growth, pricing, productivity, and headcount discipline to achieve it. Review quarterly with your management team and adjust initiatives if you are tracking below plan. A quarterly review cadence is the right frequency for revenue per employee management.','month_3_6','medium','high','people'),
  ('salesPerEmployee','Revenue per Employee','healthy',65,100,1,'Benchmark revenue per employee against your sector top quartile','Compare your revenue per employee to the top quartile for businesses at your scale in your sector. If you are above the median but below the top quartile, a specific improvement opportunity exists. If you are at the top quartile, your focus shifts to protecting the advantage through hiring discipline and productivity maintenance.','month_1','low','low','people'),
  ('salesPerEmployee','Revenue per Employee','healthy',65,100,2,'Protect revenue per employee by setting a minimum threshold for new hires','Define a minimum revenue contribution expected from each new hire within 6 months of joining — expressed as a revenue per employee target for that role type. Apply this threshold as a hiring criterion. Businesses with healthy revenue per employee ratios often erode them gradually through hiring that adds cost faster than revenue.','month_1','low','medium','people'),
  ('salesPerEmployee','Revenue per Employee','healthy',65,100,3,'Invest in technology to grow revenue without proportional headcount','Identify the highest-potential technology investments — CRM, automation, AI tools, or delivery platforms — that could increase revenue capacity without requiring proportional headcount growth. Technology-driven revenue growth compounds your revenue per employee advantage over time. Model the expected revenue per employee impact before each technology investment.','month_1_3','medium','high','operations'),
  ('salesPerEmployee','Revenue per Employee','healthy',65,100,4,'Use your productivity advantage to compete on service quality not price','A healthy revenue per employee means each person in your business generates more revenue than your competitors'' equivalents. This productivity advantage allows you to invest more in service quality — faster response, higher expertise, better output — without sacrificing margin. Use the advantage to compete on value, not price, to protect and improve your ratio.','month_1_3','medium','medium','revenue'),
  ('salesPerEmployee','Revenue per Employee','healthy',65,100,5,'Develop a structured onboarding programme to reach productivity faster','Design a formal 90-day onboarding programme that accelerates new staff to full productivity faster than your current informal process. Reducing the time from hire to full productivity improves the revenue per employee ratio for new staff — and reduces the drag on the overall ratio that occurs during the ramp-up period. A structured onboarding programme typically halves time-to-productivity.','month_1_3','medium','medium','people'),
  ('salesPerEmployee','Revenue per Employee','healthy',65,100,6,'Create a productivity recognition programme to sustain high performance','Design a formal recognition and rewards programme for consistently high revenue per employee performance. Recognising and rewarding your highest-productivity staff sustains their performance, signals to the wider team what is valued, and reduces attrition risk among your most economically important people.','month_3_6','medium','medium','people'),
  ('salesPerEmployee','Revenue per Employee','healthy',65,100,7,'Stress-test revenue per employee against a revenue decline scenario','Model your revenue per employee if revenue declined 20% with headcount unchanged. Identify the threshold at which you would need to reduce headcount to protect the ratio and pre-plan which roles would be affected first. Pre-planned restructuring responses to revenue declines are less disruptive and legally better-managed than improvised ones.','month_3_6','low','medium','risk'),
  ('salesPerEmployee','Revenue per Employee','healthy',65,100,8,'Explore premium product development to increase revenue from existing staff','Develop a premium offering that your existing staff can deliver at a higher price point without significantly more time investment. Premium products sold by the same number of staff directly improve revenue per employee. The development investment pays back quickly if even 10–15% of customers adopt the premium tier.','month_3_6','high','high','revenue'),
  ('salesPerEmployee','Revenue per Employee','healthy',65,100,9,'Include revenue per employee in your annual people strategy review','Make revenue per employee a standing item in your annual HR and people strategy review — assessed alongside staff satisfaction, retention rates, and compensation benchmarks. Setting a target for the coming year and identifying the productivity, technology, and training initiatives to achieve it keeps revenue per employee a managed metric rather than an observed outcome.','year_1','low','medium','people'),
  ('salesPerEmployee','Revenue per Employee','healthy',65,100,10,'Set a three-year revenue per employee target in your strategic plan','Define a specific three-year revenue per employee target and build the technology, product, pricing, and people strategies required to achieve it. Revenue per employee is the most direct measure of scalability — a business that grows revenue faster than headcount compounds its profitability and competitive advantage. Making it a strategic target ensures growth is designed for efficiency, not just for scale.','year_1','medium','high','people'),
  ('assetReinvestmentRatio','Asset Reinvestment','critical',0,40,1,'Determine if critical ratio reflects over-investment or under-investment','An asset reinvestment ratio significantly above 1.5x indicates over-investment — spending on assets far faster than they depreciate, often financed by debt. A ratio far below 0.8x indicates under-investment — assets are not being replaced and are ageing. Each scenario requires a completely different response. Calculate your ratio and confirm which problem you face before acting.','immediate','low','high','structure'),
  ('assetReinvestmentRatio','Asset Reinvestment','critical',0,40,2,'Halt all discretionary capital expenditure if over-investing','If your critical ratio is driven by excessive Capex relative to depreciation, place an immediate freeze on all discretionary capital investment. Review every planned or contracted Capex item and cancel or defer everything not essential to maintaining current revenue. Every additional asset purchased at an over-investment position deepens the problem.','immediate','low','high','cost'),
  ('assetReinvestmentRatio','Asset Reinvestment','critical',0,40,3,'Prioritise critical asset replacements if under-investing','If your critical ratio reflects severe under-investment, identify which assets are approaching failure or obsolescence — those most likely to cause an operational disruption within 12 months — and prioritise their replacement above all other Capex. Operating with a severely depleted asset base is a hidden operational and revenue risk that worsens over time.','week_1_2','medium','high','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','critical',0,40,4,'Switch from asset purchase to operating lease for essential capital needs','For any essential capital requirement, source the asset via operating lease rather than purchase. Leasing reduces Capex and therefore the numerator of the reinvestment ratio, while maintaining operational capacity. An operating lease also preserves cash and avoids the debt required to fund a purchased asset.','week_1_2','medium','high','structure'),
  ('assetReinvestmentRatio','Asset Reinvestment','critical',0,40,5,'Conduct a full asset condition audit immediately','Physically inspect and document the condition of every significant fixed asset — machinery, vehicles, equipment, IT infrastructure. Rate each asset as serviceable, needing maintenance, or requiring replacement within 12 months. This audit gives you the operational ground truth underlying the accounting ratio and identifies which assets pose the most immediate risk.','month_1','medium','high','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','critical',0,40,6,'Develop a three-year asset replacement schedule','Based on your asset condition audit, build a three-year asset replacement schedule identifying which assets need replacement in each year, their estimated cost, and the funding source — retained earnings, asset finance, or lease. A scheduled replacement programme prevents the critical under-investment ratio from recurring and enables advance financial planning.','month_1','medium','high','structure'),
  ('assetReinvestmentRatio','Asset Reinvestment','critical',0,40,7,'Implement preventive maintenance to extend asset life and reduce replacement urgency','For assets that are functional but at risk of failure, implement an intensive preventive maintenance programme. Extending the useful life of existing assets by even 18–24 months through better maintenance provides time to improve cash flow and plan replacement funding. Preventive maintenance is typically 3–5x cheaper than emergency replacement or repair.','month_1','medium','medium','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','critical',0,40,8,'Benchmark your reinvestment ratio against sector capital intensity norms','Research the typical asset reinvestment ratios for your sector. Capital-intensive industries like manufacturing require reinvestment ratios closer to 1.0x–1.5x to maintain asset bases; service businesses can sustain lower ratios. A critical ratio in the context of your sector''s norms tells you how far you are from sustainable and what the recovery target should be.','month_1_3','low','medium','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','critical',0,40,9,'Explore asset finance options to fund essential replacements without cash pressure','For assets that must be replaced but cannot be funded from current cash flow, investigate hire purchase or finance lease options from asset finance providers. Asset finance allows you to replace essential assets at manageable monthly payments without large upfront cash commitments. Compare the monthly payment to the cost of operational disruption from an asset failure.','month_1_3','medium','medium','structure'),
  ('assetReinvestmentRatio','Asset Reinvestment','critical',0,40,10,'Build an ongoing Capex-to-depreciation monitoring discipline','Add asset reinvestment ratio to your annual financial review — tracking Capex as a multiple of depreciation over rolling three-year periods. A single year of deviation from the healthy range (0.8x–1.5x) is manageable; sustained deviation leads to either critical over-leveraging or asset base deterioration. Annual monitoring prevents the ratio from reaching critical without warning.','month_3_6','low','medium','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','at_risk',40,65,1,'Identify whether your ratio is above or below the healthy range','Determine whether your at-risk ratio is above 1.5x (over-investing) or below 0.8x (under-investing). At-risk over-investment means Capex is meaningfully outpacing asset replacement needs — potentially adding unnecessary assets or over-funding expansion. At-risk under-investment means assets are aging faster than they are being replaced. The intervention is fundamentally different for each.','immediate','low','medium','structure'),
  ('assetReinvestmentRatio','Asset Reinvestment','at_risk',40,65,2,'Conduct an asset condition review to assess replacement urgency','Physically review the condition of every significant fixed asset and classify each as in good condition, requiring maintenance within 12 months, or requiring replacement within 24 months. This review grounds the ratio in operational reality and identifies the specific assets that need attention versus those that are performing adequately.','week_1_2','medium','medium','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','at_risk',40,65,3,'Build a three-year asset replacement budget aligned to depreciation','Create a three-year Capex budget that targets annual Capex equal to 100–120% of annual depreciation — the maintenance reinvestment rate for most SME asset bases. For each year, identify the specific assets due for replacement, their cost, and the funding source. A replacement budget prevents both under-investment drift and over-investment spikes.','month_1','medium','medium','structure'),
  ('assetReinvestmentRatio','Asset Reinvestment','at_risk',40,65,4,'Adopt lease-first policy for expansion Capex to control the ratio','If your at-risk ratio is above 1.5x due to expansion Capex, adopt a lease-first policy for all expansion assets. Operating leases reduce the Capex numerator without reducing operational capacity. Apply the lease-first policy to any new asset that represents growth Capex — limit purchase decisions to replacement assets where total ownership cost clearly favours buying.','month_1','low','medium','structure'),
  ('assetReinvestmentRatio','Asset Reinvestment','at_risk',40,65,5,'Implement a preventive maintenance programme to extend asset life','Establish scheduled preventive maintenance for all critical production or delivery assets. Good maintenance extends asset useful life by 20–40% on average, reducing the annual replacement Capex required to sustain your asset base. A maintenance programme also reduces unplanned downtime — an operational benefit that compounds the financial one.','month_1','medium','medium','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','at_risk',40,65,6,'Add asset reinvestment ratio to annual Capex planning review','Include asset reinvestment ratio as an explicit output of your annual Capex planning process. Set a target range — typically 0.8x–1.3x for maintenance-focused businesses, up to 2.0x for businesses actively expanding their asset base — and ensure your planned Capex keeps the ratio within range. Annual visibility prevents the gradual drift that creates at-risk positions.','month_1','low','medium','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','at_risk',40,65,7,'Review depreciation rates for accuracy and compliance with SARS schedules','Work with your accountant to confirm that all assets are being depreciated at the correct rates per the SARS wear-and-tear schedule and your accounting policy. Under-depreciation inflates the book value of assets and understates the replacement requirement implied by depreciation. Accurate depreciation rates make your reinvestment ratio more meaningful as a management metric.','month_1_3','medium','medium','structure'),
  ('assetReinvestmentRatio','Asset Reinvestment','at_risk',40,65,8,'Benchmark reinvestment ratio against similar businesses in your sector','Research the typical Capex-to-depreciation ratios for businesses at your scale in your industry. Capital-intensive sectors require higher reinvestment ratios to maintain competitiveness; service businesses require lower ones. Benchmarking your at-risk ratio against sector norms tells you whether your position represents genuine under- or over-investment relative to peers.','month_1_3','low','medium','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','at_risk',40,65,9,'Model the operational risk of continued under-investment over three years','If your at-risk ratio reflects under-investment, model what your asset base will look like in three years if current Capex levels are maintained. Calculate the cumulative depreciation against replacement costs and identify the operational risk — equipment failures, technology obsolescence, and capacity constraints — that an ageing asset base creates.','month_1_3','medium','medium','risk'),
  ('assetReinvestmentRatio','Asset Reinvestment','at_risk',40,65,10,'Build a Capex funding plan to restore reinvestment ratio to the healthy range','Create a structured plan to bring your reinvestment ratio into the healthy 0.8x–1.5x range within 12–18 months. Identify the funding sources — retained earnings, asset finance, sale of surplus assets — and the Capex timing that will achieve the target ratio. Review progress annually against plan.','month_3_6','medium','medium','structure'),
  ('assetReinvestmentRatio','Asset Reinvestment','healthy',65,100,1,'Document your current Capex-to-depreciation baseline and target range','Record your current asset reinvestment ratio and establish a target range for your business — typically 0.8x–1.3x for stable maintenance-phase businesses, up to 2.0x for expansion-phase ones. Having a documented target range converts a healthy ratio from an accidental outcome into a managed position.','month_1','low','low','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','healthy',65,100,2,'Include asset reinvestment ratio in your annual Capex planning','Build the asset reinvestment ratio as an explicit output of your annual Capex budgeting process. Before finalising the Capex budget, calculate the resulting reinvestment ratio and confirm it is within your target range. This discipline prevents over- and under-investment from developing incrementally through annual budget decisions made without reference to the ratio.','month_1','low','medium','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','healthy',65,100,3,'Maintain a three-year rolling asset replacement schedule','Keep a live three-year asset replacement schedule that is reviewed and updated annually. The schedule should identify every significant asset, its estimated remaining useful life, replacement cost, and planned replacement year. A rolling schedule prevents the reinvestment ratio from being driven by asset failures rather than planned replacement.','month_1','medium','medium','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','healthy',65,100,4,'Assess whether technology upgrades can improve productivity per asset rand','When planning asset replacements, evaluate whether upgrading to higher-specification assets — incorporating automation, connectivity, or precision improvements — justifies a higher replacement cost through improved productivity. The additional investment above base replacement cost should be assessed against the incremental revenue or cost reduction it generates.','month_1_3','medium','medium','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','healthy',65,100,5,'Explore government incentives for qualifying capital investment','Research SEDA, IDC, dti, and sector-specific incentive programmes that could partially fund qualifying asset replacements or upgrades. Incentive-funded Capex reduces the effective cost of reinvestment and can allow a higher reinvestment ratio without proportionally higher Capex spending. Build incentive research into your annual Capex planning process.','month_1_3','medium','medium','cost'),
  ('assetReinvestmentRatio','Asset Reinvestment','healthy',65,100,6,'Balance asset reinvestment ratio against ROA and Capex intensity','Assess your asset reinvestment ratio alongside ROA and Capex intensity to ensure they tell a consistent story. A healthy reinvestment ratio combined with declining ROA suggests you are replacing assets without improving their productivity. Review the quality of reinvestment — not just the quantity — to ensure each replacement asset generates returns above your ROA target.','month_3_6','medium','medium','structure'),
  ('assetReinvestmentRatio','Asset Reinvestment','healthy',65,100,7,'Stress-test reinvestment requirements against a cash flow constraint','Model your asset replacement schedule under a scenario where OCF declined 30% for two years. Identify which planned replacements would be deferred first and whether those deferrals create unacceptable operational risk. This stress test tells you whether your current asset replacement plan is sustainable through a downturn without asset base deterioration.','month_3_6','low','medium','risk'),
  ('assetReinvestmentRatio','Asset Reinvestment','healthy',65,100,8,'Evaluate whether growth phase requires a higher reinvestment ratio','If your strategic plan includes significant revenue growth, model the asset investment required to support that growth. Growth that requires new production capacity, fleet, or infrastructure will require a reinvestment ratio above 1.5x during the investment phase. Plan for this explicitly in your Capex and funding strategy rather than discovering the cash need mid-growth.','month_3_6','medium','high','structure'),
  ('assetReinvestmentRatio','Asset Reinvestment','healthy',65,100,9,'Link reinvestment ratio to asset productivity in management reporting','Track asset reinvestment ratio alongside fixed asset productivity in your management reporting. A healthy reinvestment ratio combined with improving fixed asset productivity confirms that capital is being efficiently maintained and upgraded. A healthy ratio with declining asset productivity signals that replacement quality needs attention.','year_1','low','medium','operations'),
  ('assetReinvestmentRatio','Asset Reinvestment','healthy',65,100,10,'Include asset reinvestment strategy in your three-year strategic plan','Dedicate a section of your three-year strategic plan to capital maintenance and reinvestment strategy — setting target reinvestment ratios at each growth phase, identifying the funding sources, and linking asset investment to revenue productivity targets. Businesses that plan capital reinvestment strategically maintain more durable operational capacity than those that replace assets reactively.','year_1','medium','high','structure'),
  ('currentRatio','Cash Stability','critical',0,40,1,'Calculate your current ratio and assess insolvency risk immediately','Divide current assets by current liabilities to confirm your ratio. A current ratio below 1.0x means your current liabilities exceed your current assets — you are technically unable to meet short-term obligations from current resources. In South Africa, this is a legally significant position. Engage your accountant immediately to assess your directors'' obligations under the Companies Act.','immediate','low','high','risk'),
  ('currentRatio','Cash Stability','critical',0,40,2,'Build a 13-week cash flow forecast and identify cash exhaustion date','Create a week-by-week cash flow forecast for the next 13 weeks showing every confirmed receipt and committed payment. Identify the exact week when cash runs out if no additional action is taken. This date is your decision deadline — every recovery action must be initiated before that date to have any effect.','immediate','medium','high','cash'),
  ('currentRatio','Cash Stability','critical',0,40,3,'Contact your bank before missing any payment obligation','Call your bank immediately and disclose your current ratio and liquidity position. Banks have formal business support processes for clients in financial distress — and they are significantly more helpful to businesses that engage proactively than to those that miss payments first. Request an urgent meeting with your relationship manager and prepare a recovery plan before the call.','immediate','medium','high','structure'),
  ('currentRatio','Cash Stability','critical',0,40,4,'Accelerate all debtor collections with maximum urgency','Call every debtor with an outstanding balance personally and request immediate payment. Offer 2–3% discounts for payment within 48 hours on your five largest outstanding invoices. Apply for invoice discounting on your entire debtors book if immediate collection is insufficient. Each rand collected from debtors improves your current ratio directly by increasing current assets.','immediate','medium','high','cash'),
  ('currentRatio','Cash Stability','critical',0,40,5,'Negotiate deferral of all current liabilities with creditors immediately','Contact every supplier, lender, and creditor with amounts due in the next 90 days and request a deferral or payment arrangement. Each liability deferred beyond 12 months moves from current to non-current — directly improving your current ratio. Most creditors will negotiate rather than force a default that produces worse outcomes for them.','week_1_2','medium','high','structure'),
  ('currentRatio','Cash Stability','critical',0,40,6,'Convert short-term debt to long-term facilities to improve current ratio','Identify all short-term debt facilities — overdrafts, short-term loans, current portions of long-term debt — and request conversion to term facilities with repayment beyond 12 months. Every rand of short-term debt reclassified as long-term improves your current ratio by reducing current liabilities. This is the most effective structural improvement available without new capital.','week_1_2','medium','high','structure'),
  ('currentRatio','Cash Stability','critical',0,40,7,'Liquidate non-essential inventory and fixed assets for immediate cash','Sell all non-essential inventory at clearance pricing and dispose of any non-essential fixed assets. Converting assets to cash improves current assets directly. Selling non-current fixed assets and holding the proceeds as cash also improves the current ratio — proceeds are liquid current assets, while the sold fixed asset was non-current.','month_1','medium','high','cash'),
  ('currentRatio','Cash Stability','critical',0,40,8,'Seek emergency equity injection from shareholders','Contact all shareholders for an emergency equity injection. Equity increases current assets (cash) without increasing current liabilities — directly and immediately improving the current ratio. Even a modest injection that covers 60 days of operating requirements changes the trajectory of a critical current ratio from deteriorating to recovering.','month_1','high','high','structure'),
  ('currentRatio','Cash Stability','critical',0,40,9,'Engage a business rescue practitioner for a formal assessment','If your current ratio is below 1.0x and declining, engage a registered business rescue practitioner for a formal assessment. South Africa''s business rescue procedure under Chapter 6 of the Companies Act halts creditor actions, provides a structured recovery framework, and is far preferable to liquidation. Early engagement while value remains in the business is essential.','month_1','medium','high','risk'),
  ('currentRatio','Cash Stability','critical',0,40,10,'Build a 12-month current ratio recovery plan with monthly targets','Create a structured 12-month plan targeting a current ratio of at least 1.5x through cash generation, liability management, and capital injection. Set monthly current asset and current liability targets and review with your accountant at month-end. A written plan with monthly milestones is essential for coordinating the multiple simultaneous actions required to recover from a critical current ratio.','month_1_3','medium','high','structure'),
  ('currentRatio','Cash Stability','at_risk',40,65,1,'Calculate your current ratio and identify its weakest component','Divide current assets by current liabilities and identify which component is most responsible for the at-risk position — low cash, high debtors, large inventory, short-term debt maturing, or large trade payables. At-risk current ratios (1.0x–1.5x) are manageable but require targeted intervention on the specific driver rather than general liquidity management.','immediate','low','medium','cash'),
  ('currentRatio','Cash Stability','at_risk',40,65,2,'Arrange a working capital facility before the ratio deteriorates further','Apply for a revolving working capital facility or overdraft while your current ratio is still at-risk rather than critical. Banks approve facilities to businesses that need them as a contingency — not to businesses already in crisis. An approved facility improves your effective current ratio by providing committed liquidity that counts toward your financial resilience even if undrawn.','week_1_2','medium','high','structure'),
  ('currentRatio','Cash Stability','at_risk',40,65,3,'Accelerate debtor collections to increase current assets','Implement weekly debtors review and collection calls. Each rand collected from debtors increases current assets — improving the current ratio directly. A 15-day improvement in average debtor days on R5 million annual revenue releases approximately R205 000 in current assets. Target a 15-day debtor days improvement within 60 days.','week_1_2','medium','medium','cash'),
  ('currentRatio','Cash Stability','at_risk',40,65,4,'Renegotiate short-term debt to long-term to reduce current liabilities','Identify any short-term debt facilities or current portions of long-term debt that could be extended to longer terms. Converting short-term debt to long-term reduces current liabilities and directly improves the current ratio. Approach your lenders with a specific proposal — a 12-month extension of any current facility converts a current liability to a non-current one.','month_1','medium','medium','structure'),
  ('currentRatio','Cash Stability','at_risk',40,65,5,'Reduce inventory to minimum operational levels within 60 days','Set a target to reduce inventory by 15–20% within 60 days through tighter reorder points and clearance of aged stock. Reducing inventory does not directly improve the current ratio — both current assets and cash are affected — but it releases working capital that improves cash position and reduces the risk of inventory obsolescence adding to current liabilities through write-offs.','month_1','medium','medium','cash'),
  ('currentRatio','Cash Stability','at_risk',40,65,6,'Build OCF to generate cash and improve current position over 12 months','Focus on profitability and cash generation as the most sustainable route to a healthy current ratio. Every rand of positive OCF retained in the business increases current assets or reduces current liabilities. Set a monthly OCF target and direct all management energy toward achieving it. A current ratio is ultimately a function of accumulated cash generation over time.','month_1','medium','medium','cash'),
  ('currentRatio','Cash Stability','at_risk',40,65,7,'Track current ratio monthly alongside its component movements','Add current ratio to your monthly management accounts, broken into current assets and current liabilities with sub-components. Monthly visibility with a trend line allows you to see whether the ratio is improving or deteriorating and which component is driving the movement. At-risk ratios tracked monthly deteriorate less often than those reviewed only at year-end.','month_1','low','medium','operations'),
  ('currentRatio','Cash Stability','at_risk',40,65,8,'Avoid any new short-term debt commitments that would worsen the ratio','Set a policy that no new short-term debt facility will be taken on until the current ratio exceeds 1.8x. New short-term borrowing increases current liabilities and worsens the ratio. If additional funding is needed, pursue long-term facilities specifically — these do not impact the current portion of the ratio in the same way.','month_1_3','low','medium','risk'),
  ('currentRatio','Cash Stability','at_risk',40,65,9,'Stress-test current ratio against a collections and liability shock','Model your current ratio if your two largest debtors delayed payment by 60 days while a major supplier demanded early payment simultaneously. Identify the minimum current ratio under this scenario and pre-plan the liquidity actions you would take. Pre-planned responses to liquidity stress are faster and less costly than improvised ones.','month_1_3','low','medium','risk'),
  ('currentRatio','Cash Stability','at_risk',40,65,10,'Set a 12-month current ratio target of 1.8x with quarterly milestones','Define a 12-month target of reaching a 1.8x current ratio and build a plan of OCF generation, debt restructuring, working capital improvement, and capital management to achieve it. Set quarterly milestones and review with your accountant. A 1.8x current ratio provides meaningful operational buffer and removes the at-risk designation permanently if sustained.','month_3_6','medium','high','structure'),
  ('currentRatio','Cash Stability','healthy',65,100,1,'Document your current ratio baseline and target range','Record your current ratio and establish a target range — typically 1.5x–3.0x for most SMEs, where above 1.5x is secure and above 3.0x may indicate excess idle cash. Having a target range converts a healthy ratio from an accidental outcome into a managed position. Review annually and adjust the target as your business model evolves.','month_1','low','low','operations'),
  ('currentRatio','Cash Stability','healthy',65,100,2,'Use healthy current ratio to negotiate better banking facilities','Present your current ratio alongside profitability and cash flow metrics when renegotiating banking facilities. A healthy current ratio signals low short-term default risk to lenders — justifying better rates, higher limits, and more flexible terms. Request a formal facility review and use your liquidity position as a primary negotiating argument.','month_1','low','medium','structure'),
  ('currentRatio','Cash Stability','healthy',65,100,3,'Assess whether current ratio is too high due to excess idle cash','A current ratio significantly above 3.0x may indicate excess cash sitting in current accounts earning minimal return. If your ratio is high because of large uninvested cash balances, assess whether some surplus should be redeployed — into debt reduction, investment, or distributions — rather than held as idle current assets.','month_1','low','medium','cash'),
  ('currentRatio','Cash Stability','healthy',65,100,4,'Invest surplus current assets in yield-bearing short-term instruments','If your healthy current ratio is partly driven by large cash balances, ensure excess cash above your minimum operating buffer is invested in money market funds, notice deposits, or 32-day accounts earning 6–9% per year. Your healthy liquidity should be earning a return — not sitting idle in a current account.','month_1_3','low','medium','cash'),
  ('currentRatio','Cash Stability','healthy',65,100,5,'Stress-test current ratio against a simultaneous collections and liability shock','Model your current ratio if your three largest debtors delayed payment by 90 days while a major creditor demanded immediate payment. Identify the floor current ratio under this combined scenario and confirm it remains above 1.0x. Pre-planning the response to this scenario preserves your healthy ratio during adverse conditions.','month_1_3','low','medium','risk'),
  ('currentRatio','Cash Stability','healthy',65,100,6,'Model current ratio requirements at your next revenue milestone','Calculate the absolute current assets required to maintain your target current ratio at your next revenue milestone. Growth increases working capital requirements — more debtors, more inventory — and if not planned, can silently reduce your current ratio even as revenue improves. Plan the funding for this growth in advance.','month_3_6','medium','medium','cash'),
  ('currentRatio','Cash Stability','healthy',65,100,7,'Maintain a minimum cash buffer policy of one month fixed costs','Define a minimum cash balance policy — at least one month of total fixed costs held as a liquid cash reserve — and automate a monthly check against this threshold. This policy protects your current ratio from temporary cash shortfalls caused by delayed collections or unexpected expenses, maintaining operational resilience without a formal credit facility.','month_3_6','low','medium','cash'),
  ('currentRatio','Cash Stability','healthy',65,100,8,'Review current ratio seasonality and plan for low-liquidity periods','Most businesses experience seasonal variation in current ratio — higher after strong collection periods, lower after large supplier payment runs or tax payments. Map your typical seasonal pattern and ensure your minimum current ratio through the year stays above 1.5x. Pre-funding liquidity dips avoids short-term borrowing at adverse rates.','month_3_6','low','medium','risk'),
  ('currentRatio','Cash Stability','healthy',65,100,9,'Include current ratio in your annual board and shareholder reporting','Present your current ratio alongside profitability and debt metrics in annual board and shareholder reports. A consistently healthy current ratio demonstrates financial discipline and liquidity management to your stakeholders. Reporting it explicitly creates accountability for maintaining it and makes it a visible governance metric rather than an invisible accounting output.','year_1','low','medium','operations'),
  ('currentRatio','Cash Stability','healthy',65,100,10,'Build liquidity management into your three-year strategic plan','Include a liquidity strategy section in your three-year plan — setting target current ratio ranges at each revenue milestone, the working capital management and facility arrangements required to sustain them, and the minimum cash buffer policy. Liquidity management at three-year horizon is a CFO-level discipline that prevents the cash crises that undermine otherwise successful growth strategies.','year_1','medium','high','structure'),
  ('debtToEquity','Debt-to-Equity','critical',0,40,1,'Map every debt obligation with its cost, term, and security','List every debt facility — bank loans, overdrafts, asset finance, credit cards, shareholder loans, informal borrowings — with its outstanding balance, interest rate, monthly repayment, maturity date, and security provided. A critical debt-to-equity ratio is almost always obscured by complexity in the debt structure. Complete visibility of every obligation is the mandatory first step.','immediate','low','high','structure'),
  ('debtToEquity','Debt-to-Equity','critical',0,40,2,'Contact all lenders before any payment is missed','Call every lender within 48 hours and disclose your financial position honestly. Request urgent meetings to discuss restructuring options. Banks and other lenders have formal distress support processes — they are designed for businesses that engage proactively, not for those that default without warning. Every day of delay reduces the options available to you.','immediate','medium','high','structure'),
  ('debtToEquity','Debt-to-Equity','critical',0,40,3,'Apply for capital repayment holidays across all term debt','Formally apply for 3–6 month capital repayment holidays on all term debt facilities. This reduces monthly cash outflow immediately, buys time to restore profitability and cash generation, and signals to lenders that you are managing the situation proactively. Interest will continue to accrue during the holiday but principal relief is critical breathing space.','week_1_2','medium','high','cash'),
  ('debtToEquity','Debt-to-Equity','critical',0,40,4,'Halt all new borrowing with immediate effect','Issue an absolute prohibition on any new debt commitment — no new facilities, no increased limits, no informal loans. At a critical debt-to-equity ratio, every additional rand of debt deepens the problem exponentially. The only exceptions are refinancing arrangements that replace existing debt at lower rates or longer terms.','immediate','low','high','risk'),
  ('debtToEquity','Debt-to-Equity','critical',0,40,5,'Liquidate non-essential assets to repay highest-cost debt','Identify every asset not directly generating revenue and initiate a sale process within 30 days. Apply all proceeds to your highest-rate debt first. Asset-funded debt repayment reduces both the numerator and the denominator of your debt-to-equity ratio, with the net effect of improving equity solvency as well.','week_1_2','medium','high','cash'),
  ('debtToEquity','Debt-to-Equity','critical',0,40,6,'Convert shareholder loans to equity to improve ratio immediately','If the business has outstanding shareholder loans, negotiate their conversion to equity with immediate effect. Converting shareholder debt to equity reduces total debt, increases equity, and dramatically improves the debt-to-equity ratio without any cash movement. Shareholders converting loans become equity holders with no change in their economic exposure.','month_1','medium','high','structure'),
  ('debtToEquity','Debt-to-Equity','critical',0,40,7,'Seek emergency equity injection from existing or new investors','Contact all existing shareholders for an emergency equity contribution. If existing shareholders cannot or will not inject equity, explore external investors — strategic partners, private equity, or family offices — who might invest at an attractive valuation in exchange for an equity stake. Equity at this stage is dilutive but far preferable to insolvency.','month_1','high','high','structure'),
  ('debtToEquity','Debt-to-Equity','critical',0,40,8,'Explore debt-for-equity swaps with institutional lenders','Propose to your primary lender a debt-for-equity conversion — they receive equity in exchange for forgiving or reducing a portion of the debt. This directly and substantially improves your debt-to-equity ratio by simultaneously reducing debt and increasing equity. It is a well-established restructuring mechanism in South Africa and is available to businesses with credible recovery plans.','month_1_3','high','high','structure'),
  ('debtToEquity','Debt-to-Equity','critical',0,40,9,'Maximise profitability to rebuild equity through retained earnings','Direct all management energy toward improving net income and retaining every rand of profit in the business. Retained profit builds equity directly, improving the debt-to-equity ratio from the denominator. At a critical ratio, profitability is not a financial objective — it is a survival mechanism. Set a monthly net income target and review weekly.','month_1_3','high','high','revenue'),
  ('debtToEquity','Debt-to-Equity','critical',0,40,10,'Build a 24-month debt reduction and equity restoration roadmap','Create a structured 24-month plan mapping specific debt balance reductions from each facility, equity growth from retained earnings and injections, and quarterly debt-to-equity ratio milestones. Share this plan with all lenders to demonstrate commitment and secure their cooperation. A target of reaching a debt-to-equity ratio below 2.0x within 24 months should be your minimum ambition.','month_3_6','medium','high','structure'),
  ('debtToEquity','Debt-to-Equity','at_risk',40,65,1,'Calculate your exact debt-to-equity ratio and compare to sector norms','Confirm your current debt-to-equity ratio — total debt divided by total equity — and compare to your sector benchmark. Most healthy SMEs target a debt-to-equity ratio below 1.5x; capital-intensive businesses may target up to 2.5x. Knowing where you stand relative to sector norms gives you a specific improvement target and helps you understand the magnitude of the issue.','immediate','low','medium','structure'),
  ('debtToEquity','Debt-to-Equity','at_risk',40,65,2,'Set a debt reduction target of 15% within 12 months','Commit to reducing total debt by 15% within 12 months by directing monthly free cash flow above minimum repayments to your highest-rate facility first. A 15% debt reduction on a meaningful debt base combined with retained earnings growth can improve your debt-to-equity ratio by 0.3x–0.5x within a year — moving from at-risk toward healthy.','immediate','medium','medium','structure'),
  ('debtToEquity','Debt-to-Equity','at_risk',40,65,3,'Reduce distributions and retain earnings to build equity base','Set a policy of retaining at least 50–60% of net profit in the business for 12 months. Retained earnings directly increase equity, improving the debt-to-equity ratio from the denominator. Model the impact of a 12-month high-retention policy on your debt-to-equity ratio and share it with your accountant to confirm the trajectory is sufficient.','week_1_2','medium','medium','structure'),
  ('debtToEquity','Debt-to-Equity','at_risk',40,65,4,'Renegotiate your most expensive debt facility for a lower rate','Identify your highest-rate facility and request a rate reduction from your lender. Present your financial performance, payment history, and a plan showing how the debt will be reduced. A 1.5–2 percentage point rate reduction on your most expensive facility reduces interest cost and improves free cash flow available for debt repayment — accelerating your ratio improvement.','month_1','medium','medium','cost'),
  ('debtToEquity','Debt-to-Equity','at_risk',40,65,5,'Assess conversion of shareholder loans to equity','Review all shareholder loan accounts and assess whether converting them to equity is commercially viable. Shareholder loan conversion directly improves debt-to-equity by reducing the numerator and increasing the denominator simultaneously — the most capital-efficient ratio improvement available without new external capital.','month_1','medium','high','structure'),
  ('debtToEquity','Debt-to-Equity','at_risk',40,65,6,'Enforce a debt ceiling policy to prevent further deterioration','Define a maximum acceptable debt-to-equity ratio — typically 1.5x–2.0x for your sector — and enforce it as a governance policy. Any new borrowing that would breach this ceiling requires explicit owner or board approval with a documented repayment plan. This policy prevents the gradual borrowing drift that converts at-risk ratios to critical ones.','month_1','low','medium','risk'),
  ('debtToEquity','Debt-to-Equity','at_risk',40,65,7,'Track debt-to-equity monthly in management accounts','Add debt-to-equity ratio to your monthly management accounts. Monthly tracking with a trend line shows whether your deleveraging strategy is producing results and flags any unexpected increase. An at-risk debt-to-equity ratio tracked and managed monthly deteriorates less often than one reviewed only at year-end.','month_1','low','medium','operations'),
  ('debtToEquity','Debt-to-Equity','at_risk',40,65,8,'Explore SEFA or IDC refinancing to reduce cost and extend terms','Research whether the Small Enterprise Finance Agency or Industrial Development Corporation offer facilities that could replace your most expensive commercial debt at lower rates and longer terms. SEFA and IDC rates are typically 2–5% below commercial bank rates for qualifying SMEs. Lower rates and longer terms reduce monthly repayments and improve free cash flow for debt reduction.','month_1_3','high','medium','structure'),
  ('debtToEquity','Debt-to-Equity','at_risk',40,65,9,'Sell non-core assets to fund accelerated debt repayment','Identify assets not essential to revenue generation and initiate a disposal process, directing all proceeds to debt repayment. Asset-funded debt reduction improves the debt-to-equity ratio faster than income-funded reduction because disposal proceeds can be large relative to monthly OCF. Target the highest-rate facility for early repayment from asset sale proceeds.','month_1_3','medium','medium','cash'),
  ('debtToEquity','Debt-to-Equity','at_risk',40,65,10,'Build a 24-month deleveraging roadmap with quarterly milestones','Create a structured 24-month debt reduction plan with quarterly milestones showing the specific facility balances to be reduced, the funding sources — OCF and asset sales — and the resulting debt-to-equity ratio at each milestone. A target of reaching a debt-to-equity ratio below 1.5x within 24 months is realistic for most at-risk SMEs with stable operations.','month_3_6','medium','high','structure'),
  ('debtToEquity','Debt-to-Equity','healthy',65,100,1,'Document your debt structure and optimal leverage range','Record all debt facilities, your current debt-to-equity ratio, and your deliberate target range for leverage. A healthy debt-to-equity ratio that is not documented and governed can drift upward through individual borrowing decisions that each seem reasonable in isolation but are cumulatively damaging.','month_1','low','low','structure'),
  ('debtToEquity','Debt-to-Equity','healthy',65,100,2,'Use healthy leverage to negotiate better financing terms','Present your debt-to-equity ratio to your bank alongside your profitability metrics as evidence of low credit risk. A debt-to-equity ratio below 1.0x signals significant equity backing for every rand of debt — a strong negotiating position for rate reductions, higher facility limits, and less restrictive covenants. Request a formal facility review annually.','month_1','low','medium','structure'),
  ('debtToEquity','Debt-to-Equity','healthy',65,100,3,'Assess whether debt headroom can fund accretive growth investment','With a healthy debt-to-equity ratio, you have borrowing capacity that over-leveraged competitors do not. Identify one or two growth investments where debt-funded capital would generate ROE above your cost of capital. Disciplined use of your leverage headroom at this stage is a competitive advantage that should be deployed strategically rather than left unused.','month_1_3','medium','high','structure'),
  ('debtToEquity','Debt-to-Equity','healthy',65,100,4,'Enforce a maximum debt-to-equity ceiling as governance policy','Define a maximum acceptable debt-to-equity ratio and make it a formal governance policy requiring board or owner approval with a documented repayment plan before any borrowing that would breach the ceiling. This policy protects your healthy position from eroding through individually justified but cumulatively damaging borrowing decisions.','month_1_3','low','medium','risk'),
  ('debtToEquity','Debt-to-Equity','healthy',65,100,5,'Stress-test debt-to-equity against a profit decline and rate increase','Model your debt-to-equity ratio if net income declined 40% for two years while interest rates increased 200 basis points. Identify your debt-to-equity under this scenario and the specific actions you would take to prevent it reaching at-risk. Pre-planned stress responses preserve more financial options than improvised ones.','month_1_3','low','medium','risk'),
  ('debtToEquity','Debt-to-Equity','healthy',65,100,6,'Optimise your debt portfolio for cost and maturity','Review your complete debt portfolio for opportunities to reduce weighted average cost — refinancing high-rate facilities, fixing variable rates ahead of a rate cycle, or consolidating multiple small facilities. Also review maturity dates to ensure no more than 35–40% of debt matures in any single 12-month window. Optimised debt structure reduces cost and risk simultaneously.','month_3_6','medium','medium','structure'),
  ('debtToEquity','Debt-to-Equity','healthy',65,100,7,'Consider whether interest rate exposure should be hedged','Assess what percentage of your debt is on variable rates and model the impact of a 2–3% rate increase on your monthly interest expense and debt service coverage. If variable rate exposure is significant, consider fixing a portion of your debt at current rates through fixed-rate facilities or interest rate swaps. Rate certainty protects a healthy debt-to-equity from being undermined by a rate cycle.','month_3_6','medium','medium','risk'),
  ('debtToEquity','Debt-to-Equity','healthy',65,100,8,'Include debt-to-equity in your annual capital structure review','Make debt-to-equity a standing item in your annual strategic review — evaluated alongside ROE, interest coverage, and solvency. Assess whether your current leverage level is optimal for your growth stage and risk profile. Capital structure optimisation is a living discipline, not a one-time decision.','year_1','low','medium','structure'),
  ('debtToEquity','Debt-to-Equity','healthy',65,100,9,'Present debt-to-equity in shareholder reporting as a financial health indicator','Include debt-to-equity in your annual shareholder or board report alongside profitability and liquidity metrics. Shareholders who see that debt-to-equity is healthy and managed to a target range have greater confidence in the financial discipline of the business — particularly important if growth investments are being funded with debt.','year_1','low','medium','operations'),
  ('debtToEquity','Debt-to-Equity','healthy',65,100,10,'Build a three-year capital structure strategy aligned to growth and exit plans','Develop a three-year capital structure strategy defining your target debt-to-equity at each growth milestone, the funding mix for major investments, and the leverage at any planned capital event or exit. Businesses with explicit capital structure strategies achieve better valuations, better funding terms, and greater resilience than those that manage leverage reactively.','year_1','medium','high','structure'),
  ('debtToAssets','Debt-to-Assets','critical',0,40,1,'Assess your technical solvency with your accountant immediately','A critical debt-to-assets ratio means debt represents a very high proportion of your total asset base — your equity cushion is thin. Engage your accountant within 24 hours to assess whether the business meets the solvency test under the Companies Act. If liabilities exceed assets, directors have specific legal obligations that must be understood and fulfilled immediately.','immediate','low','high','risk'),
  ('debtToAssets','Debt-to-Assets','critical',0,40,2,'Stop all new borrowing with absolute immediate effect','Issue an absolute prohibition on any new debt commitment. At a critical debt-to-assets ratio, your existing debt already exceeds safe levels relative to your asset base. Additional borrowing reduces the equity buffer further and increases the probability of technical insolvency. No exceptions except refinancing that reduces total debt.','immediate','low','high','risk'),
  ('debtToAssets','Debt-to-Assets','critical',0,40,3,'Contact all lenders proactively to discuss restructuring','Call every lender within 48 hours and disclose your debt-to-assets position. Request emergency restructuring meetings. The earlier you engage, the more options both parties have. A debt-to-assets ratio above 80% with declining profitability is a signal that lenders will respond to more constructively before any default than after.','immediate','medium','high','structure'),
  ('debtToAssets','Debt-to-Assets','critical',0,40,4,'Liquidate non-essential assets to reduce debt','Identify every asset not actively generating revenue and initiate a disposal process within 30 days. Apply all proceeds to your highest-rate debt. Selling non-essential assets and repaying debt reduces both numerator and denominator of the ratio — but net debt reduction always improves debt-to-assets as long as assets are sold at or above book value.','week_1_2','medium','high','cash'),
  ('debtToAssets','Debt-to-Assets','critical',0,40,5,'Convert shareholder loans to equity to reduce debt immediately','Negotiate conversion of all shareholder loans to equity. This directly reduces total debt — the numerator of your ratio — without requiring any cash or asset movement. It also increases equity, improving solvency simultaneously. Shareholder loan conversion is the fastest and lowest-cost structural improvement available for a critical debt-to-assets ratio.','week_1_2','medium','high','structure'),
  ('debtToAssets','Debt-to-Assets','critical',0,40,6,'Explore emergency equity injection to recapitalise the balance sheet','Contact existing and potential new shareholders for an emergency equity injection. Equity increases assets (cash) without increasing debt — directly reducing your debt-to-assets ratio. At a critical ratio, even a modest injection that repays your most expensive facility changes the trajectory from deteriorating to recovering. Present a realistic recovery plan alongside the investment proposal.','month_1','high','high','structure'),
  ('debtToAssets','Debt-to-Assets','critical',0,40,7,'Maximise profitability and retain all earnings to rebuild equity','Direct every management decision toward maximising profitability and retaining every rand of net income in the business. Retained earnings increase equity directly, reducing the debt-as-a-proportion-of-assets ratio from the equity side. Stop all distributions, owner drawings, and discretionary spending until the ratio is below 70%.','month_1','high','high','revenue'),
  ('debtToAssets','Debt-to-Assets','critical',0,40,8,'Negotiate debt-for-equity conversions with institutional lenders','Propose debt-for-equity swaps to your primary lenders — they receive an equity stake in exchange for forgiving or reducing a portion of the outstanding debt. This directly reduces total debt, increases total equity, and improves the debt-to-assets ratio from both directions simultaneously. It is one of the most powerful structural tools available in a critical leverage crisis.','month_1_3','high','high','structure'),
  ('debtToAssets','Debt-to-Assets','critical',0,40,9,'Engage a business rescue practitioner if assets are insufficient to cover debts','If total liabilities exceed total assets, engage a registered business rescue practitioner immediately. South Africa''s Chapter 6 business rescue provides a structured framework for recovering a financially distressed business while protecting it from creditor actions. Early engagement — when value still exists in the business — produces significantly better outcomes than late engagement.','month_1_3','medium','high','risk'),
  ('debtToAssets','Debt-to-Assets','critical',0,40,10,'Build a 24-month debt reduction and equity restoration plan','Create a comprehensive 24-month plan targeting a debt-to-assets ratio below 60% through specific debt repayments, asset disposals, equity injections, and retained earnings growth. Set quarterly milestones and review with your accountant and lenders. A written recovery plan with milestones that all stakeholders can see dramatically improves cooperation and recovery outcomes.','month_3_6','medium','high','structure'),
  ('debtToAssets','Debt-to-Assets','at_risk',40,65,1,'Calculate your exact debt-to-assets ratio and benchmark it','Confirm your debt-to-assets ratio — total debt divided by total assets — and compare to your sector benchmark. A ratio of 40–60% is considered at-risk for most SMEs; below 40% is healthy. Knowing your specific position relative to sector norms tells you the magnitude of improvement required and helps set a realistic recovery target.','immediate','low','medium','structure'),
  ('debtToAssets','Debt-to-Assets','at_risk',40,65,2,'Set a debt reduction target of 15% within 12 months','Commit to reducing total debt by 15% through cash flow allocation above minimum repayments and targeted asset disposal proceeds. A 15% debt reduction on a meaningful debt base combined with equity growth through retained earnings can shift a debt-to-assets ratio from at-risk toward healthy within 12–18 months for most businesses with stable operations.','immediate','medium','medium','structure'),
  ('debtToAssets','Debt-to-Assets','at_risk',40,65,3,'Retain 60% of net profit to build equity and reduce ratio','Set a 12-month retention policy of keeping at least 60% of net profit in the business. Retained earnings increase equity, which reduces debt as a proportion of total assets. Model the debt-to-assets trajectory over 12 months at different retention rates and confirm the 60% target achieves your improvement goal within the timeframe.','week_1_2','medium','medium','structure'),
  ('debtToAssets','Debt-to-Assets','at_risk',40,65,4,'Sell non-essential assets to reduce debt','Identify assets not generating revenue and initiate disposal processes with proceeds directed to debt repayment. Selling non-essential assets at or above book value and applying proceeds to debt reduces the total debt faster than income-funded repayment alone — particularly effective for large asset categories like surplus property or unused equipment.','month_1','medium','medium','cash'),
  ('debtToAssets','Debt-to-Assets','at_risk',40,65,5,'Assess shareholder loan conversion to equity','Review all shareholder loan balances and assess whether converting them to equity is commercially viable. Conversion directly reduces the debt numerator and increases the equity denominator — the most efficient structural improvement for an at-risk debt-to-assets ratio. Formalise the conversion with proper legal documentation.','month_1','medium','high','structure'),
  ('debtToAssets','Debt-to-Assets','at_risk',40,65,6,'Enforce a maximum debt-to-assets ceiling as governance policy','Define a maximum acceptable debt-to-assets ratio — typically 50% for most SMEs — and make it a formal policy requiring documented approval before any borrowing that would breach it. This prevents the gradual incremental borrowing that converts at-risk positions to critical ones through a series of individually reasonable but cumulatively damaging decisions.','month_1','low','medium','risk'),
  ('debtToAssets','Debt-to-Assets','at_risk',40,65,7,'Track debt-to-assets monthly alongside equity solvency and leverage','Add debt-to-assets to your monthly management accounts alongside debt-to-equity and equity solvency. Monthly tracking of all three capital structure ratios together gives you the most complete picture of your balance sheet health trajectory. Include trend lines and compare to your targets at each review.','month_1','low','medium','operations'),
  ('debtToAssets','Debt-to-Assets','at_risk',40,65,8,'Renegotiate your most expensive debt facility for a lower rate','Identify your highest-rate debt facility and request a rate reduction. Lower interest rates reduce the effective cost of your debt and free cash flow for accelerated repayment. A 1–2% rate reduction on a significant facility can release R20 000–R50 000 in annual cash flow that is better directed to debt principal reduction.','month_1_3','medium','medium','cost'),
  ('debtToAssets','Debt-to-Assets','at_risk',40,65,9,'Explore whether a minority equity investor could improve the ratio','Assess whether a minority equity investor — private equity, angel, or strategic partner — could inject equity that accelerates your debt-to-assets recovery. An equity injection while the business is at-risk — not yet distressed — is typically achievable at a fair valuation. Waiting until critical makes equity raises significantly more expensive and dilutive.','month_3_6','high','high','structure'),
  ('debtToAssets','Debt-to-Assets','at_risk',40,65,10,'Build a 24-month capital structure improvement plan','Create a structured 24-month plan targeting a debt-to-assets ratio below 40% through specific debt reduction, asset management, and equity growth initiatives. Set quarterly milestones and review with your accountant. A written plan with milestones converts a general ambition to deleverage into a managed financial programme.','month_3_6','medium','high','structure'),
  ('debtToAssets','Debt-to-Assets','healthy',65,100,1,'Document your debt-to-assets ratio and set a target range','Record your current debt-to-assets ratio and establish a target range — typically 25–40% for a well-capitalised SME. A formal target range converts a healthy ratio from an accidental outcome into a managed position and provides a governance threshold for future borrowing decisions.','month_1','low','low','structure'),
  ('debtToAssets','Debt-to-Assets','healthy',65,100,2,'Use your strong balance sheet to access growth capital at favourable terms','A low debt-to-assets ratio is a compelling indicator to lenders that your assets are well-equity-backed and your borrowing capacity is underutilised. Present this metric in facility applications and negotiations. Businesses with low debt-to-assets consistently access larger facilities at lower rates than peers with higher leverage.','month_1','low','medium','structure'),
  ('debtToAssets','Debt-to-Assets','healthy',65,100,3,'Assess whether unused borrowing capacity should fund growth investments','With a healthy debt-to-assets ratio, you have unused debt capacity. Identify growth investments where debt-funded capital would generate returns above your cost of capital. Deliberately not using available debt capacity when ROI-positive opportunities exist is a form of capital inefficiency — your healthy balance sheet should be working for the business.','month_1_3','medium','high','structure'),
  ('debtToAssets','Debt-to-Assets','healthy',65,100,4,'Stress-test debt-to-assets against asset impairment and profit decline','Model your debt-to-assets ratio if assets declined 20% in value through impairment or market value reduction while net losses reduced equity. Identify your debt-to-assets under this scenario and the specific actions you would take. Pre-planned responses to asset value and equity shocks preserve financial health better than improvised reactions.','month_1_3','low','medium','risk'),
  ('debtToAssets','Debt-to-Assets','healthy',65,100,5,'Review asset valuations annually to ensure balance sheet accuracy','Work with your accountant to confirm that asset valuations on your balance sheet remain accurate — neither overstated nor understated. Overvalued assets produce an artificially low debt-to-assets ratio that masks true financial leverage. Accurate asset values give you and your stakeholders a reliable picture of actual balance sheet health.','month_1_3','medium','medium','structure'),
  ('debtToAssets','Debt-to-Assets','healthy',65,100,6,'Include debt-to-assets in your annual board and shareholder reporting','Present debt-to-assets alongside debt-to-equity and equity solvency in your annual board and shareholder report. Showing all three capital structure metrics together provides the most complete picture of balance sheet health and demonstrates financial discipline to all stakeholders.','month_3_6','low','medium','operations'),
  ('debtToAssets','Debt-to-Assets','healthy',65,100,7,'Maintain a debt ceiling policy to protect the ratio during growth','Enforce a maximum debt-to-assets ceiling of 50% as a standing governance policy. Any proposed borrowing that would breach this ceiling requires documented approval and a specific repayment plan. The ceiling protects your healthy ratio from the gradual drift that occurs when each individual borrowing decision seems reasonable but aggregate leverage accumulates.','month_3_6','low','medium','risk'),
  ('debtToAssets','Debt-to-Assets','healthy',65,100,8,'Optimise debt maturity profile to avoid refinancing concentration risk','Review the maturity profile of your debt portfolio and ensure no more than 35–40% matures in any single 12-month window. Stagger maturities by refinancing one facility early if concentration exists. Refinancing risk — where adverse credit conditions coincide with a maturity date — is the primary way a healthy debt-to-assets ratio becomes an at-risk one suddenly.','year_1','medium','medium','structure'),
  ('debtToAssets','Debt-to-Assets','healthy',65,100,9,'Align debt-to-assets strategy to your three-year growth and valuation plans','If you are planning to raise equity, attract investors, or sell the business in the next three years, model the debt-to-assets ratio that will maximise your valuation and funding options at that point. Businesses acquired or funded at debt-to-assets below 35% consistently command better terms and higher multiples than those carrying higher leverage.','year_1','medium','high','structure'),
  ('debtToAssets','Debt-to-Assets','healthy',65,100,10,'Build a three-year capital structure strategy addressing all leverage metrics','Create a three-year capital structure strategy that sets targets for debt-to-assets, debt-to-equity, and equity solvency simultaneously — with the debt management, equity retention, and asset strategy required to achieve each. Businesses that manage all three leverage dimensions as an integrated capital strategy achieve the most resilient and valuable balance sheets over time.','year_1','medium','high','structure')
on conflict (ratio_key, health_tier, step_number) do update set
  step_title = excluded.step_title,
  step_description = excluded.step_description,
  timeframe = excluded.timeframe,
  effort = excluded.effort,
  impact = excluded.impact,
  category = excluded.category;